CURSORS = {"open": "hand2", "grab": "fleur"}   # запасні - стандартні курсори Tk


def _cursor_cells(art):
    """'#' - контур, 'in' - заливка, None - прозоро (все, до чого можна дійти від краю)."""
    n = len(art)
    cells = [["#" if ch == "#" else "in" for ch in row] for row in art]
    stack = [(x, y) for y in range(n) for x in range(n) if (x in (0, n - 1) or y in (0, n - 1))]
    while stack:
        x, y = stack.pop()
        if 0 <= x < n and 0 <= y < n and cells[y][x] == "in":
            cells[y][x] = None
            stack += [(x + 1, y), (x - 1, y), (x, y + 1), (x, y - 1)]
    return cells


def _write_cur(path, art, hot, fill=(0, 0, 0), line=(0xff, 0xff, 0xff), size=32):
    """
    Записує 32-бітний .cur (Windows) з піксель-арту: чорна рука з білим контуром
    (видно і на світлих, і на темних клітинках). Малюнок 16x16 у звичайному полотні
    32x32 - курсор розміром як стандартна стрілка Windows, не більший.
    """
    import struct
    cells = _cursor_cells(art)
    n = len(art)
    xor = bytearray()
    mask = bytearray()
    for y in range(size - 1, -1, -1):              # рядки знизу вгору
        bits = 0
        for x in range(size):
            c = cells[y][x] if (y < n and x < n) else None
            if c is None:
                xor += b"\0\0\0\0"
                bits |= 1 << (size - 1 - x)
            else:
                r, g, b = line if c == "#" else fill
                xor += bytes((b, g, r, 255))
        mask += bits.to_bytes(size // 8, "big")
    img = struct.pack("<IiiHHIIiiII", 40, size, size * 2, 1, 32, 0, len(xor) + len(mask), 0, 0, 0, 0)
    data = img + bytes(xor) + bytes(mask)
    head = struct.pack("<HHH", 0, 2, 1) + struct.pack(
        "<BBBBHHII", size, size, 0, 0, hot[0], hot[1], len(data), 22)
    with open(path, "wb") as f:
        f.write(head + data)


def init_cursors(widget):
    """Створює курсори-руки у тимчасовій папці; якщо Tk їх не прийме - лишаються стандартні."""
    if sys.platform != "win32":
        return
    try:
        import tempfile
        folder = os.path.join(tempfile.gettempdir(), "chess_analyzer_cursors")
        os.makedirs(folder, exist_ok=True)
        for name, art in (("open", _HAND_OPEN), ("grab", _HAND_GRAB)):
            path = os.path.join(folder, f"hand_{name}.cur")
            _write_cur(path, art, (8, 8))
            spec = "@" + path.replace("\\", "/")
            if " " in spec:
                spec = "@{" + spec[1:] + "}"
            old = widget.cget("cursor")
            widget.configure(cursor=spec)               # перевірка: Tk зміг завантажити файл
            widget.configure(cursor=old)
            CURSORS[name] = spec
    except Exception:  # noqa: BLE001
        pass


# ---------------------------------------------------------- значки оцінки ---
# Значок якості ходу на дошці - картинка зі згладженими краями (без PIL): символи задані
# як векторні фігури в координатах кола радіуса 1 (y - вниз) і растеризуються з 4x4 вибірками.
#   ("cap", x1, y1, x2, y2, r) - товста лінія з круглими кінцями; ("dot", x, y, r) - коло;
#   ("poly", [(x, y), ...]) - многокутник.

def _g_excl(cx=0.0, s=1.0):
    return [("cap", cx, -0.50 * s, cx, 0.10 * s, 0.10 * s), ("dot", cx, 0.40 * s, 0.105 * s)]


def _g_quest(cx=0.0, s=1.0):
    pts = []
    for i in range(13):                               # дуга верхньої частини «?»
        a = math.radians(195 + i * 195 / 12)
        pts.append((cx + 0.24 * s * math.cos(a), -0.24 * s + 0.24 * s * math.sin(a)))
    pts += [(cx + 0.03 * s, 0.0), (cx, 0.12 * s)]       # до ніжки
    caps = [("cap", x1, y1, x2, y2, 0.09 * s) for (x1, y1), (x2, y2) in zip(pts, pts[1:])]
    return caps + [("dot", cx, 0.40 * s, 0.105 * s)]


def _g_star():
    pts = []
    for i in range(10):
        r = 0.60 if i % 2 == 0 else 0.25
        a = math.radians(-90 + i * 36)
        pts.append((r * math.cos(a), 0.05 + r * math.sin(a)))
    return [("poly", pts)]


BADGE_GLYPHS = {
    "!!": _g_excl(-0.23, 0.85) + _g_excl(0.23, 0.85),
    "!": _g_excl(),
    "★": _g_star(),
    "✓": [("cap", -0.42, 0.02, -0.13, 0.31, 0.115), ("cap", -0.13, 0.31, 0.43, -0.30, 0.115)],
    "+": [("cap", -0.42, 0.0, 0.42, 0.0, 0.115), ("cap", 0.0, -0.42, 0.0, 0.42, 0.115)],
    "Т": [("poly", [(-0.56, -0.34), (-0.06, -0.24), (-0.06, 0.46), (-0.56, 0.36)]),   # розгорнута книжка
          ("poly", [(0.56, -0.34), (0.06, -0.24), (0.06, 0.46), (0.56, 0.36)])],
    "?!": _g_quest(-0.22, 0.85) + _g_excl(0.27, 0.85),
    "?": _g_quest(),
    "??": _g_quest(-0.24, 0.85) + _g_quest(0.24, 0.85),
    "✕": [("cap", -0.33, -0.33, 0.33, 0.33, 0.115), ("cap", -0.33, 0.33, 0.33, -0.33, 0.115)],
}


def _in_glyph(shapes, x, y):
    for sh in shapes:
        kind = sh[0]
        if kind == "dot":
            _, cx, cy, r = sh
            if (x - cx) ** 2 + (y - cy) ** 2 <= r * r:
                return True
        elif kind == "cap":
            _, x1, y1, x2, y2, r = sh
            dx, dy = x2 - x1, y2 - y1
            ll = dx * dx + dy * dy
            t = 0.0 if ll == 0 else max(0.0, min(1.0, ((x - x1) * dx + (y - y1) * dy) / ll))
            px, py = x1 + t * dx - x, y1 + t * dy - y
            if px * px + py * py <= r * r:
                return True
        else:
            pts = sh[1]
            inside = False
            j = len(pts) - 1
            for i in range(len(pts)):
                xi, yi = pts[i]
                xj, yj = pts[j]
                if (yi > y) != (yj > y) and x < (xj - xi) * (y - yi) / (yj - yi) + xi:
                    inside = not inside
                j = i
            if inside:
                return True
    return False


def _png_rgba(w, h, rows):
    """Мінімальний PNG-кодувальник (RGBA, 8 біт) - без сторонніх бібліотек."""
    import struct
    import zlib
    raw = b"".join(b"\0" + bytes(r) for r in rows)

    def chunk(tag, data):
        return struct.pack(">I", len(data)) + tag + data + struct.pack(">I", zlib.crc32(tag + data))
    return (b"\x89PNG\r\n\x1a\n" + chunk(b"IHDR", struct.pack(">IIBBBBB", w, h, 8, 6, 0, 0, 0))
            + chunk(b"IDAT", zlib.compress(raw, 9)) + chunk(b"IEND", b""))


def _png_pal(w, h, rows, rgb, alpha):
    """PNG з палітрою з 2 кольорів: 0 - прозоро, 1 - rgb з прозорістю alpha (0-255). rows - байти 0/1 на піксель."""
    import struct
    import zlib
    raw = b"".join(b"\0" + bytes(r) for r in rows)

    def chunk(tag, data):
        return struct.pack(">I", len(data)) + tag + data + struct.pack(">I", zlib.crc32(tag + data))
    return (b"\x89PNG\r\n\x1a\n" + chunk(b"IHDR", struct.pack(">IIBBBBB", w, h, 8, 3, 0, 0, 0))
            + chunk(b"PLTE", b"\0\0\0" + bytes(rgb)) + chunk(b"tRNS", bytes((0, alpha)))
            + chunk(b"IDAT", zlib.compress(raw, 6)) + chunk(b"IEND", b""))


def _fill_polys(w, h, polys, rings=()):
    """Маска w x h (рядки bytearray 0/1): заповнені многокутники (scanline) і кільця (cx, cy, r_out, r_in)."""
    rows = [bytearray(w) for _ in range(h)]
    for poly in polys:
        edges = list(zip(poly, poly[1:] + poly[:1]))
        for y in range(h):
            yc = y + 0.5
            xs = sorted(x1 + (yc - y1) * (x2 - x1) / (y2 - y1)
                        for (x1, y1), (x2, y2) in edges if (y1 <= yc < y2) or (y2 <= yc < y1))
            for i in range(0, len(xs) - 1, 2):
                a, b = max(0, round(xs[i])), min(w, round(xs[i + 1]))
                if b > a:
                    rows[y][a:b] = b"\x01" * (b - a)
    for cx, cy, ro, ri in rings:
        for y in range(h):
            dy = abs(y + 0.5 - cy)
            if dy >= ro:
                continue
            xo = math.sqrt(ro * ro - dy * dy)
            if dy >= ri:
                spans = [(cx - xo, cx + xo)]
            else:
                xi = math.sqrt(ri * ri - dy * dy)
                spans = [(cx - xo, cx - xi), (cx + xi, cx + xo)]
            for xa, xb in spans:
                a, b = max(0, round(xa)), min(w, round(xb))
                if b > a:
                    rows[y][a:b] = b"\x01" * (b - a)
    return rows


def _png_decode(data):
    """Розпаковує PNG RGBA 8 біт (наші фігури) у рядки bytearray. Без сторонніх бібліотек."""
    import struct
    import zlib
    i, idat, w = 8, b"", 0
    while i < len(data):
        n = struct.unpack(">I", data[i:i + 4])[0]
        tag, body = data[i + 4:i + 8], data[i + 8:i + 8 + n]
        if tag == b"IHDR":
            w, h, bd, ct = struct.unpack(">IIBB", body[:10])
            if bd != 8 or ct != 6:
                raise ValueError("not RGBA8")
        elif tag == b"IDAT":
            idat += body
        i += 12 + n
    raw, s, rows, prev, p = zlib.decompress(idat), w * 4, [], bytearray(w * 4), 0
    for _y in range(h):
        f, line = raw[p], bytearray(raw[p + 1:p + 1 + s])
        p += 1 + s
        if f == 1:
            for x in range(4, s):
                line[x] = (line[x] + line[x - 4]) & 255
        elif f == 2:
            for x in range(s):
                line[x] = (line[x] + prev[x]) & 255
        elif f == 3:
            for x in range(s):
                line[x] = (line[x] + (((line[x - 4] if x >= 4 else 0) + prev[x]) >> 1)) & 255
        elif f == 4:
            for x in range(s):
                a = line[x - 4] if x >= 4 else 0
                b, c = prev[x], (prev[x - 4] if x >= 4 else 0)
                pp = a + b - c
                pa, pb, pc = abs(pp - a), abs(pp - b), abs(pp - c)
                line[x] = (line[x] + (a if pa <= pb and pa <= pc else b if pb <= pc else c)) & 255
        rows.append(line)
        prev = line
    return w, h, rows


PIECE_SCALE = 1.0          # картинка фігури = клітинка (1.18.5; у 1.18.4 було 1.1 - задумно і розмито)
_PIECE_SRC = {}
_PIECE_PNG = {}


def piece_png(code, size, alien=False):
    """Фігура code розміром size px: найбільша картинка (88 px), плавно масштабована (білінійно,
    з урахуванням прозорості). Кеш - бо дошка змінює розмір разом з вікном. alien - фігури-прибульці (1.26.8)."""
    key = (code, size, alien)
    if key in _PIECE_PNG:
        return _PIECE_PNG[key]
    src = _PIECE_SRC.get((code, alien))
    if src is None:
        import base64
        w, h, rows = _png_decode(base64.b64decode(ALIEN_PIECES[code] if alien else PIECE_DATA[max(PIECE_DATA)][code]))
        # попередньо помножена прозорість - щоб краї не темніли
        pm = []
        for r in rows:
            out = []
            for x in range(w):
                a = r[x * 4 + 3]
                out.append((r[x * 4] * a, r[x * 4 + 1] * a, r[x * 4 + 2] * a, a))
            pm.append(out)
        src = _PIECE_SRC[(code, alien)] = (w, h, pm)
    w, h, pm = src
    sx, sy = w / size, h / size
    n = max(1, math.ceil(sx))              # зменшення: кілька вибірок на піксель - чітко, без «сходинок»

    def taps(scale, lim, N):
        out = []
        for X in range(size):
            t = []
            for i in range(N):
                f = min(max((X + (i + 0.5) / N) * scale - 0.5, 0.0), lim - 1.0)
                x0 = int(f)
                t.append((x0, min(x0 + 1, lim - 1), f - x0))
            out.append(t)
        return out
    xs, ys = taps(sx, w, n), taps(sy, h, n)
    k = 1.0 / (n * n)
    out_rows = []
    for Y in range(size):
        row = bytearray()
        for xt in xs:
            R = G = B = A = 0.0
            for y0, y1, ty in ys[Y]:
                r0, r1 = pm[y0], pm[y1]
                for x0, x1, tx in xt:
                    p00, p01, p10, p11 = r0[x0], r0[x1], r1[x0], r1[x1]
                    w00, w01, w10, w11 = (1 - tx) * (1 - ty), tx * (1 - ty), (1 - tx) * ty, tx * ty
                    R += p00[0] * w00 + p01[0] * w01 + p10[0] * w10 + p11[0] * w11
                    G += p00[1] * w00 + p01[1] * w01 + p10[1] * w10 + p11[1] * w11
                    B += p00[2] * w00 + p01[2] * w01 + p10[2] * w10 + p11[2] * w11
                    A += p00[3] * w00 + p01[3] * w01 + p10[3] * w10 + p11[3] * w11
            if A * k < 0.5:
                row += b"\0\0\0\0"
                continue
            row += bytes((min(255, round(R / A)), min(255, round(G / A)), min(255, round(B / A)),
                          min(255, round(A * k))))
        out_rows.append(row)
    import base64
    data = _PIECE_PNG[key] = base64.b64encode(_png_rgba(size, size, out_rows)).decode("ascii")
    return data


_BADGE_CACHE = {}


def badge_image(symbol, color, size):
    """Кругла кольорова «таблетка» з білим символом, м'якою тінню і гладкими краями (PhotoImage)."""
    key = (symbol, color, size)
    if key in _BADGE_CACHE:
        return _BADGE_CACHE[key]
    import base64
    rows = badge_rows(symbol, color, size)
    img = tk.PhotoImage(data=base64.b64encode(_png_rgba(size, size, rows)).decode("ascii"))
    _BADGE_CACHE[key] = img
    return img


def badge_rows(symbol, color, size):
    """Пікселі значка: список рядків [r, g, b, a, r, g, b, a, ...]."""
    shapes = BADGE_GLYPHS[symbol]
    fr, fg, fb = (int(color[i:i + 2], 16) for i in (1, 3, 5))
    R, SH = 0.90, 0.07                     # радіус кола і зсув тіні (у частках половини картинки)
    n = 4                                   # 4x4 вибірки на піксель
    rows = []
    for py in range(size):
        row = []
        for px in range(size):
            acc_r = acc_g = acc_b = acc_a = 0.0
            for sy in range(n):
                for sx in range(n):
                    u = ((px + (sx + 0.5) / n) / size) * 2 - 1
                    v = ((py + (sy + 0.5) / n) / size) * 2 - 1
                    r = g = b = a = 0.0     # колір з передмноженою прозорістю
                    if u * u + (v - SH) ** 2 <= (R + 0.02) ** 2:          # тінь кола
                        a = 0.35
                    if u * u + v * v <= R * R:                           # саме коло
                        r, g, b, a = fr / 255, fg / 255, fb / 255, 1.0
                        gu, gv = u / R, v / R
                        if _in_glyph(shapes, gu, gv - 0.06):             # тінь символу
                            r, g, b = r * 0.72, g * 0.72, b * 0.72
                        if _in_glyph(shapes, gu, gv):                    # білий символ
                            r = g = b = 1.0
                    acc_r += r
                    acc_g += g
                    acc_b += b
                    acc_a += a
            k = n * n
            a = acc_a / k
            if a <= 0:
                row += (0, 0, 0, 0)
            else:
                row += (round(255 * min(1.0, acc_r / k / a)), round(255 * min(1.0, acc_g / k / a)),
                        round(255 * min(1.0, acc_b / k / a)), round(255 * a))
        rows.append(row)
    return rows


def dark_title_bar(win):
    """Темний заголовок вікна Windows у колір фону програми (замість білого)."""
    if sys.platform != "win32":
        return
    try:
        import ctypes
        win.update_idletasks()
        hwnd = ctypes.windll.user32.GetParent(win.winfo_id())
        dwm = ctypes.windll.dwmapi.DwmSetWindowAttribute

        def setattr_(attr, value):
            v = ctypes.c_int(value)
            return dwm(hwnd, attr, ctypes.byref(v), ctypes.sizeof(v))

        def colorref(hex_color):
            r, g, b = (int(hex_color[i:i + 2], 16) for i in (1, 3, 5))
            return r | (g << 8) | (b << 16)

        if setattr_(20, 1) != 0:          # DWMWA_USE_IMMERSIVE_DARK_MODE (Windows 10 2004+ / 11)
            setattr_(19, 1)               # старіші збірки Windows 10
        setattr_(35, colorref(BG))        # DWMWA_CAPTION_COLOR (Windows 11): точно колір фону
        setattr_(36, colorref(FG))        # DWMWA_TEXT_COLOR
    except Exception:  # noqa: BLE001
        pass


def open_engine(path):
    """Запускає Stockfish без чорного вікна консолі (у Windows)."""
    kwargs = {}
    if sys.platform == "win32":
        import subprocess
        kwargs["creationflags"] = subprocess.CREATE_NO_WINDOW
    return chess.engine.SimpleEngine.popen_uci(path, **kwargs)

