def bundled_engine():
    """Stockfish, який лежить поруч із програмою (папка stockfish/ або сама папка)."""
    exe_dir = os.path.dirname(os.path.abspath(
        sys.executable if getattr(sys, "frozen", False) else sys.argv[0]))
    bases = [exe_dir]
    if getattr(sys, "_MEIPASS", None):
        bases.append(sys._MEIPASS)
    for base in bases:
        for d in (os.path.join(base, "stockfish"), base):
            found = sorted(glob.glob(os.path.join(d, "stockfish*.exe")))
            if found:
                return found[0]
    return ""
