_XL_TPL, _XL_CACHE = None, {}


def _xl_templates():
    global _XL_TPL
    if _XL_TPL is None:
        _XL_TPL = []
        for en, tgt in I18N.items():
            if "{0}" not in en:
                continue
            parts = re.split(r"(\{\d\})", en)
            rx = "".join("(.*?)" if re.fullmatch(r"\{\d\}", p) else re.escape(p) for p in parts)
            _XL_TPL.append((re.compile(rx + "$", re.S), tgt))
    return _XL_TPL


def xl(en):
    """Англійський текст -> португальська / іспанська, якщо вибрана (інакше як є)."""
    lang = STATE.get("xl")
    if not lang or not isinstance(en, str) or not en:
        return en
    i = 0 if lang == "pt" else 1
    t = I18N.get(en)
    if t:
        return t[i]
    key = (lang, en)
    if key in _XL_CACHE:
        return _XL_CACHE[key]
    out = en
    for rx, tgt in _xl_templates():
        m = rx.match(en)
        if m:
            g = m.groups()
            g = [I18N[x][i] if x in I18N else x for x in g]     # підставлені слова теж (назви фігур)
            out = re.sub(r"\{(\d)\}", lambda mm: g[int(mm.group(1))] if int(mm.group(1)) < len(g) else mm.group(0), tgt[i])
            break
    if len(_XL_CACHE) < 5000:
        _XL_CACHE[key] = out
    return out


def ui_lang():
    """Мова інтерфейсу: uk / en / pt / es (для ШІ-тренера й налаштувань)."""
    return STATE.get("xl") or STATE["lang"]


def tr(uk):
    """Переклад рядка з українського оригіналу (для динамічних текстів)."""
    return xl(TR_EN.get(uk, uk)) if STATE["lang"] == "en" else uk


def trd(uk, en):
    """Переклад для заголовків діалогів (без спільного словника)."""
    return xl(en) if STATE["lang"] == "en" else uk


def pick(uk, en):
    return xl(en) if STATE["lang"] == "en" else uk


def changelog_view(cl=None):
    """«Що нового» для показу (користувач): підряд ідучі «Bugfix» або «Small fixes» після тієї самої версії X.Y.Z -
    один запис. Закрита серія - номер X.Y.Z.N за порядком (1, 2…); серія вгорі, що ще триває, - номер поточної версії.
    У CHANGELOG кожен реліз лишається окремо зі своїм справжнім номером (за ним програми порівнюють версії)."""
    cl = CHANGELOG if cl is None else cl
    out = []
    for v, d, items in cl:                                   # новіші зверху
        kind = items[0][0] if len(items) == 1 and items[0][0] in ("Bugfix", "Small fixes") else None
        base = ".".join(v.split(".")[:3])
        if kind and out and out[-1][3] == kind and out[-1][4] == base:
            continue                                          # та сама серія - уже показана новішим записом
        out.append([v, d, items, kind, base])
    counters, res = {}, []
    for i, (v, d, items, kind, base) in reversed(list(enumerate(out))):
        if kind:
            counters[base] = counters.get(base, 0) + 1
            if i:                                             # закрита серія - X.Y.Z.1, X.Y.Z.2…
                v = f"{base}.{counters[base]}"
        res.append((v, d, items))
    return res[::-1]


def ymd_to_ydm(s):
    """«2026-11-06 17:48» -> «2026-06-11 17:48»: у «Що нового» дата як рік-день-місяць (1.26.3, користувач)."""
    m = re.match(r"(\d{4})-(\d\d)-(\d\d)(.*)", s or "")
    return f"{m.group(1)}-{m.group(3)}-{m.group(2)}{m.group(4)}" if m else s


def qname(q):
    return xl(QUALITY_EN.get(q, q)) if STATE["lang"] == "en" else q


PNAME = {chess.PAWN: ("пішак", "pawn"), chess.KNIGHT: ("кінь", "knight"),
         chess.BISHOP: ("слон", "bishop"), chess.ROOK: ("тура", "rook"),
         chess.QUEEN: ("ферзь", "queen"), chess.KING: ("король", "king")}


def _pn(pt):
    uk, en = PNAME[pt]
    return en if STATE["lang"] == "en" else uk


# Знахідний відмінок для українських фраз «бере коня», «атакує туру».
PNAME_ACC = {chess.PAWN: ("пішака", "pawn"), chess.KNIGHT: ("коня", "knight"),
             chess.BISHOP: ("слона", "bishop"), chess.ROOK: ("туру", "rook"),
             chess.QUEEN: ("ферзя", "queen"), chess.KING: ("короля", "king")}


def _pa(pt):
    uk, en = PNAME_ACC[pt]
    return en if STATE["lang"] == "en" else uk


def _val(pt):
    return PIECE_VALUES.get(pt, 0)


def _hanging(board, sq):
    """Фігуру на sq можна вигідно взяти: її атакують, а захисту немає або атакує дешевша фігура."""
    p = board.piece_at(sq)
    if not p or p.piece_type == chess.KING:
        return False
    attackers = board.attackers(not p.color, sq)
    if not attackers:
        return False
    if not board.attackers(p.color, sq):
        return True
    return min(_val(board.piece_type_at(s)) or 99 for s in attackers) < _val(p.piece_type)


def _targets(board, sq):
    """Що реально атакує фігура на sq: король, дорожчі фігури і фігури без захисту."""
    me = board.piece_at(sq)
    out = []
    for t in board.attacks(sq):
        p = board.piece_at(t)
        if not p or p.color == me.color:
            continue
        if (p.piece_type == chess.KING or _val(p.piece_type) > _val(me.piece_type)
                or (p.piece_type != chess.PAWN and not board.attackers(p.color, t))):
            out.append((p.piece_type, t))
    return out


def _pv_moves(board, pv_uci, limit):
    """Легальні ходи головного варіанту рушія (не більше limit)."""
    b = board.copy(stack=False)
    moves = []
    for u in (pv_uci or [])[:limit]:
        try:
            mv = chess.Move.from_uci(u)
        except ValueError:
            break
        if not b.is_legal(mv):
            break
        moves.append(mv)
        b.push(mv)
    return moves


def _pv_text(board, pv_uci, plies=6):
    moves = _pv_moves(board, pv_uci, plies)
    return board.variation_san(moves) if moves else ""


def _pv_gain(board, pv_uci, color, base=4):
    """
    Скільки матеріалу виграє color за головним варіантом рушія: перші base півходів,
    а далі лише поки йдуть взяття (розмін доводимо до кінця). Глибше не дивимось -
    там варіант рушія ненадійний для висновків про матеріал.
    """
    moves = _pv_moves(board, pv_uci, 10)
    b = board.copy(stack=False)
    start = material_diff(b, color)
    for i, mv in enumerate(moves):
        if i >= base and not b.is_capture(mv):
            break
        b.push(mv)
    return material_diff(b, color) - start


PNAME_A = {chess.PAWN: ("пішака", "a pawn"), chess.KNIGHT: ("коня", "a knight"),
           chess.BISHOP: ("слона", "a bishop"), chess.ROOK: ("туру", "a rook"),
           chess.QUEEN: ("ферзя", "the queen"), chess.KING: ("короля", "the king")}


def _pv_trade(board, pv_uci, color, base=6):
    """Найдорожча фігура, яку бере color, і найдорожча, яку бере суперник (за тим самим варіантом)."""
    moves = _pv_moves(board, pv_uci, 10)
    b = board.copy(stack=False)
    took = {True: 0, False: 0}
    for i, mv in enumerate(moves):
        if i >= base and not b.is_capture(mv):
            break
        if b.is_capture(mv):
            vic = b.piece_at(mv.to_square)
            pt = vic.piece_type if vic else chess.PAWN
            side = b.turn == color
            if not took[side] or _val(pt) > _val(took[side]):
                took[side] = pt
        b.push(mv)
    return took[True], took[False]


def _gain_words(n):
    if n >= 9:
        return pick("ферзя", "the queen")
    if n >= 5:
        return pick("туру", "a rook")
    if n >= 3:
        return pick("фігуру", "a piece")
    if n == 2:
        return pick("два пішаки", "two pawns")
    return pick("пішака", "a pawn")


def move_facts(b, m):
    """Що робить хід m у позиції b (список коротких фраз). Порожній - якщо нічого помітного."""
    a = b.copy(stack=False)
    a.push(m)
    piece = b.piece_at(m.from_square)
    me = b.turn
    facts = []
    if b.is_castling(m):
        facts.append(pick("рокіровка: король у безпеці, тура активніша",
                          "castling: the king gets safety, the rook gets active"))
    if b.is_capture(m):
        vic = b.piece_at(m.to_square)
        vt = vic.piece_type if vic else chess.PAWN
        facts.append(pick(f"бере {_pa(vt)}", f"takes the {_pa(vt)}"))
    if a.is_checkmate():
        facts.append(pick("мат!", "checkmate!"))
        return facts
    if a.is_check():
        facts.append(pick("шах", "check"))
    if m.promotion:
        facts.append(pick("перетворення пішака", "pawn promotion"))
    if not piece:
        return facts

    tg = _targets(a, m.to_square)
    if len(tg) >= 2:
        names = [_pa(pt) for pt, _ in tg[:2]]
        facts.append(pick(f"вилка: атакує {names[0]} і {names[1]}",
                          f"fork: attacks the {names[0]} and the {names[1]}"))
    elif tg and tg[0][0] != chess.KING:
        pt, t = tg[0]
        facts.append(pick(f"атакує {_pa(pt)} на {chess.square_name(t)}",
                          f"attacks the {_pa(pt)} on {chess.square_name(t)}"))

    if piece.piece_type != chess.PAWN and _hanging(b, m.from_square) and not _hanging(a, m.to_square):
        facts.append(pick(f"відводить {_pa(piece.piece_type)} з-під удару",
                          f"moves the {_pa(piece.piece_type)} out of danger"))
    for sq, p in b.piece_map().items():
        if (p.color == me and sq != m.from_square and _hanging(b, sq) and not _hanging(a, sq)
                and m.to_square in a.attackers(me, sq)):
            facts.append(pick(f"захищає {_pa(p.piece_type)} на {chess.square_name(sq)}",
                              f"defends the {_pa(p.piece_type)} on {chess.square_name(sq)}"))
            break

    early = b.fullmove_number <= 10
    pt = piece.piece_type
    if pt in (chess.KNIGHT, chess.BISHOP) and chess.square_rank(m.from_square) in (0, 7) and early:
        facts.append(pick("розвиток фігури", "develops a piece"))
    if pt == chess.PAWN and m.to_square in (chess.E4, chess.D4, chess.E5, chess.D5):
        facts.append(pick("займає центр", "takes the center"))
    if pt == chess.PAWN and early and chess.square_file(m.from_square) in (5, 6):
        k = b.king(me)
        if k is not None and chess.square_file(k) == 4:     # король ще в центрі
            facts.append(pick("послаблює укриття короля", "weakens the king's shelter"))
    if pt == chess.QUEEN and b.fullmove_number <= 5 and not facts:
        facts.append(pick("ранній вихід ферзя: його можуть ганяти фігури суперника",
                          "early queen move: enemy pieces can chase it"))
    if pt == chess.KING and not b.is_castling(m) and not facts:
        facts.append(pick("хід короля", "king move"))
    return facts


def _book_note(row):
    """Рядок тренера про дебют: теорія, або відомий, але слабкий хід (як 2…f6 у захисті Даміано)."""
    if not (row.get("book") and row.get("opening")):
        return []
    if row.get("book_bad"):
        return [pick(f"📖 Хід є в дебютній теорії ({row['opening']}), але рушій вважає його слабким",
                     f"📖 This move is in opening theory ({row['opening']}), "
                     f"but the engine considers it weak")]
    return [pick(f"📖 Дебютна теорія: {row['opening']}", f"📖 Opening theory: {row['opening']}")]


def coach_lines(fen_before, uci, quality, best_san, pe_before, pe_after):
    """
    Пояснення ходу тренером на основі даних Stockfish:
    що робить хід, чому він поганий (за головним варіантом рушія), що було краще,
    і що загрожує зараз. Якість ходу й оцінку тренер не показує.
    """
    pe_before = pe_before or {}
    pe_after = pe_after or {}
    b = chess.Board(fen_before)
    m = chess.Move.from_uci(uci)
    san = b.san(m)
    me = b.turn
    a = b.copy(stack=False)
    a.push(m)

    facts = move_facts(b, m) or [pick("тихий хід", "quiet move")]
    lines = [f"{san}: " + "; ".join(facts)]
    if a.is_game_over():
        return lines

    pv_after = pe_after.get("pv") or ([pe_after["best"]] if pe_after.get("best") else [])
    if quality in BAD:
        cp = pe_after.get("cp", 0)
        my_cp = cp if me == chess.WHITE else -cp
        line = _pv_text(a, pv_after)
        head = pick("Чому неточно", "Why it's inaccurate") if quality == "Неточність" \
            else pick("Чому погано", "Why it's bad")
        moves6 = _pv_moves(a, pv_after, 6)
        checks = False
        t = a.copy(stack=False)
        for mv in moves6:
            if t.turn != me and t.gives_check(mv):
                checks = True
            t.push(mv)
        gain = _pv_gain(b, [uci] + pv_after, not me, base=6)   # від позиції до ходу: розмін - не виграш
        if my_cp <= -(MATE_SCORE - 100):
            why = pick("суперник ставить мат", "the opponent has a forced mate")
        elif gain >= 1:
            mine, theirs = _pv_trade(b, [uci] + pv_after, me)
            if mine and theirs and _val(theirs) > _val(mine):
                # «хід віддає коня лише за пішака» зрозуміліше, ніж «суперник виграє два пішаки»
                why = pick(f"хід віддає {PNAME_A[theirs][0]} лише за {PNAME_A[mine][0]}",
                           f"the move gives up {PNAME_A[theirs][1]} for just {PNAME_A[mine][1]}")
            else:
                why = pick(f"суперник виграє {_gain_words(gain)}", f"the opponent wins {_gain_words(gain)}")
        elif checks:
            why = pick("король стає вразливим", "the king becomes exposed")
        elif quality == "Пропуск":
            why = pick("перевага втрачена", "the advantage slips away")
        else:
            why = pick("суперник отримує кращу гру", "the opponent gets the better game")
        lines.append(f"{head}: {why}" + (f" — {line}" if line else ""))

        if best_san and best_san != san and pe_before.get("best"):
            try:
                best = chess.Move.from_uci(pe_before["best"])
            except ValueError:
                best = None
            details = []
            if best and b.is_legal(best):
                pv_best = pe_before.get("pv") or [pe_before["best"]]
                g = _pv_gain(b, pv_best, me)
                bcp = 0
                if pe_before.get("cp") is not None:
                    bcp = pe_before["cp"] if me == chess.WHITE else -pe_before["cp"]
                    if bcp >= MATE_SCORE - 100:
                        details.append(pick("веде до мату", "leads to mate"))
                # «виграє» - лише якщо рушій справді бачить перевагу (а не гамбіт суперника)
                if not details and g >= 1 and bcp >= 100:
                    details.append(pick(f"виграє {_gain_words(g)}", f"wins {_gain_words(g)}"))
                details += move_facts(b, best)
            txt = pick(f"Краще було {best_san}", f"Better was {best_san}")
            if details:
                txt += ": " + "; ".join(details[:2])
            lines.append(txt)
        return lines

    # хід нормальний - підказуємо, що задумав суперник
    if pv_after:
        try:
            r = chess.Move.from_uci(pv_after[0])
        except ValueError:
            r = None
        if r and a.is_legal(r):
            rs = a.san(r)
            c = a.copy(stack=False)
            c.push(r)
            gain = _pv_gain(b, [uci] + pv_after, not me)
            if c.is_checkmate():
                text = pick(f"Загроза мату: {rs}", f"Mate threat: {rs}")
            elif gain >= 1 and r.to_square == m.to_square and a.is_capture(r):
                # хід добрий, хоча фігуру/пішака одразу беруть: гамбіт або жертва
                text = pick(f"Жертва: після {rs} у суперника більше матеріалу, "
                            f"але рушій вважає хід добрим",
                            f"Sacrifice: after {rs} the opponent is up material, "
                            f"but the engine considers the move good")
            else:
                rf = move_facts(a, r)
                text = pick(f"Суперник, ймовірно, відповість {rs}", f"The opponent will likely reply {rs}")
                if rf:
                    text += f" ({'; '.join(rf[:2])})"
            lines.append(text)
    return lines


PIECE_VALUES = {chess.PAWN: 1, chess.KNIGHT: 3, chess.BISHOP: 3, chess.ROOK: 5, chess.QUEEN: 9}


# ---------------------------------------------------------------- логіка ---

WIN_K = 0.00368208   # lichess: Win% = 50 + 50 * (2 / (1 + exp(-0.00368208 * cp)) - 1)
RATING_K = (0.00033, 2.1e-6, 400, 2800)   # крутизна кривої для гравця з рейтингом: k0 + k1 * рейтинг (у цих межах)
# 1.29.3 (користувач): була (0.00195, 1.5e-6) - для ~1300 надто крута: 11.Ne5+ (Lotusnut, 0.00 -> -1.29) була «Помилкою», а
# на chess.com - «Неточність»; 8.Nxf7 (+0.38 -> -1.18) і 6.Neg5 лишаються «Помилками". Для 2700 крива та сама (0.006).
# Еталон therockymd (12.Ne5, 13…Bxb5, 20.Qf7 - «Груба», 20…h6/21…a6/22…h5 - «Пропуск») не змінився (cmp_curve.py).
# Точність (1.23.1) - сталі підібрано за числами самого chess.com: 323 партії гравців від 900 до 3400, для яких
# chess.com порахував точність (поле accuracies у його відкритому API). Середня розбіжність - 2.2 пункта
# (формула до 1.23.0 - 5.9, формула lichess без змін - 5.3); 74% партій - у межах 3 пунктів.
ACC_K = 0.0017       # крива шансів для точності (пологіша за криву оцінок і однакова для всіх рейтингів)
ACC_DECAY = 0.13     # точність ходу = 100 * exp(-ACC_DECAY * втрата шансів у %)
ACC_POWER = 0.35     # степінь середнього для точності партії (1 - звичайне середнє; менше - поганий хід важить більше)


def _logistic(cp: float, k: float) -> float:
    return 100.0 / (1.0 + math.exp(-k * cp))


def rating_k(rating=None) -> float:
    """
    Крутизна кривої шансів. Без рейтингу - стала lichess (підібрана на партіях гравців 2300).
    З рейтингом - як у chess.com (Expected Points залежить від рейтингу): новачок і з +4 часто не виграє,
    а майстру досить +1.5. Орієнтири (ту саму партію перевіряли з рейтингами 700 / 1600 / 2700):
    з -4.25 під мат - «Груба помилка» / «Помилка» / «Неточність», тобто шанси при +4.25 - до 80% / 80-90% / 90-95%.
    """
    if not rating:
        return WIN_K
    k0, k1, lo, hi = RATING_K
    return k0 + k1 * min(max(float(rating), lo), hi)


def expected_points(cp: float, rating=None) -> float:
    """
    Очікувані очки (0-100) за оцінкою рушія з точки зору гравця: логістична крива, як Win% у lichess,
    з крутизною за рейтингом гравця, як у chess.com. Мат = 100 / 0.
    """
    return _logistic(cp, rating_k(rating))


def win_percent(cp: float, rating=None) -> float:
    """Шанси на перемогу в % (для шкали й графіка - без рейтингу, формула lichess)."""
    return expected_points(cp, rating)


def lichess_win(cp: float) -> float:
    """Win% точно як у lichess: оцінка обмежена ±10 пішаками (мат - теж ±10), рейтинг не враховується."""
    return _logistic(max(-1000.0, min(1000.0, cp)), WIN_K)


WON_ANYWAY = 99.5      # очікувані очки, від яких вирішувати вже нічого (мат або близько +14 для рейтингу 1150)
# «Геніальний» дають лише там, де партія ще не виграна й без жертви. Новачкам chess.com щедріший: гравцеві з
# рейтингом 1144 він дав «!!» при +11, а про сильних пише, що після виграшу матеріалу жертви вже не геніальні.
# Тому межа - від 99.5 очікуваних очок (рейтинг до 1200) до 95 (від 2000; це близько +6); без рейтингу - як для 1500.
BRILLIANT_LIMIT = (99.5, 95.0, 1200, 2000, 1500)


def competitive_limit(rating=None) -> float:
    hi, lo, r0, r1, default = BRILLIANT_LIMIT
    r = float(rating) if rating else float(default)
    return hi - (hi - lo) * min(max((r - r0) / (r1 - r0), 0.0), 1.0)


GREAT_GAP = 5         # 1.25.6: «Чудовий» - другий хід рушія гірший щонайменше на стільки очікуваних очок
HARD_DEPTHS = (2, 4, 6)  # ...і рушій на цих малих глибинах (без хешу) хід не знаходить - його важко помітити
MISS_MATERIAL = 2      # 1.25.15: «Пропуск» - лише якщо найкращий хід вигравав стільки матеріалу (або мат)
BLUNDER_SURE = 30      # 1.25.13: «Груба помилка» без втрати матеріалу (> пішака) - лише якщо шанси впали на стільки (20.Qf7: виграш -> нічия)
BEST_TOLERANCE = 0.5   # % очікуваних очок: хід з меншою втратою - «Найкращий» (як рівноцінний)


def move_accuracy(cp_before: float, cp_after: float) -> float:
    """
    Точність ходу (0-100) за оцінками рушія до і після ходу (з точки зору гравця).
    Формула того ж виду, що в lichess (оцінка -> шанси -> втрата шансів -> експонента), але зі сталими,
    за яких точність партії збігається з chess.com (див. ACC_K).
    """
    loss = max(0.0, _logistic(cp_before, ACC_K) - _logistic(cp_after, ACC_K))
    return 100.0 * math.exp(-ACC_DECAY * loss)


def game_accuracy(accs) -> float:
    """Точність партії: степеневе середнє точностей ходів - поганий хід важить більше, ніж у звичайному середньому."""
    if not accs:
        return 0.0
    return (sum(max(1.0, a) ** ACC_POWER for a in accs) / len(accs)) ** (1.0 / ACC_POWER)


def material(board, color):
    return sum(PIECE_VALUES.get(p.piece_type, 0)
               for p in board.piece_map().values() if p.color == color)


def material_diff(board, color):
    return material(board, color) - material(board, not color)


def _zone(w):
    """0 - програшна, 1 - рівна, 2 - виграшна позиція (у % очікуваних очок)."""
    return 0 if w < 35 else (1 if w < 65 else 2)


def grade(drop, is_best, win_b, win_a, sacrifice, second_w, prev_drop, recapture,
          rating=None, missed_mate=False, sound_loss=None, endgame=False, hard=False):
    """
    Класифікація ходу за схемою chess.com Classification V2.
    drop - втрачені очікувані очки в % (межі 2/5/10/20 опубліковані chess.com).
    sacrifice - скільки матеріалу хід пропонує суперникові (sacrifice_amount); sound_loss - втрата шансів за
    шкалою lichess (для «Геніального»); endgame - чи це ендшпіль (is_endgame).
    second_w - очікувані очки після другого найкращого ходу рушія (або None).
    """
    generous = rating is not None and rating < 1200          # новачкам щедріше
    min_sac = 1      # 1.25.12: жертва фігури, навіть якщо за неї повертається до двох пішаків (14.Bxh6!! gxh6 Qxh6)
    # «навіть якби не знайшов хід»: без найкращого ходу лишився б другий варіант рушія, без іншого - найкращий
    baseline = second_w if (is_best and second_w is not None) else win_b

    # Геніальний (chess.com): добра жертва фігури чи якості; позиція після ходу не погана; без цього ходу партія
    # ще не була б повністю виграна; в ендшпілі - лише єдиний добрий хід. «Добра» - хід не гірший за «Добрий» і
    # майже не зменшує шансів за шкалою lichess (вона насичується на ±10, тому у вирішеній позиції жертва, після
    # якої перевага лишається вирішальною, - добра).
    # 1.23.1: chess.com дав «Геніальний» за 16.Bc4 (ферзь під боєм, +11 -> +9, рейтинг 1144); правило 1.21.1
    # («повністю виграна» вже від +4.5 і втрата до 2 очок за старою шкалою) такі ходи відкидало.
    if sound_loss is None:
        sound_loss = drop
    # 1.27.15 (ПРАВИЛО КОРИСТУВАЧА): «Геніальний» = жертва фігури + найкращий хід (найбільша перевага після нього).
    # Жодних порогів (втрата шансів, «позиція не погана», ендшпіль). Хід, рівноцінний найкращому, - у evaluate_move.
    if sacrifice >= min_sac and is_best:
        return "Геніальний"

    # Чудовий (1.25.6, правило користувача): найкращий хід, який дуже важко помітити - інші ходи помітно гірші,
    # а рушій на малій глибині його не бачить (hard, див. great_candidate / hard_to_find). Старе правило
    # («єдиний хороший хід») давало «!» за очевидні ходи: усі 37 таких у 30 партіях рушій бачив уже на глибині 2.
    if great_candidate(is_best, recapture, win_b, second_w) and hard:
        return "Чудовий"

    if is_best:
        return "Найкращий"
    if missed_mate:                      # був форсований мат, а хід його не залишив
        return "Пропуск"
    if drop <= 2:
        return "Відмінний"
    if drop <= 5:
        return "Добрий"
    if drop <= 10:
        base = "Неточність"
    elif drop <= 20:
        base = "Помилка"
    else:
        base = "Груба помилка"

    # 1.29.3 (користувач: «чому 7.Nxc6 - Пропуск?»): якщо хід зберіг помітну частину подарунка (понад чверть того, що
    # дала помилка суперника, і не менше 3 очок), це не «Пропуск», а звичайна оцінка. 7.Nxc6 (marwen_13): +0.73 -> +2.86
    # (6…g6?) -> +1.61 - збережено 5.8 з 13.5. Еталон 21…a6 (therockymd) - 5 з 39, лишається «Пропуском».
    if prev_drop >= 10 and win_a - (win_b - prev_drop) > max(3.0, 0.25 * prev_drop):
        return base
    # Пропуск: суперник помилився, можна було виграти, але перевага втрачена
    if prev_drop >= 10 and win_b >= 65 and win_a < 65 and win_a >= 35:
        return "Пропуск"
    # Пропуск (як у chess.com): суперник щойно помилився, а хід не покарав цю помилку
    # і повернув позицію приблизно туди, де вона була ДО помилки суперника.
    # Напр. 20.Qf7?? дає чорним 20…Rxd4 з нічиєю, а 20…h6 лишає їх у програшній позиції,
    # де вони й так були: це не нова «груба помилка», а пропущений подарунок.
    before_gift = win_b - prev_drop          # наші очікувані очки до помилки суперника
    if prev_drop >= 10 and win_a >= before_gift - 5:
        return "Пропуск"
    # Те саме за класом позиції (так «Пропуск» описує й chess.com: втрачено нагоду здобути кращу позицію):
    # помилка суперника перевела нас у кращий клас (програшна -> рівна чи виграшна, рівна -> виграшна), а хід
    # повернув туди, де ми були до неї. Без цього на кривій 1.23.1 ті самі 20…h6 і 22…h5 на глибинах 10-16
    # ставали «Грубою помилкою»: оцінка програшної позиції гуляє (-6.6 чи -7.0), а різниця в очках виходила за 5.
    if prev_drop >= 10 and _zone(win_b) > _zone(before_gift) and _zone(win_a) >= _zone(before_gift):
        return "Пропуск"
    return base


def great_candidate(is_best, recapture, win_b, second_w):
    """Чи може хід бути «Чудовим» (до перевірки, чи його важко помітити)."""
    return (is_best and not recapture and second_w is not None and win_b < WON_ANYWAY
            and win_b - second_w >= GREAT_GAP)


def hard_to_find(engine, board, move):
    """Хід важко помітити: рушій без хешу на глибинах HARD_DEPTHS обирає інший хід."""
    try:
        for d in HARD_DEPTHS:
            engine.configure({"Clear Hash": None})
            pv = engine.analyse(board, chess.engine.Limit(depth=d)).get("pv")
            if pv and pv[0] == move:
                return False
        return True
    except Exception:
        return False


def fmt_eval(cp_white: int) -> str:
    if abs(cp_white) >= MATE_SCORE - 100:
        n = MATE_SCORE - abs(cp_white)
        sign = "+" if cp_white > 0 else "-"
        return f"{sign}M{n}" if n else f"{sign}M"
    return f"{cp_white / 100:+.2f}"


def white_cp(info) -> int:
    return info["score"].white().score(mate_score=MATE_SCORE)


def _analyse(engine, board, limit):
    infos = engine.analyse(board, limit, multipv=2)
    return infos if isinstance(infos, list) else [infos]


def download_openings():
    """Завантажує a.tsv ... e.tsv з репозиторію lichess-org/chess-openings."""
    os.makedirs(OPENINGS_DIR, exist_ok=True)
    for letter in "abcde":
        path = os.path.join(OPENINGS_DIR, f"{letter}.tsv")
        if os.path.exists(path):
            continue
        with urllib.request.urlopen(OPENINGS_URL.format(letter), timeout=25) as resp:
            data = resp.read()
        with open(path, "wb") as f:
            f.write(data)


class BookDict(dict):
    """База дебютів: {EPD позиції: (ECO, назва) або None}. next_moves - теоретичні ходи з позиції."""

    def __init__(self):
        super().__init__()
        self.next_moves = {}


BOOK_CACHE = os.path.join(OPENINGS_DIR, "book_cache_v1.json")


def load_opening_book():
    """
    Словник {позиція (EPD): (ECO, назва) або None} і next_moves.
    Розбирати 3600 дебютів щоразу довго (~5 с, і при запуску це гальмувало вікно), тому готовий результат
    зберігається в book_cache_v1.json і наступного разу просто зчитується (~0,1 с).
    """
    tsvs = [os.path.join(OPENINGS_DIR, f"{l}.tsv") for l in "abcde"]
    try:
        newest = max(os.path.getmtime(p) for p in tsvs if os.path.exists(p))
        if os.path.getmtime(BOOK_CACHE) >= newest:
            with open(BOOK_CACHE, encoding="utf-8") as f:
                data = json.load(f)
            book = BookDict()
            for k, v in data["book"].items():
                book[k] = tuple(v) if v else None
            book.next_moves = {k: set(v) for k, v in data["next"].items()}
            if book:
                return book
    except (OSError, ValueError, KeyError):
        pass
    book = _parse_opening_book()
    try:
        tmp = BOOK_CACHE + ".tmp"
        with open(tmp, "w", encoding="utf-8") as f:
            json.dump({"book": {k: list(v) if v else None for k, v in book.items()},
                       "next": {k: sorted(v) for k, v in book.next_moves.items()}}, f, ensure_ascii=False)
        os.replace(tmp, BOOK_CACHE)
    except OSError:
        pass
    return book


def _parse_opening_book():
    """
    Будує словник {позиція (EPD): (ECO, назва) або None}.
    У словник потрапляють усі позиції вздовж кожної лінії (не лише кінцеві),
    тож кожен хід теорії розпізнається, а транспозиції теж.
    """
    book = BookDict()
    for letter in "abcde":
        path = os.path.join(OPENINGS_DIR, f"{letter}.tsv")
        if not os.path.exists(path):
            continue
        with open(path, encoding="utf-8") as f:
            for line in f:
                parts = line.rstrip("\n").split("\t")
                if len(parts) < 3 or parts[0].strip().lower() == "eco":
                    continue
                eco, name, pgn = parts[0], parts[1], parts[2]
                game = chess.pgn.read_game(io.StringIO(pgn))
                if game is None:
                    continue
                board = game.board()
                for mv in game.mainline_moves():
                    book.next_moves.setdefault(board.epd(), set()).add(mv.uci())
                    board.push(mv)
                    book.setdefault(board.epd(), None)
                book[board.epd()] = (eco, name)
    return book


def pos_eval(infos, req_depth=None):
    """Стислий опис позиції: оцінка (з точки зору білих), найкращий і другий варіанти рушія."""
    pv = infos[0].get("pv") or []
    return {
        "cp": white_cp(infos[0]),
        "best": pv[0].uci() if pv else None,
        "pv": [mv.uci() for mv in pv[:10]],   # головний варіант рушія (для тренера)
        "second": white_cp(infos[1]) if len(infos) > 1 else None,
        "depth": infos[0].get("depth"),     # глибина, яку Stockfish реально досяг
        "req_depth": req_depth,             # глибина, яку попросили
    }


_SEE_ORDER = {chess.PAWN: 1, chess.KNIGHT: 3, chess.BISHOP: 3, chess.ROOK: 5, chess.QUEEN: 9, chess.KING: 100}


def _see(board, sq):
    """
    Скільки матеріалу виграє сторона, чий хід, розміном на полі sq: щоразу бере найдешевшою фігурою
    (лише дозволені ходи - зв'язана фігура не бере, король не йде під шах) і може зупинитися, коли брати невигідно.
    """
    victim = board.piece_at(sq)
    if victim is None or victim.piece_type == chess.KING:
        return 0
    best = None
    for m in board.legal_moves:
        if m.to_square != sq or (m.promotion and m.promotion != chess.QUEEN):
            continue
        key = (_SEE_ORDER[board.piece_type_at(m.from_square)], m.from_square)
        if best is None or key < best[0]:
            best = (key, m)
    if best is None:
        return 0
    gain = PIECE_VALUES.get(victim.piece_type, 0) + (8 if best[1].promotion else 0)
    b = board.copy(stack=False)
    b.push(best[1])
    return max(0, gain - _see(b, sq))


def _best_capture(board):
    """Найбільше, що сторона, чий хід, може виграти одним розміном будь-де на дошці."""
    them = not board.turn
    best = 0
    for sq, p in board.piece_map().items():
        if p.color == them and p.piece_type != chess.KING and board.attackers(board.turn, sq):
            best = max(best, _see(board, sq))
    return best


def is_endgame(board):
    """Ендшпіль за правилом lichess: на дошці лишилось не більше шести фігур (без королів і пішаків)."""
    return sum(1 for p in board.piece_map().values() if p.piece_type not in (chess.PAWN, chess.KING)) <= 6


def sacrifice_amount(board, move, after, pv=None):
    """
    Скільки матеріалу хід жертвує (1.23.1, як «piece sacrifice» у chess.com): після ходу суперник може взяти
    ФІГУРУ (не пішака) і лишитися з матеріалом. Бере він чи ні - байдуже: відхилена жертва теж жертва
    (chess.com ставить «!!» і за туру, яку суперник раз за разом не бере).
    Не жертва:
    - розмін: фігуру забирають назад на тому ж полі або у відповідь беруть не менше деінде (_best_capture);
    - фігура, що висіла ще до ходу (хід її просто не врятував);
    - «втрата замість втрати»: фігура, що пішла, сама була під боєм, а тепер беруть іншу, не дорожчу;
    - те, що хід сам узяв, віднімається (взяв туру й віддав слона - не жертва).
    1.27.10 (користувач, 16.Rxe5!! fxe5 Nxf8): відіграш деінде рахується, лише якщо він був і до взяття; новий,
    який відкрило саме взяття (лінія, відволікання), - тактика жертви, а не розмін.
    """
    if board.is_check():
        return 0                               # вихід з-під шаху - вимушений хід, не жертва
    mover = board.turn
    if board.is_en_passant(move):
        gained = 1
    else:
        cap = board.piece_at(move.to_square)
        gained = PIECE_VALUES.get(cap.piece_type, 0) if cap else 0
    if move.promotion:
        gained += PIECE_VALUES.get(move.promotion, 0) - 1      # пішак став фігурою - це теж здобуток
    flipped = board.copy(stack=False)          # та сама позиція, але ходить суперник: що вже було під боєм
    flipped.turn = not mover
    flipped.ep_square = None
    risk_moved = None
    best = 0
    mine = after.copy(stack=False)             # після ходу знову ходить той, хто жертвує: що він уже може виграти
    mine.turn = mover
    mine.ep_square = None
    ready_cache = {}

    def ready(t):
        if t not in ready_cache:
            ready_cache[t] = _see(mine, t)
        return ready_cache[t]

    for sq, p in after.piece_map().items():
        if p.color != mover or p.piece_type in (chess.PAWN, chess.KING) or not after.attackers(not mover, sq):
            continue
        pre = 0
        if sq != move.to_square:
            if _see(flipped, sq) > 0:
                continue                       # висіла ще до ходу
            if risk_moved is None:
                risk_moved = _see(flipped, move.from_square)
            pre = risk_moved
        worst = 0
        for c in after.legal_moves:
            if c.to_square != sq or (c.promotion and c.promotion != chess.QUEEN):
                continue
            b = after.copy(stack=False)
            b.push(c)
            take = PIECE_VALUES.get(p.piece_type, 0) + (8 if c.promotion else 0)
            worst = max(worst, take - _regain(b, sq, ready))
        best = max(best, worst - gained - pre)
    return max(0, best)


def _regain(board, sq, ready):
    """Що сторона, чий хід, відіграє одним розміном після взяття на sq: на самому sq - усе, деінде - не більше,
    ніж можна було виграти й до взяття (ready)."""
    them = not board.turn
    best = 0
    for t, p in board.piece_map().items():
        if p.color == them and p.piece_type != chess.KING and board.attackers(board.turn, t):
            v = _see(board, t)
            best = max(best, v if t == sq else min(v, ready(t)))
    return best


def blunder_material(board, move, after, pe_before, pe_after, mover):
    """Скільки матеріалу хід втрачає порівняно з найкращим ходом (за варіантами рушія, як _pv_gain)."""
    best = _pv_gain(board, pe_before.get("pv") or [], mover, base=6)
    if after.is_game_over():
        played = material_diff(after, mover) - material_diff(board, mover)
    else:
        played = material_diff(after, mover) - material_diff(board, mover) \
            + _pv_gain(after, pe_after.get("pv") or [], mover, base=5)
    return best - played


NOT_EQUAL_CP = 100      # 1.29.3.1: позиція «не зрівнялась» - гірше більш ніж на пішака


DEEP_EXTRA = 10      # 1.30.1: наскільки глибше за вибрану глибину думати над ходом гравця у фоні
DEEP_MAX = 30


def evaluate_move(engine, limit, board, move, pe_before, prev_drop=0.0, prev_capture_sq=None,
                  rating=None, book_hit=False, check_hard=True, prev_bril=False):
    """
    Оцінює один хід. board - позиція ДО ходу (не змінюється), pe_before - pos_eval цієї позиції.
    Повертає (рядок з результатом, pos_eval позиції після ходу).
    Використовується і для аналізу партії, і для ходів, зроблених користувачем на дошці.
    """
    mover = board.turn
    sign = 1 if mover == chess.WHITE else -1
    before_m = sign * pe_before["cp"]
    best_move = chess.Move.from_uci(pe_before["best"]) if pe_before["best"] else None
    second_m = sign * pe_before["second"] if pe_before["second"] is not None else None

    best_san = board.san(best_move) if best_move else ""
    played_san = board.san(move)
    move_no = board.fullmove_number
    label = f"{move_no}." if mover == chess.WHITE else f"{move_no}…"

    d0 = material_diff(board, mover)
    is_cap = board.is_capture(move)
    recapture = is_cap and prev_capture_sq == move.to_square

    after = board.copy()
    after.push(move)
    sacrifice = 0
    if after.is_checkmate():
        pe_after = {"cp": MATE_SCORE if mover == chess.WHITE else -MATE_SCORE,
                    "best": None, "second": None}
    elif after.is_game_over():
        pe_after = {"cp": 0, "best": None, "second": None}
    else:
        pe_after = pos_eval(_analyse(engine, after, limit), limit.depth)
        sacrifice = sacrifice_amount(board, move, after, pe_after.get("pv"))

    after_m = sign * pe_after["cp"]
    win_b, win_a = win_percent(before_m, rating), win_percent(after_m, rating)
    drop = max(0.0, win_b - win_a)
    second_w = win_percent(second_m, rating) if second_m is not None else None
    loss = max(0, before_m - after_m)
    is_best = best_move is not None and move == best_move

    missed_mate = before_m >= MATE_SCORE - 100 and after_m < MATE_SCORE - 100
    sound_loss = max(0.0, lichess_win(before_m) - lichess_win(after_m))
    # check_hard=False (аналіз партії): перевірка пізніше, після всіх ходів - очищення хешу посеред аналізу
    # змінювало б оцінки наступних ходів
    great = great_candidate(is_best, recapture, win_b, second_w)
    hard = great and check_hard and hard_to_find(engine, board, move)
    quality = grade(drop, is_best, win_b, win_a, sacrifice, second_w,
                    prev_drop, recapture, rating, missed_mate, sound_loss, is_endgame(board), hard)
    # 1.22.2: хід, рівноцінний найкращому, - теж «Найкращий». На глибині 14 рушій інколи вагається між
    # двома ходами (12.Nxb5 / 12.dxc6: глибше Nxb5 - перший), тож різниця до 0.5 очікуваних очок - шум.
    # Якщо в оцінці мат і він став гіршим (довший свій або ближчий чужий) - це не «рівноцінний» хід.
    mate_worse = after_m < before_m and max(abs(before_m), abs(after_m)) >= MATE_SCORE - 100
    # 1.25.15 (користувач: 6…Be7 і 11.Ne5+ - не «Пропуск»): «Пропуск» лише якщо найкращий хід вигравав матеріал
    # (більше пішака) або мат, чи хід повернув позицію в гірший клас (20…h6: нічия -> програш); не покарати
    # суперника лише позиційно - звичайна оцінка за втратою
    if quality == "Пропуск" and not missed_mate \
            and _zone(win_a) >= _zone(win_b) \
            and blunder_material(board, move, after, pe_before, pe_after, mover) < MISS_MATERIAL \
            and max(abs(before_m), abs(after_m)) < MATE_SCORE - 100:
        quality = grade(drop, is_best, win_b, win_a, sacrifice, second_w, 0.0, recapture, rating, False,
                        sound_loss, is_endgame(board), hard)
    if quality == "Відмінний" and (after_m >= before_m or (drop <= BEST_TOLERANCE and not mate_worse)):
        quality = "Геніальний" if sacrifice >= 1 else "Найкращий"     # 1.27.15: рівноцінний найкращому - теж
    if quality == "Геніальний" and after_m <= -(MATE_SCORE - 100):
        quality = "Найкращий"     # 1.27.16 (користувач, 45.Rd7): мат буде в будь-якому разі - не «Геніальний»
    # 1.29.3.1: «не зрівнялась» - за оцінкою (гірше більш ніж на пішака), а не за % шансів: після м'якшої кривої
    # 1.29.3 14…Rf5 (-1.67, Lotusnut) вийшла з «програшної зони» і знову стала «!!»
    if quality == "Геніальний" and prev_bril and after_m < -NOT_EQUAL_CP:
        quality = "Чудовий"       # 1.29.2 (користувач): відповідь на «!!» суперника, а позиція не зрівнялась - «!»
    if quality == "Груба помилка" and drop < BLUNDER_SURE and blunder_material(board, move, after, pe_before, pe_after, mover) <= 1 \
            and max(abs(before_m), abs(after_m)) < MATE_SCORE - 100:
        quality = "Помилка"     # 1.25.13 (правило користувача): віддав пішака чи менше - «Помилка», не «Груба помилка»
    # Хід з бази дебютів - «Теорія», якщо він не зівок. У базі є й погані дебюти
    # (захист Даміано 2…f6): якщо рушій вважає хід помилкою і позиція після нього
    # гірша більш ніж на пішака, показуємо справжню оцінку рушія.
    # Гамбіти (королівський 2.f4: близько -0.6) лишаються теорією.
    book_bad = book_hit and quality in BAD and after_m < -BOOK_MAX_DEFICIT
    if book_bad:
        book_hit = False
    elif book_hit:
        quality = "Теорія"
    accuracy = 100.0 if book_hit else move_accuracy(before_m, after_m)

    row = {
        "label": label,
        "san": played_san,
        "uci": move.uci(),
        "best_uci": best_move.uci() if best_move else None,
        "best_san": best_san,
        "loss": int(loss),
        "quality": quality,
        "book": book_hit or book_bad,     # хід є в базі дебютів (назву дебюту показуємо)
        "book_bad": book_bad,             # ...але рушій вважає його слабким
        "opening": "",
        "fen": after.fen(),
        "acc": accuracy,
        "drop": 0.0 if book_hit else drop,
        "cap_sq": move.to_square if is_cap else None,
    }
    if great and not check_hard and quality == "Найкращий":
        row["_great"] = True
    # 1.29.2.1 (користувач): «!» (Чудовий) - не «пропущений геніальний»; і пропущеного немає там, де він був би лише «!»
    if quality not in ("Геніальний", "Чудовий", "Теорія") and not is_best \
            and missed_brilliant(board, pe_before, rating, prev_bril):
        row["missed_bril"] = True        # 1.26.6: тут був «Геніальний» хід (best_san), але зіграно інший
    return row, pe_after


def missed_brilliant(board, pe_before, rating=None, prev_bril=False):
    """1.26.6 (користувач): чи був найкращий хід рушія в цій позиції «Геніальним». Ті самі умови grade(), що й для
    зіграного ходу: найкращий хід нічого не втрачає (drop 0, позиція після = до), тож рушій не потрібен - лише
    жертва (sacrifice_amount за дошкою) і шанси до ходу."""
    if not pe_before or not pe_before.get("best"):
        return False
    mv = chess.Move.from_uci(pe_before["best"])
    if mv not in board.legal_moves:
        return False
    sign = 1 if board.turn == chess.WHITE else -1
    if sign * pe_before["cp"] <= -(MATE_SCORE - 100):
        return False                     # 1.27.16: мат у будь-якому разі - «Геніального» не було
    win_b = win_percent(sign * pe_before["cp"], rating)
    if prev_bril and sign * pe_before["cp"] < -NOT_EQUAL_CP:
        return False                     # 1.29.2.1: відповідь на «!!» у програшній позиції була б лише «!»
    second_w = win_percent(sign * pe_before["second"], rating) if pe_before.get("second") is not None else None
    after = board.copy(stack=False)
    after.push(mv)
    if after.is_game_over():
        return False
    sac = sacrifice_amount(board, mv, after)
    return grade(0.0, True, win_b, win_b, sac, second_w, 0.0, False, rating, False, 0.0,
                 is_endgame(board), False) == "Геніальний"


def analyze_game(game, engine_path, depth, progress=None, should_cancel=None, book=None):
    moves = list(game.mainline_moves())
    if not moves:
        raise ValueError(tr("У партії немає жодного ходу."))

    def _elo(tag):
        try:
            return int(game.headers.get(tag, ""))
        except ValueError:
            return None

    ratings = {chess.WHITE: _elo("WhiteElo"), chess.BLACK: _elo("BlackElo")}

    board = game.board()
    engine = open_engine(engine_path)
    limit = chess.engine.Limit(depth=depth)

    fens = [board.fen()]
    evals = []
    pos_info = []
    book_path = [bool(book)]       # чи лежить позиція на безперервному шляху теорії
    rows = []
    acc = {chess.WHITE: [], chess.BLACK: []}
    keys = list(QUALITY.keys())
    counts = {chess.WHITE: dict.fromkeys(keys, 0), chess.BLACK: dict.fromkeys(keys, 0)}

    try:
        pe_before = pos_eval(_analyse(engine, board, limit), depth)
        evals.append(pe_before["cp"])
        pos_info.append(pe_before)
        prev_drop = 0.0
        prev_capture_sq = None
        in_book = True
        opening = None

        for i, move in enumerate(moves):
            if should_cancel and should_cancel():
                raise RuntimeError(tr("Скасовано."))

            mover = board.turn

            # теорія: усі ходи підряд від початку партії, що лишаються в базі дебютів
            book_hit = False
            if in_book and book:
                tmp = board.copy(stack=False)
                tmp.push(move)
                key = tmp.epd()
                if key in book:
                    book_hit = True
                    if book[key]:
                        opening = book[key]
                else:
                    in_book = False

            row, pe_after = evaluate_move(engine, limit, board, move, pe_before,
                                          prev_drop, prev_capture_sq, ratings[mover], book_hit, False,
                                          bool(rows) and rows[-1]["quality"] == "Геніальний")
            if opening and book_hit:
                row["opening"] = f"{opening[0]} · {opening[1]}"
            # Правило: після ходу, що не є «Теорією» (зокрема поганого ходу з бази, як 2…f6
            # у захисті Даміано), наступні ходи вже не можуть бути «Теорією».
            still_book = row["quality"] == "Теорія"
            if not still_book:
                in_book = False
            book_path.append(still_book)
            board.push(move)

            fens.append(row["fen"])
            evals.append(pe_after["cp"])
            pos_info.append(pe_after)
            counts[mover][row["quality"]] += 1
            acc[mover].append(row["acc"])
            rows.append(row)

            prev_drop = row["drop"]
            prev_capture_sq = row["cap_sq"]
            pe_before = pe_after
            if progress:
                # знімок уже проаналізованих ходів (1.22.0): їх можна дивитися, поки аналіз іде далі
                part = {"fens": list(fens), "evals": list(evals), "pos_info": list(pos_info),
                        "moves": list(rows), "book_path": list(book_path), "depth": depth,
                        "summary": _game_summary(game, ratings, opening, acc, counts),
                        "partial": True, "total": len(moves)}
                progress(i + 1, len(moves), part)
        # «Чудовий» (1.25.6): найкращі ходи з великим розривом - чи важко їх помітити
        for i, row in enumerate(rows):
            if row.pop("_great", False) and hard_to_find(engine, chess.Board(fens[i]), moves[i]):
                mover = chess.WHITE if " w " in fens[i] else chess.BLACK
                counts[mover][row["quality"]] -= 1
                row["quality"] = "Чудовий"
                counts[mover]["Чудовий"] += 1
    finally:
        engine.quit()

    try:                                   # час на кожен хід (з годинника в PGN)
        spent = clock_spent(game)
    except Exception:  # noqa: BLE001
        spent = None
    if spent:
        for row, s in zip(rows, spent):
            row["spent"] = s

    summary = _game_summary(game, ratings, opening, acc, counts)
    out = {"fens": fens, "evals": evals, "pos_info": pos_info, "moves": rows,
           "summary": summary, "book_path": book_path, "depth": depth}
    clocks = [node.clock() for node in game.mainline()]     # 1.27.13: залишок годинника після кожного ходу
    if any(c is not None for c in clocks):
        m = re.match(r"(\d+)", game.headers.get("TimeControl", "").strip())
        out["clocks"], out["clk0"] = clocks, (float(m.group(1)) if m else None)
    return out


def clock_at(res, k, white):
    """Скільки часу лишалось у білих/чорних у позиції після k ходів (з [%clk]); None - невідомо."""
    clocks = res.get("clocks") if res else None
    if not clocks:
        return None
    t = res.get("clk0")
    for i in range(min(k, len(clocks), len(res["fens"]))):
        if clocks[i] is not None and (" w " in res["fens"][i]) == white:
            t = clocks[i]
    return t


def fmt_clock(sec):
    sec = max(0.0, float(sec))
    if sec < 20:
        return f"0:{sec:04.1f}"
    s = int(sec)
    return f"{s // 3600}:{s // 60 % 60:02d}:{s % 60:02d}" if s >= 3600 else f"{s // 60}:{s % 60:02d}"


def _game_summary(game, ratings, opening, acc, counts):
    """Підсумок партії: імена, рейтинги, дебют, точність і кількість ходів кожної якості."""
    avg = game_accuracy

    h = game.headers
    return {
        "white": h.get("White", "Білі"),
        "black": h.get("Black", "Чорні"),
        "white_elo": h.get("WhiteElo", ""),
        "black_elo": h.get("BlackElo", ""),
        "result": h.get("Result", "*"),
        "opening": opening,
        "white_rating": ratings[chess.WHITE],
        "black_rating": ratings[chess.BLACK],
        "white_acc": avg(acc[chess.WHITE]),
        "black_acc": avg(acc[chess.BLACK]),
        "white_counts": dict(counts[chess.WHITE]),
        "black_counts": dict(counts[chess.BLACK]),
    }


def best_was(m):
    """Пояснення до ходу, що не найкращий (1.22.1): який хід був найкращим. Для поганих - ще й втрата."""
    if not m.get("best_san") or m.get("book") or m["quality"] in ("Найкращий", "Геніальний", "Чудовий", "Теорія"):
        return ""
    if m["quality"] in BAD:
        return f"  {tr('Краще було')} {m['best_san']} ({tr('втрата')} {m['loss'] / 100:.2f})"
    if m["best_san"] == m["san"]:
        return ""
    return "  " + pick(f"Найкращий хід: {m['best_san']}", f"Best move: {m['best_san']}")


def to_move(fen):
    """«Хід білих» / «Хід чорних» - щоб порада рушія не читалась як заміна щойно зіграного ходу."""
    white = " w " in fen
    return pick("Хід білих" if white else "Хід чорних", "White to move" if white else "Black to move")


# ------------------------------------------------------------ ШІ-тренер ---
# З 1.23.2: пояснення ходу живою мовою від відкритої моделі (Gemma 4 від Google) на безплатному Cloudflare Workers AI.
# Програма шле лише факти, які вже порахував Stockfish (хід, висновок рушія, варіанти, матеріал, пункти тренера),
# а модель їх переказує. Ключів у програмі немає: посередник (scratchpad\aiworker) тримає доступ до моделі в себе.
# Немає інтернету, вичерпано денний ліміт або помилка - показується звичайний тренер.
AI_COACH_URL = "https://chess-analyzer-coach.chessanalyzer.workers.dev"

_AI_VERDICT = {
    "Геніальний": ("сильна жертва: хід віддає матеріал, але це найкращий або майже найкращий хід, і позиція лишається доброю",
                   "a strong sacrifice: the move gives up material, but it is the best or nearly best move and the position stays good"),
    "Чудовий": ("найкращий хід, який дуже важко помітити (інші ходи помітно гірші)",
                "the best move, and a very hard one to spot (other moves are clearly worse)"),
    "Найкращий": ("найкращий хід", "the best move"),
    "Відмінний": ("дуже добрий хід, майже такий самий, як найкращий", "a very good move, almost as good as the best one"),
    "Добрий": ("непоганий хід, але був трохи кращий", "a decent move, but there was a slightly better one"),
    "Теорія": ("відомий дебютний хід", "a known opening move"),
    "Неточність": ("неточний хід: частина переваги втрачається", "an inaccurate move: part of the advantage is lost"),
    "Помилка": ("помилковий хід: позиція помітно погіршується", "a mistake: the position gets clearly worse"),
    "Груба помилка": ("груба помилка: позиція сильно погіршується", "a serious error: the position gets much worse"),
    "Пропуск": ("пропущена нагода: суперник щойно помилився, а цей хід цим не скористався",
                "a missed chance: the opponent just erred, and this move did not take advantage of it"),
}


def _moves_word(n):
    """1 хід, 2 ходи, 5 ходів."""
    if n % 10 == 1 and n % 100 != 11:
        return "хід"
    if 2 <= n % 10 <= 4 and not 12 <= n % 100 <= 14:
        return "ходи"
    return "ходів"


def _pv_captures(board, pv_uci, base=4):
    """Що забирає кожна сторона за варіантом рушія (те саме вікно, що й _pv_gain): {колір: [тип фігури, ...]}."""
    took = {chess.WHITE: [], chess.BLACK: []}
    b = board.copy(stack=False)
    for i, mv in enumerate(_pv_moves(board, pv_uci, 10)):
        cap = b.is_capture(mv)
        if i >= base and not cap:
            break
        if cap:
            took[b.turn].append(chess.PAWN if b.is_en_passant(mv) else b.piece_type_at(mv.to_square))
        b.push(mv)
    return took


def ai_facts(fen_before, uci, quality, best_san, pe_before, pe_after):
    """Факти для ШІ-тренера (мовою інтерфейсу): усе - з даних Stockfish, щоб модель нічого не вигадувала."""
    pe_before, pe_after = pe_before or {}, pe_after or {}
    b = chess.Board(fen_before)
    m = chess.Move.from_uci(uci)
    me = b.turn
    san = b.san(m)
    a = b.copy(stack=False)
    a.push(m)
    side = pick("білі", "White") if me == chess.WHITE else pick("чорні", "Black")
    out = [pick(f"Ходять {side}. Зіграний хід: {san}.", f"{side} to move. Move played: {san}.")]
    if quality in _AI_VERDICT:
        out.append(pick("Висновок рушія про хід: ", "Engine's verdict on the move: ") + pick(*_AI_VERDICT[quality]) + ".")
    if a.is_checkmate():
        out.append(pick("Хід ставить мат.", "The move gives checkmate."))
        return "\n".join(out)
    cp = pe_after.get("cp")
    if cp is not None:
        my = cp if me == chess.WHITE else -cp
        if abs(my) >= MATE_SCORE - 100:
            n = max(1, MATE_SCORE - abs(my))
            w = pick(f"{side} ставлять мат за {n} {_moves_word(n)}", f"{side} can force mate in {n}") if my > 0 else \
                pick(f"суперник ставить мат за {n} {_moves_word(n)}", f"the opponent can force mate in {n}")
        elif abs(my) < 50:
            w = pick("приблизно рівна", "roughly equal")
        else:
            lead = abs(my)
            size = pick("невелика", "a small") if lead < 150 else pick("помітна", "a clear") if lead < 400 else \
                pick("вирішальна", "a decisive")
            who = pick("у білих" if me == chess.WHITE else "у чорних", side) if my > 0 else \
                pick("у суперника", "the opponent")
            w = pick(f"{size} перевага {who}", f"{size} advantage for {who}")
        out.append(pick("Позиція після ходу: ", "Position after the move: ") + w + ".")
    pv_after = pe_after.get("pv") or ([pe_after["best"]] if pe_after.get("best") else [])
    if pv_after:
        line = _pv_text(a, pv_after, 8)
        if line:
            out.append(pick("Варіант рушія після ходу: ", "Engine line after the move: ") + line + ".")
            took = _pv_captures(a, pv_after)

            def names(types):
                return ", ".join(pick(*PNAME_A[t]) for t in types)
            if took[me] or took[not me]:
                parts = []
                if took[not me]:
                    parts.append(pick(f"суперник забирає {names(took[not me])}", f"the opponent takes {names(took[not me])}"))
                if took[me]:
                    parts.append(pick(f"{side} забирають {names(took[me])}", f"{side} take {names(took[me])}"))
                out.append(pick("За цим варіантом ", "In this line ") + pick("; ", "; ").join(parts) + ".")
    pv_before = pe_before.get("pv") or []
    if best_san and best_san != san and quality not in ("Найкращий", "Геніальний", "Чудовий", "Теорія"):
        line = (_pv_text(b, pv_before, 6) if pv_before else "") or best_san
        out.append(pick(f"Найкращий хід рушія був {best_san} (варіант: {line}).",
                        f"The engine's best move was {best_san} (line: {line})."))
    try:
        coach = coach_lines(fen_before, uci, quality, best_san, pe_before, pe_after)
        if coach:
            out.append(pick("Що помітив тренер:", "What the coach noticed:") + "\n" + "\n".join(coach))
    except Exception:  # noqa: BLE001
        pass
    return "\n".join(out)[:2400]


_PNAME_N = {chess.PAWN: ("пішак", "pawn"), chess.KNIGHT: ("кінь", "knight"), chess.BISHOP: ("слон", "bishop"),
            chess.ROOK: ("тура", "rook"), chess.QUEEN: ("ферзь", "queen"), chess.KING: ("король", "king")}


def ask_facts(fen, pe, sans=(), last=None):
    """Факти про позицію для запитання до ШІ-тренера (1.23.5): фігури, оцінка рушія словами, найкращий хід
    з варіантом, можливі ходи, ходи партії і (якщо є) факти про останній хід."""
    pe = pe or {}
    b = chess.Board(fen)
    white = b.turn == chess.WHITE
    out = [pick("Позиція (FEN): ", "Position (FEN): ") + fen,
           pick("Ходять білі." if white else "Ходять чорні.", "White to move." if white else "Black to move.")]
    for color in (chess.WHITE, chess.BLACK):
        parts = []
        for pt in (chess.KING, chess.QUEEN, chess.ROOK, chess.BISHOP, chess.KNIGHT, chess.PAWN):
            sq = [chess.square_name(s) for s in b.pieces(pt, color)]
            if sq:
                parts.append(pick(*_PNAME_N[pt]) + " " + ", ".join(sq))
        out.append(pick("Білі: " if color == chess.WHITE else "Чорні: ",
                        "White: " if color == chess.WHITE else "Black: ") + "; ".join(parts) + ".")
    if b.is_checkmate():
        out.append(pick("Це мат.", "This is checkmate."))
    elif b.is_stalemate():
        out.append(pick("Це пат (нічия).", "This is stalemate (a draw)."))
    elif b.is_check():
        out.append(pick("Король під шахом.", "The king is in check."))
    cp = pe.get("cp")
    if cp is not None and not b.is_game_over():
        if abs(cp) >= MATE_SCORE - 100:
            n = max(1, MATE_SCORE - abs(cp))
            who = pick("білі" if cp > 0 else "чорні", "White" if cp > 0 else "Black")
            w = pick(f"{who} ставлять мат за {n} {_moves_word(n)}", f"{who} can force mate in {n}")
        elif abs(cp) < 50:
            w = pick("приблизно рівна", "roughly equal")
        else:
            size = pick("невелика", "a small") if abs(cp) < 150 else pick("помітна", "a clear") if abs(cp) < 400 else \
                pick("вирішальна", "a decisive")
            w = pick(f"{size} перевага {'білих' if cp > 0 else 'чорних'}",
                     f"{size} advantage for {'White' if cp > 0 else 'Black'}")
        out.append(pick("Оцінка Stockfish: ", "Stockfish evaluation: ") + w + ".")
    pv = pe.get("pv") or ([pe["best"]] if pe.get("best") else [])
    if pv and not b.is_game_over():
        line = _pv_text(b, pv, 10)
        if line:
            first = _pv_moves(b, pv, 1)
            out.append(pick("Найкращий хід за Stockfish: ", "Stockfish's best move: ") + b.san(first[0]) + ". " +
                       pick("Варіант рушія: ", "Engine line: ") + line + ".")
    legal = [b.san(m) for m in b.legal_moves]
    if legal:
        out.append(pick("Можливі ходи: ", "Legal moves: ") + ", ".join(legal[:60]) + ".")
    if sans:
        sans = list(sans)
        start = max(0, len(sans) - 60)
        txt = " ".join((f"{i // 2 + 1}." if i % 2 == 0 else "") + s for i, s in enumerate(sans) if i >= start)
        out.append(pick("Ходи партії до цієї позиції: ", "Game moves up to this position: ") + txt)
    if last:
        try:
            out.append(pick("Про останній хід:", "About the last move:") + "\n" + ai_facts(*last)[:1200])
        except Exception:  # noqa: BLE001
            pass
    return "\n".join(out)[:4000]


def fetch_ai_coach(facts, lang, timeout=40, question=None, history=None, bot=None):
    """Пояснення від ШІ-тренера (або відповідь на запитання гравця - question, history [{q, a}]).
    Повертає текст; при помилці - RuntimeError("quota" | "rate" | "net" | ...)."""
    d = {"lang": lang, "facts": facts}
    if question:
        d["question"], d["history"] = question, list(history or [])[-3:]
    if bot:                                  # 1.25.0: репліка бота-суперника (ім'я і характер шахіста)
        d["mode"], d["bot"] = "bot", bot
    body = json.dumps(d).encode("utf-8")
    req = urllib.request.Request(AI_COACH_URL, data=body, method="POST",
                                 headers={"Content-Type": "application/json", "User-Agent": "ChessAnalyzer"})
    try:
        with urllib.request.urlopen(req, timeout=timeout) as r:
            data = json.loads(r.read().decode("utf-8"))
    except urllib.error.HTTPError as e:
        try:
            err = json.loads(e.read().decode("utf-8")).get("error") or str(e.code)
        except Exception:  # noqa: BLE001
            err = str(e.code)
        raise RuntimeError(err)
    except Exception:  # noqa: BLE001
        raise RuntimeError("net")
    text = (data.get("text") or "").strip()
    if not text:
        raise RuntimeError("empty")
    return text


class LiveEngine:
    """Один постійний процес Stockfish для оцінки ходів, зроблених користувачем на дошці."""

    def __init__(self):
        self.lock = threading.Lock()
        self.engine = None
        self.path = None

    def get(self, path):
        """Викликати лише під self.lock."""
        if self.engine is None or self.path != path:
            self.close()
            self.engine = open_engine(path)
            self.path = path
        return self.engine

    def close(self):
        if self.engine is not None:
            try:
                self.engine.quit()
            except Exception:
                pass
        self.engine = None
        self.path = None


# ------------------------------------------------------------------ боти ---
# З 1.24.0: гра проти ботів у стилі відомих шахістів. Бот - це Stockfish, обмежений до сили гравця (UCI_Elo;
# у налаштуваннях гри можна вибрати й слабший рівень), плюс дебютний репертуар гравця («w» - білими, «b» - чорними)
# і стиль: серед майже рівноцінних ходів рушія (у межах «risk» сантипішаків від найкращого) бот бере той, що
# більше личить гравцеві («aggr» від -1 = спокійна позиційна гра до +1 = атака, жертви). Це наслідування стилю,
# а не самі гравці; партії в цьому режимі - звичайна вільна гра, яку Stockfish оцінює хід за ходом.
BOT_LEVELS = (900, 1100, 1350, 1500, 1700, 1900, 2100, 2300, 2500)
# 1.26.0: дебютний репертуар ботів - як кожен шахіст грав (грає) проти різних дебютів суперника. Бот іде варіантом,
# поки суперник не звернув; на розвилці бере один з ходів (частіше той, що в більшій кількості варіантів).
# Білими - відповіді на 1…e5, сицилійський, французький, Каро-Канн, скандинавський, Алехіна, Пірца/сучасний
# (у гравців 1.d4 - на ферзевий гамбіт, індійські захисти, голландський); чорними - на 1.e4, 1.d4, 1.c4, 1.Nf3.
# Джерела: загальновідомі репертуари шахістів; Witty Alien - Alien Gambit і Martian Gambit проти Каро-Канн,
# гамбіт Сміта-Морри, гамбіт Слона й гамбіт Англунда (його курси й сторінки chess.com / Chessable).
_R_RUY = "e4 e5 Nf3 Nc6 Bb5 a6 Ba4 Nf6 O-O Be7 Re1 b5 Bb3 d6 c3 O-O h3"
_R_NAJ = "e4 c5 Nf3 d6 d4 cxd4 Nxd4 Nf6 Nc3 a6"
_R_KID = "d4 Nf6 c4 g6 Nc3 Bg7 e4 d6"
_R_GRU = "d4 Nf6 c4 g6 Nc3 d5 cxd5 Nxd5 e4 Nxc3 bxc3 Bg7"
_R_QGD = "d4 d5 c4 e6 Nc3 Nf6 Bg5 Be7 e3 O-O Nf3"
_R_WIN = "e4 e6 d4 d5 Nc3 Bb4 e5 c5 a3 Bxc3+ bxc3"
_R_BER = "e4 e5 Nf3 Nc6 Bb5 Nf6 O-O Nxe4 d4 Nd6 Bxc6 dxc6 dxe5 Nf5 Qxd8+ Kxd8"
_R_PET = "e4 e5 Nf3 Nf6 Nxe5 d6 Nf3 Nxe4"
_R_SVE = "e4 c5 Nf3 Nc6 d4 cxd4 Nxd4 Nf6 Nc3 e5 Ndb5 d6"
_R_TAI = "e4 c5 Nf3 e6 d4 cxd4 Nxd4 Nc6 Nc3 Qc7"
# типові відповіді 1.e4-гравця на рідкісні захисти (щоб бот не «губився» вже на 2-му ходу)
