def bot_stars_for(bot, won, real, undos, hints):
    """Зірки за партію з ботом: ★ - перемога на будь-якій силі; ★★ - перемога на силі самого шахіста;
    ★★★ - те саме без жодного повернення ходу й без підказки."""
    if not won:
        return 0
    if not real:
        return 1
    return 3 if not undos and not hints else 2


def stars_text(n, total=3):
    return "★" * n + "☆" * (total - n)


_BOT_PNAME = {chess.PAWN: ("пішака", "pawn"), chess.KNIGHT: ("коня", "knight"), chess.BISHOP: ("слона", "bishop"),
              chess.ROOK: ("туру", "rook"), chess.QUEEN: ("ферзя", "queen"), chess.KING: ("короля", "king")}


def bot_chat_facts(event, board, bot_color, result=None):
    """Факти для репліки бота (мовою інтерфейсу) - лише те, що видно на дошці; жодних даних рушія, щоб не підказати.
    event: start | move | end; board - позиція після останнього ходу з історією."""
    me = pick("білими", "White") if bot_color == chess.WHITE else pick("чорними", "Black")
    out = [pick(f"Ти граєш {me}. Суперник - людина.", f"You play {me}. Your opponent is a human.")]
    if event == "start":
        out.append(pick("Подія: партія тільки починається, привітайся.", "Event: the game is just starting, greet the opponent."))
        return "\n".join(out)
    if event == "alien":                      # 1.27.6: гравець щойно зіграв 1...c6 - Каро-Канн
        out.append(pick("Подія: людина щойно відповіла 1...c6 - Каро-Канн. Ти чекав саме цього. Привітай її по-своєму.",
                        "Event: the human just answered 1...c6 - the Caro-Kann. You were waiting for exactly this. "
                        "Greet them in your own way."))
        return "\n".join(out)
    if event == "end":
        won = result is not None and ((result == "1-0") == (bot_color == chess.WHITE)) and result != "1/2-1/2"
        what = pick("нічия", "a draw") if result == "1/2-1/2" else (pick("ти переміг", "you won") if won else
                                                                    pick("людина перемогла тебе", "the human beat you"))
        out.append(pick(f"Подія: партія закінчилась - {what}. Попрощайся.", f"Event: the game is over - {what}. Say goodbye."))
        return "\n".join(out)
    out.append(pick(f"Хід {board.fullmove_number}.", f"Move {board.fullmove_number}."))
    moves = list(board.move_stack)[-2:]               # останній хід людини і відповідь бота
    tmp = board.copy()
    for _ in moves:
        tmp.pop()
    for mv in moves:
        who_bot = tmp.turn == bot_color
        san = tmp.san(mv)
        cap = tmp.is_capture(mv)
        victim = (chess.PAWN if tmp.is_en_passant(mv) else tmp.piece_type_at(mv.to_square)) if cap else None
        if who_bot:
            s = pick(f"Ти зіграв {san}", f"You played {san}")
            if victim:
                s += pick(f" і забрав {_BOT_PNAME[victim][0]} людини", f" and took the human's {_BOT_PNAME[victim][1]}")
        else:
            s = pick(f"Людина зіграла {san}", f"The human played {san}")
            if victim:
                s += pick(f" і забрала твого {_BOT_PNAME[victim][0]}", f" and took your {_BOT_PNAME[victim][1]}")
        tmp.push(mv)
        if tmp.is_check():
            s += pick(" з шахом", " with check")
        out.append(s + ".")
    diff = material_diff(board, bot_color)
    out.append(pick("Матеріал рівний." if diff == 0 else f"Матеріал: у тебе на {abs(diff)} {'більше' if diff > 0 else 'менше'}.",
                    "Material is equal." if diff == 0 else f"Material: you are {abs(diff)} {'up' if diff > 0 else 'down'}."))
    return "\n".join(out)


