def bot_canned(event, rng, alien=False):
    if alien:
        return pick(*rng.choice(ALIEN_CANNED.get(event, ALIEN_CANNED["move"])))
    return pick(*rng.choice(BOT_CANNED.get(event, BOT_CANNED["move"])))


