def witty_book_move(ucis, white, rng):
    """Хід Witty Alien з тією ж частотою, з якою він сам грає в цій позиції (або None)."""
    raw = WITTY_BOOK["w" if white else "b"].get(" ".join(ucis))
    if not raw:
        return None
    opts = [(u, int(c)) for u, c in (x.split(":") for x in raw.split(","))]
    r = rng.random() * sum(c for _, c in opts)
    for u, c in opts:
        r -= c
        if r < 0:
            return u
    return opts[-1][0]


def bot_book_move(bot, ucis, white, rng):
    """Наступний хід з репертуару бота, якщо партія досі йде одним з його варіантів (інакше None)."""
    if bot["id"] == "wittyalien":
        u = witty_book_move(ucis, white, rng)
        if u:
            return u
    n = len(ucis)
    nxt = [ln[n] for ln in bot_lines(bot, white) if len(ln) > n and ln[:n] == ucis]
    return rng.choice(nxt) if nxt else None


def bot_style_bonus(board, move, aggr):
    """Наскільки хід личить стилю (у сантипішаках): aggr > 0 - шахи, взяття, фігури до короля суперника, жертви;
    aggr < 0 - навпаки: спокійні ходи й розмін ферзів."""
    piece = board.piece_type_at(move.from_square)
    me = board.turn
    bonus = 0.0
    if board.gives_check(move):
        bonus += 25
    if board.is_capture(move):
        victim = chess.PAWN if board.is_en_passant(move) else board.piece_type_at(move.to_square)
        bonus += -30 if (piece == chess.QUEEN and victim == chess.QUEEN) else 10
    king = board.king(not me)
    if king is not None and piece != chess.KING:
        closer = chess.square_distance(move.from_square, king) - chess.square_distance(move.to_square, king)
        bonus += 6 * max(-3, min(3, closer))
    if piece not in (chess.PAWN, chess.KING):
        after = board.copy(stack=False)
        after.push(move)
        foes = after.attackers(not me, move.to_square)
        if foes:
            cheapest = min(_BOT_VAL[after.piece_type_at(s)] for s in foes)
            if cheapest < _BOT_VAL[piece] or not after.attackers(me, move.to_square):
                bonus += 30               # фігура під боєм: «жертва» (рушій уже перевірив, що хід не програє)
    return bonus * aggr


def bot_choose(board, sf_move, cands, bot):
    """Хід бота: cands - [(хід, оцінка для того, хто ходить)] від рушія, найкращий перший; sf_move - вибір самого
    Stockfish на заданій силі. Якщо рушій навмисне «помилився» (гра на нижчому рівні) - лишаємо його хід; інакше
    серед ходів, не гірших за найкращий більш ніж на bot['risk'], беремо найближчий до стилю."""
    if not cands:
        return sf_move
    top = cands[0][1]
    sf_cp = next((cp for m, cp in cands if m == sf_move), None)
    if sf_cp is None or top - sf_cp > bot["risk"]:
        return sf_move
    best, best_v = sf_move, None
    for m, cp in cands:
        if top - cp > bot["risk"]:
            continue
        v = cp + bot_style_bonus(board, m, bot["aggr"])
        if best_v is None or v > best_v:
            best, best_v = m, v
    return best


def bot_engine_move(eng, board, elo, bot, rng, seconds=0.8):
    """Хід бота від Stockfish: сила UCI_Elo (1320–3190; нижчі рівні - 1320 плюс випадкові слабкі ходи), 4 варіанти."""
    eng.configure({"UCI_LimitStrength": True, "UCI_Elo": max(1320, min(3190, int(elo)))})
    with eng.analysis(board, chess.engine.Limit(time=seconds), multipv=4) as an:
        best = an.wait()
        infos = list(an.multipv)
    cands = []
    for inf in infos:
        pv, sc = inf.get("pv"), inf.get("score")
        if pv and sc is not None:
            cands.append((pv[0], sc.pov(board.turn).score(mate_score=MATE_SCORE)))
    cands.sort(key=lambda x: -x[1])
    sf_move = best.move or (cands[0][0] if cands else next(iter(board.legal_moves)))
    move = bot_choose(board, sf_move, cands, bot)
    if elo < 1320 and len(cands) > 1 and rng.random() < (1320 - elo) / 1320 * 0.8:
        move = cands[-1][0]               # рівні 900 і 1100: інколи найслабший з варіантів
    return move


def bot_game_over(board):
    """Кінець партії з ботом: (результат «1-0» / «0-1» / «1/2-1/2», причина) або None. Нічия за трикратним
    повторенням і правилом 50 ходів - одразу, без заявки."""
    out = board.outcome(claim_draw=True)
    if out is None:
        return None
    T = chess.Termination
    reason = {T.CHECKMATE: "mate", T.STALEMATE: "stalemate", T.INSUFFICIENT_MATERIAL: "material",
              T.THREEFOLD_REPETITION: "repetition", T.FIVEFOLD_REPETITION: "repetition",
              T.FIFTY_MOVES: "fifty", T.SEVENTYFIVE_MOVES: "fifty"}.get(out.termination, "draw")
    return out.result(), reason


