def bug_report_url(platform):
    """1.27.17: нова задача GitHub з версією й платформою (текст англійською - її читаємо ми)."""
    body = (f"**Version:** {APP_VERSION}\n**Platform:** {platform}\n\n"
            "**What happened?**\n\n\n**Steps to reproduce:**\n1. \n\n**PGN (if any):**\n")
    return f"{GITHUB_URL}/issues/new?" + urllib.parse.urlencode({"title": "Bug: ", "body": body, "labels": "bug"})


def fetch_site_stats():
    """Статистика (з 1.23.0) з stats.json у репозиторії: перегляди сторінки GitHub (накопичено по днях) і канал
    Telegram (підписники, перегляди дописів). Файл оновлює автор під час кожного релізу."""
    req = urllib.request.Request(f"{STATS_URL}?t={int(time.time())}", headers={"User-Agent": "ChessAnalyzer"})
    with urllib.request.urlopen(req, timeout=15) as resp:
        return json.loads(resp.read().decode("utf-8"))



