def release_notes_for(body):
    """Опис релізу двома мовами: українська, потім рядок «— English —» і англійська.
    Список файлів релізу («Файли:» / «Files:») не показуємо - лише що змінилось (1.22.4)."""
    body = body or ""
    i = body.find("— English —")
    if i >= 0:
        body = body[i + len("— English —"):] if STATE["lang"] == "en" else body[:i]
    body = re.split(r"(?m)^\s*(?:Файли|Files)\s*:", body)[0]
    return body.replace("<!--", "").replace("-->", "").strip()   # 1.25.1: українська - в HTML-коментарі


def update_changes_text(u):
    """Текст «що нового» для квадрата оновлення: кожна нова версія окремо, новіші зверху."""
    parts = [(v, release_notes_for(b)) for v, b in (u.get("changes") or [])]
    parts = [(v, n) for v, n in parts if n]
    if not parts:
        return release_notes_for(u.get("notes"))
    if len(parts) == 1:
        return parts[0][1]
    return "\n\n".join(f"{v}\n{n}" for v, n in parts)


def app_dir():
    return os.path.dirname(os.path.abspath(sys.executable))


def can_self_update():
    """Оновлюватись самій може лише зібрана програма з папкою, куди можна писати."""
    if not getattr(sys, "frozen", False):
        return False
    d = app_dir()
    try:
        probe = os.path.join(d, ".update_probe")
        with open(probe, "w") as f:
            f.write("1")
        os.remove(probe)
        return True
    except OSError:
        return False


def _fetch_to(url, zpath, progress, api=False):
    hdr = {"User-Agent": "ChessAnalyzer"}
    if api:
        hdr["Accept"] = "application/octet-stream"   # файл через API GitHub (інший шлях, ніж releases/download)
    req = urllib.request.Request(url, headers=hdr)
    with urllib.request.urlopen(req, timeout=30) as resp, open(zpath, "wb") as out:
        total = int(resp.headers.get("Content-Length") or 0)
        done = 0
        while True:
            chunk = resp.read(1 << 16)
            if not chunk:
                break
            out.write(chunk)
            done += len(chunk)
            if progress:
                progress(done, total)


def download_update(url, progress=None, api_url=""):
    """Завантажує й розпаковує архів оновлення у тимчасову папку. Повертає (тимчасова, нові файли).
    GitHub інколи відповідає 504 на звичайне посилання - тоді пробуємо через API і ще раз (до 4 спроб)."""
    tmp = tempfile.mkdtemp(prefix="ChessAnalyzer-update-")
    zpath = os.path.join(tmp, "update.zip")
    tries = ([(api_url, True)] if api_url else []) + [(url, False)]
    tries = (tries * 2)[:4]
    err = None
    for k, (u, api) in enumerate(tries):
        try:
            _fetch_to(u, zpath, progress, api)
            zipfile.ZipFile(zpath).close()          # архів цілий
            err = None
            break
        except Exception as e:  # noqa: BLE001
            err = e
            if isinstance(e, urllib.error.HTTPError) and e.code < 500 and e.code not in (403, 429) and not api:
                break                                  # 404 тощо - повтор не допоможе
            time.sleep(2 + 2 * k)
    if err is not None:
        raise err
    new = os.path.join(tmp, "new")
    with zipfile.ZipFile(zpath) as z:
        z.extractall(new)
    os.remove(zpath)
    if not os.path.exists(os.path.join(new, "ChessAnalyzer.exe")):
        raise RuntimeError("ChessAnalyzer.exe not found in the update")
    return tmp, new


def _spawn(cmd, cwd):
    """Окремий процес, який переживе закриття цієї програми."""
    base = subprocess.CREATE_NEW_PROCESS_GROUP if sys.platform == "win32" else 0
    try:
        subprocess.Popen(cmd, cwd=cwd, creationflags=base | (0x01000000 if base else 0), close_fds=True)
    except OSError:                                    # CREATE_BREAKAWAY_FROM_JOB не дозволено
        subprocess.Popen(cmd, cwd=cwd, creationflags=base, close_fds=True)


def launch_updater(tmp, new, dst=None, pid=None, exe="ChessAnalyzer.exe"):
    """
    Запускає НОВУ версію з тимчасової папки з ключем --finish-update: вона дочекається, поки ця
    програма закриється, скопіює себе поверх старих файлів і відкриє оновлену програму.
    (Без PowerShell: прихований скрипт Windows вважає підозрілим.)
    """
    dst = dst or app_dir()
    pid = pid or os.getpid()
    if _same_file(os.path.join(new, exe), os.path.join(dst, exe)):
        # 1.25.4: запускач той самий - Smart App Control не дає запускати exe з %TEMP% (навіть той самий файл),
        # тож копіюємо змінені файли самі й запускаємо вже дозволений exe з папки програми
        for root, _dirs, files in os.walk(new):
            rel = os.path.relpath(root, new)
            if rel.split(os.sep)[0] == "_internal":       # бібліотеки запускача: ті самі й зайняті цим процесом
                continue
            os.makedirs(os.path.join(dst, rel), exist_ok=True)
            for f in files:
                s, d = os.path.join(root, f), os.path.join(dst, rel, f)
                if not _same_file(s, d):
                    shutil.copy2(s, d)
        _spawn([os.path.join(dst, exe)], dst)
        return
    _spawn([os.path.join(new, exe), "--finish-update", dst, str(int(pid)), tmp], new)


def _same_file(a, b):
    """Чи однакові файли (розмір і SHA-256)."""
    import hashlib
    try:
        if os.path.getsize(a) != os.path.getsize(b):
            return False
        with open(a, "rb") as fa, open(b, "rb") as fb:
            return hashlib.sha256(fa.read()).digest() == hashlib.sha256(fb.read()).digest()
    except OSError:
        return False


def _wait_pid(pid, timeout=120.0):
    if sys.platform != "win32":
        return
    import ctypes
    k32 = ctypes.windll.kernel32
    h = k32.OpenProcess(0x00100000, False, int(pid))      # SYNCHRONIZE
    if h:
        k32.WaitForSingleObject(h, int(timeout * 1000))
        k32.CloseHandle(h)


def finish_update(dst, pid, tmp, src=None, exe="ChessAnalyzer.exe", relaunch=True):
    """Друга половина оновлення (працює нова версія з тимчасової папки)."""
    src = src or app_dir()
    _wait_pid(pid)
    time.sleep(0.8)
    for _ in range(15):
        try:
            shutil.copytree(src, dst, dirs_exist_ok=True)
            break
        except OSError:
            time.sleep(1)
    if relaunch:
        _spawn([os.path.join(dst, exe)], dst)


def cleanup_update_leftovers():
    """Тимчасові папки попередніх оновлень (нова версія не може стерти папку, з якої запущена)."""
    for d in glob.glob(os.path.join(tempfile.gettempdir(), "ChessAnalyzer-update-*")):
        shutil.rmtree(d, ignore_errors=True)


