# Партії гравця з chess.com (з 1.20.0): відкритий API chess.com (PubAPI), без входу й пароля - лише нік.
# /pub/player/<нік>/games/archives - список місяців з партіями; кожен місяць - партії з PGN.
CHESSCOM_API = "https://api.chess.com/pub/player/"
CHESSCOM_UA = "ChessAnalyzer (github.com/volod4ik4-code/chess-analyzer)"
CHESSCOM_NICK = re.compile(r"[A-Za-z0-9_-]{2,30}")
# 1.29.0: акаунти відомих гросмейстерів на chess.com (кнопки у вікні «Партії Chess.com»)
CHESSCOM_FAMOUS = ["Hikaru", "MagnusCarlsen", "DanielNaroditsky", "FabianoCaruana", "GukeshDommaraju", "Firouzja2003", "AnishGiri", "LyonBeast", "RpragChess", "GothamChess"]
# 1.29.0: база партій майстрів (lichess Masters: турнірні партії гравців FIDE 2200+), без ключа
MASTERS_URL = "https://explorer.lichess.ovh/masters"


def chesscom_get(url):
    req = urllib.request.Request(url, headers={"User-Agent": CHESSCOM_UA, "Accept": "application/json"})
    with urllib.request.urlopen(req, timeout=20) as resp:
        return json.loads(resp.read().decode("utf-8"))


def chesscom_archives(user):
    """Місяці, у яких гравець грав: [(рік, місяць, url)], новіші перші."""
    data = chesscom_get(CHESSCOM_API + user.strip().lower() + "/games/archives")
    out = []
    for u in data.get("archives") or []:
        m = re.search(r"/(\d{4})/(\d{2})$", u)
        if m:
            out.append((int(m.group(1)), int(m.group(2)), u))
    return sorted(out, reverse=True)


def chesscom_games(url, user):
    """Партії місяця (лише звичайні шахи), новіші перші: колір гравця, суперник, результат, контроль, дебют, PGN."""
    data = chesscom_get(url)
    me = user.strip().lower()
    rows = []
    for g in data.get("games") or []:
        if g.get("rules", "chess") != "chess" or not g.get("pgn"):
            continue
        w, b = g.get("white") or {}, g.get("black") or {}
        white = (w.get("username") or "").lower() == me
        mine, opp = (w, b) if white else (b, w)
        res = "win" if mine.get("result") == "win" else ("loss" if opp.get("result") == "win" else "draw")
        opening = ""
        m = re.search(r'\[ECOUrl "[^"]*/openings/([^"]+)"\]', g["pgn"])
        if m:
            # «Sicilian-Defense-McDonnell-Attack-2...e6-3.Nf3» / «Alapin-Sicilian-Defense...3.Nf3» -> лише назва
            opening = re.split(r"(?:-|\.\.\.)\d", m.group(1))[0].replace("-", " ").strip(" .")
        rows.append({"end": g.get("end_time") or 0, "white": white, "opp": opp.get("username") or "?",
                     "opp_rating": opp.get("rating"), "result": res, "class": g.get("time_class") or "",
                     "tc": str(g.get("time_control") or ""), "opening": opening, "pgn": g["pgn"]})
    rows.sort(key=lambda r: r["end"], reverse=True)
    return rows


def fmt_time_control(tc):
    """«180» -> «3 хв», «180+2» -> «3+2», «1/86400» -> «1 д» (щоденні)."""
    if "/" in tc:
        try:
            days = int(tc.split("/")[1]) // 86400
        except ValueError:
            return tc
        return pick(f"{days} д", f"{days} d")
    base, _, inc = tc.partition("+")
    try:
        b = int(base)
    except ValueError:
        return tc
    main = str(b // 60) if b >= 60 else pick(f"{b} с", f"{b} s")
    if inc and inc != "0":
        return f"{main}+{inc}"
    return main + (pick(" хв", " min") if b >= 60 else "")


# ------------------------------------------------------------ дослідження ---
# Дослідження (як на lichess): назва і розділи. Розділ - партія з аналізом рушія, власні
# варіанти гравця, коментарі до позицій і стрілки/кола на дошці. Кожне дослідження -
# окремий JSON-файл у STUDIES_DIR. Позицію (вузол) позначаємо шляхом:
#   "k"            - позиція основної лінії після k-го ходу (0 - початкова);
#   "k/e2e4/e7e5"  - позиція у варіанті, який відходить від позиції k.
# Стрілки й кола - рядки як у PGN lichess: "Ge2e4" (стрілка), "Re4" (коло).

def _study_now():
    return time.strftime("%Y-%m-%d %H:%M")


def _plural(n, uk_forms, en_forms):
    """«1 розділ, 2 розділи, 5 розділів» / «1 chapter, 2 chapters»."""
    if STATE["lang"] == "en":
        return f"{n} {en_forms[0] if n == 1 else en_forms[1]}"
    if n % 10 == 1 and n % 100 != 11:
        word = uk_forms[0]
    elif 2 <= n % 10 <= 4 and not 12 <= n % 100 <= 14:
        word = uk_forms[1]
    else:
        word = uk_forms[2]
    return f"{n} {word}"


def list_studies():
    """Збережені дослідження: [(шлях до файлу, дослідження)], новіші зверху."""
    out = []
    try:
        names = os.listdir(STUDIES_DIR)
    except OSError:
        return out
    for fn in names:
        if not fn.lower().endswith(".json"):
            continue
        path = os.path.join(STUDIES_DIR, fn)
        try:
            with open(path, encoding="utf-8") as f:
                data = json.load(f)
        except Exception:  # noqa: BLE001
            continue
        if isinstance(data, dict) and isinstance(data.get("chapters"), list):
            out.append((path, data))
    out.sort(key=lambda p: str(p[1].get("updated", "")), reverse=True)
    return out


def new_study_path():
    os.makedirs(STUDIES_DIR, exist_ok=True)
    base = time.strftime("study-%Y%m%d-%H%M%S")
    path = os.path.join(STUDIES_DIR, base + ".json")
    n = 2
    while os.path.exists(path):
        path = os.path.join(STUDIES_DIR, f"{base}-{n}.json")
        n += 1
    return path


def save_study(path, study):
    """Записує дослідження надійно: спершу тимчасовий файл, потім заміна старого."""
    os.makedirs(os.path.dirname(path), exist_ok=True)
    study["updated"] = _study_now()
    tmp = path + ".tmp"
    with open(tmp, "w", encoding="utf-8") as f:
        json.dump(study, f, ensure_ascii=False)
    os.replace(tmp, path)


def _safe_filename(name):
    bad = '<>:"/\\|?*'
    clean = "".join("_" if c in bad or ord(c) < 32 else c for c in name).strip(" .")
    return clean[:80] or "study"


def _shape_comment(shapes):
    """Стрілки й кола у форматі PGN, який розуміють lichess і chess.com: [%csl Ge4][%cal Ge2e4]."""
    circles = [s for s in shapes if len(s) == 3]
    arrows = [s for s in shapes if len(s) == 5]
    out = ""
    if circles:
        out += "[%csl " + ",".join(circles) + "]"
    if arrows:
        out += "[%cal " + ",".join(arrows) + "]"
    return out


def chapter_pgn(ch, study_name=""):
    """Розділ дослідження у PGN: основна лінія, варіанти гравця, коментарі, стрілки й кола."""
    res = ch["result"]
    game = chess.pgn.Game()
    for key, val in (ch.get("headers") or {}).items():
        game.headers[str(key)] = str(val)
    if res["fens"][0] != chess.STARTING_FEN:
        game.setup(chess.Board(res["fens"][0]))
    game.headers["Event"] = f"{study_name}: {ch.get('name', '')}" if study_name else ch.get("name", "?")
    nodes = [game]
    node = game
    for m in res["moves"]:
        node = node.add_main_variation(chess.Move.from_uci(m["uci"]))
        nodes.append(node)
    by_key = {str(k): n for k, n in enumerate(nodes)}
    for ln in ch.get("lines", []):
        base = ln.get("base", 0)
        if not 0 <= base < len(nodes):
            continue
        node, path = nodes[base], str(base)
        for row in ln.get("rows", []):
            mv = chess.Move.from_uci(row["uci"])
            node = node.variation(mv) if node.has_variation(mv) else node.add_variation(mv)
            path += "/" + row["uci"]
            by_key[path] = node
    notes, shapes = ch.get("notes") or {}, ch.get("shapes") or {}
    for key, node in by_key.items():
        parts = [p for p in (_shape_comment(shapes.get(key, [])), notes.get(key, "")) if p]
        if parts:
            node.comment = " ".join(parts)
    return str(game)


