# ------------------------------------------------------------------ дизайн ---
# Вигляд з 1.18.0: панелі - «картки» із заокругленими кутами, власні кнопки й перемикачі.
# Стандартні віджети Tk прямокутні, тож заокруглення малюємо самі: згладжені кути - маленькі
# картинки (PhotoImage), кольори яких змішано з фоном за покриттям пікселя (4x4 підпікселі).
FONT_SEMI = None          # «Segoe UI Semibold», якщо є (init_fonts), інакше жирний Segoe UI


def init_fonts(root):
    """Напряму через Tcl (font families), без модуля tkinter.font - його може не бути в запускачі exe."""
    global FONT_SEMI
    try:
        fams = set(root.tk.splitlist(root.tk.call("font", "families")))
        FONT_SEMI = "Segoe UI Semibold" if "Segoe UI Semibold" in fams else ""
    except Exception:  # noqa: BLE001
        FONT_SEMI = ""


def fsemi(size):
    """Напівжирний шрифт для заголовків і кнопок."""
    return (FONT_SEMI, size) if FONT_SEMI else ("Segoe UI", size, "bold")


def parent_bg(w):
    """Колір фону віджета (і tk, і ttk) - щоб згладжені кути зливались із тим, що під ними."""
    try:
        if isinstance(w, ttk.Widget):
            style = w.cget("style") or w.winfo_class()
            return ttk.Style(w).lookup(style, "background") or BG
        return w.cget("bg")
    except Exception:  # noqa: BLE001
        return BG


_COV = {}
_RIMG = {}


def _corner_cov(r):
    """Покриття пікселів верхнього лівого кута радіуса r: r рядків по r чисел 0..1."""
    t = _COV.get(r)
    if t is None:
        ss = 4
        t = []
        for y in range(r):
            row = []
            for x in range(r):
                n = 0
                for sy in range(ss):
                    for sx in range(ss):
                        dx, dy = x + (sx + 0.5) / ss - r, y + (sy + 0.5) / ss - r
                        n += dx * dx + dy * dy <= r * r
                row.append(n / (ss * ss))
            t.append(row)
        _COV[r] = t
    return t


def _photo(rows):
    img = tk.PhotoImage(width=len(rows[0]), height=len(rows))
    img.put(" ".join("{" + " ".join(r) + "}" for r in rows), to=(0, 0))
    return img


def cap_image(h, r, fill, bg, side):
    """Заокруглений край кнопки (ліва чи права частина шириною r і висотою h)."""
    key = ("cap", h, r, fill, bg, side)
    img = _RIMG.get(key)
    if img is None:
        cov = _corner_cov(r)
        rows = []
        for y in range(h):
            cr = cov[y] if y < r else (cov[h - 1 - y] if y >= h - r else None)
            row = [fill] * r if cr is None else [mix(bg, fill, c) for c in cr]
            rows.append(row[::-1] if side == "right" else row)
        img = _RIMG[key] = _photo(rows)
    return img


def corner_image(r, fill, bg, which):
    """Кут картки: which - tl / tr / bl / br."""
    key = ("corner", r, fill, bg, which)
    img = _RIMG.get(key)
    if img is None:
        rows = [[mix(bg, fill, c) for c in row] for row in _corner_cov(r)]
        if which in ("tr", "br"):
            rows = [row[::-1] for row in rows]
        if which in ("bl", "br"):
            rows = rows[::-1]
        img = _RIMG[key] = _photo(rows)
    return img


def circle_image(d, fill, bg):
    """Згладжене коло діаметром d (повзунок перемикача)."""
    key = ("circle", d, fill, bg)
    img = _RIMG.get(key)
    if img is None:
        rad, ss, rows = d / 2, 4, []
        for y in range(d):
            row = []
            for x in range(d):
                n = 0
                for sy in range(ss):
                    for sx in range(ss):
                        dx, dy = x + (sx + 0.5) / ss - rad, y + (sy + 0.5) / ss - rad
                        n += dx * dx + dy * dy <= rad * rad
                row.append(mix(bg, fill, n / (ss * ss)))
            rows.append(row)
        img = _RIMG[key] = _photo(rows)
    return img


def round_rect(cv, x1, y1, x2, y2, r, **kw):
    """Прямокутник із заокругленими кутами на Canvas (для виділення ходу тощо)."""
    pts = [x1 + r, y1, x2 - r, y1, x2, y1, x2, y1 + r, x2, y2 - r, x2, y2, x2 - r, y2,
           x1 + r, y2, x1, y2, x1, y2 - r, x1, y1 + r, x1, y1]
    return cv.create_polygon(pts, smooth=True, **kw)


