_BTN_FONTS = {}


class RButton(tk.Canvas):
    """
    Кнопка із заокругленими кутами (з 1.18.0 замість ttk.Button). Розуміє те саме, що й ttk.Button:
    text, command, state ("normal"/"disabled"), style (Accent/Small/Nav.TButton), width (у символах).
    cget("text")/configure(text=...) працюють, тож переклад _apply_lang її бачить.
    """
    STYLE_KIND = {"Accent.TButton": "accent", "Small.TButton": "small", "Nav.TButton": "nav"}

    def __init__(self, master, text="", command=None, style=None, width=None, kind=None, bg=None, **kw):
        self.kind = kind or self.STYLE_KIND.get(style, "normal")
        self.spec = BTN_KINDS[self.kind]
        self._bg = bg or parent_bg(master)
        super().__init__(master, highlightthickness=0, bd=0, bg=self._bg, **kw)
        self._text, self._cmd, self._state = text, command, "normal"
        self._chars = width
        self._hover = self._down = False
        self._fill = None
        self._anim = None
        self._items = None
        self._render()
        self.bind("<Enter>", self._on_enter)
        self.bind("<Leave>", self._on_leave)
        self.bind("<ButtonPress-1>", self._on_press)
        self.bind("<ButtonRelease-1>", self._on_release)

    # ---- як у ttk.Button
    def configure(self, cnf=None, **kw):
        if isinstance(cnf, dict):
            kw = {**cnf, **kw}
        elif cnf is not None:
            return self.cget(cnf)
        if not kw:
            return super().configure()
        redraw = False
        if "text" in kw:
            self._text = str(kw.pop("text"))
            redraw = True
        if "command" in kw:
            self._cmd = kw.pop("command")
            redraw = True
        if "state" in kw:
            self._state = "disabled" if str(kw.pop("state")) == "disabled" else "normal"
            redraw = True
        if "width" in kw:
            self._chars = kw.pop("width")
            redraw = True
        kw.pop("style", None)
        if kw:
            super().configure(**kw)
        if redraw:
            self._render()

    config = configure

    def cget(self, key):
        if key == "text":
            return self._text
        if key == "state":
            return self._state
        if key == "command":
            return self._cmd
        return super().cget(key)

    def __getitem__(self, key):
        return self.cget(key)

    def __setitem__(self, key, value):
        self.configure(**{key: value})

    def invoke(self):
        if self._state != "disabled" and self._cmd:
            self._cmd()

    def set_kind(self, kind):
        """Інший вигляд (BTN_KINDS) - напр. вибраний сегмент перемикача."""
        if kind != self.kind:
            self.kind, self.spec = kind, BTN_KINDS[kind]
            self._render()

    # ---- малювання
    def _measure(self, spec, text):
        """Ширина тексту в пікселях (Tcl «font measure»; кеш - бо кнопок багато)."""
        key = (spec, text)
        w = _BTN_FONTS.get(key)
        if w is None:
            w = _BTN_FONTS[key] = int(self.tk.call("font", "measure", spec, "-displayof", self._w, text))
        return w

    def _colors(self):
        s = self.spec
        if self._state == "disabled":
            return mix(s["fill"], self._bg, 0.45), mix(s["fg"], self._bg, 0.55)
        if self._down and self._hover:
            return s["press"], s["fg"]
        return (s["hover"] if self._hover else s["fill"]), s["fg"]

    def _render(self):
        s = self.spec
        spec = s["font"]()
        w = self._measure(spec, self._text) + 2 * s["padx"]
        if self._chars:
            w = max(w, self._measure(spec, "0") * int(self._chars) + 2 * s["padx"])
        w = max(w, s.get("minw", 0), 2 * s["r"] + 2)
        h, r = s["h"], s["r"]
        super().configure(width=w, height=h,
                          cursor="hand2" if self._cmd and self._state != "disabled" else "")
        fill, fg = self._colors()
        self.delete("all")
        self._items = (self.create_image(0, 0, anchor="nw", image=cap_image(h, r, fill, self._bg, "left")),
                       self.create_image(w, 0, anchor="ne", image=cap_image(h, r, fill, self._bg, "right")),
                       self.create_rectangle(r, 0, w - r, h, fill=fill, width=0),
                       self.create_text(w / 2, h / 2, text=self._text, fill=fg, font=spec))
        self._fill = fill               # (не self._w - це ім'я віджета в Tk)

    def _paint(self, fill, fg=None):
        """Новий колір фону без перебудови (для плавного переходу під мишею)."""
        if not self._items:
            return
        h, r = self.spec["h"], self.spec["r"]
        left, right, rect, txt = self._items
        self.itemconfigure(left, image=cap_image(h, r, fill, self._bg, "left"))
        self.itemconfigure(right, image=cap_image(h, r, fill, self._bg, "right"))
        self.itemconfigure(rect, fill=fill)
        if fg:
            self.itemconfigure(txt, fill=fg)
        self._fill = fill

    def _fade_to(self, target):
        """Плавна зміна кольору кнопки (~0,1 с) - як у сучасних програмах."""
        if self._anim:
            self.after_cancel(self._anim)
            self._anim = None
        start = self._fill or target
        if start == target:
            return

        def step(i=1):
            self._paint(mix(start, target, i / 3))
            self._anim = self.after(28, step, i + 1) if i < 3 else None
        step()

    def _on_enter(self, _e):
        if self._state == "disabled" or not self._cmd:
            return
        self._hover = True
        self._fade_to(self._colors()[0])

    def _on_leave(self, _e):
        self._hover = False
        if self._state != "disabled" and self._cmd:
            self._fade_to(self._colors()[0])

    def _on_press(self, _e):
        if self._state == "disabled" or not self._cmd:
            return
        self._down = True
        self._paint(self._colors()[0])

    def _on_release(self, e):
        was = self._down
        self._down = False
        if self._state == "disabled" or not self._cmd:
            return
        inside = 0 <= e.x < self.winfo_width() and 0 <= e.y < self.winfo_height()
        self._hover = inside
        self._paint(self._colors()[0])
        if was and inside:
            self._cmd()


class Card(tk.Frame):
    """
    Картка - панель із заокругленими кутами. Вміст класти в card.body (відступ pad від країв).
    Кути - маленькі картинки поверх кутів рамки (place), тож pack/grid усередині не заважають.
    """

    def __init__(self, master, pad=(14, 12), r=10, bg=None, outer=None, **kw):
        bg = bg or PANEL
        outer = outer or parent_bg(master)
        super().__init__(master, bg=bg, bd=0, highlightthickness=0, **kw)
        px, py = pad if isinstance(pad, tuple) else (pad, pad)
        self.body = tk.Frame(self, bg=bg, bd=0, highlightthickness=0)
        self.body.pack(fill="both", expand=True, padx=px, pady=py)
        for which, place in (("tl", dict(x=0, y=0, anchor="nw")),
                             ("tr", dict(relx=1.0, y=0, anchor="ne")),
                             ("bl", dict(x=0, rely=1.0, anchor="sw")),
                             ("br", dict(relx=1.0, rely=1.0, anchor="se"))):
            tk.Label(self, image=corner_image(r, bg, outer, which), bd=0, highlightthickness=0,
                     padx=0, pady=0, bg=outer).place(**place)


class Switch(tk.Frame):
    """Перемикач (як у телефоні) замість прапорця: доріжка з повзунком + підпис; пов'язаний з BooleanVar."""
    W, H, KNOB = 34, 18, 14
    OFF = "#4a4642"

    def __init__(self, master, text, variable, bg=None, fg=None, font=None):
        bg = bg or parent_bg(master)
        super().__init__(master, bg=bg, bd=0, highlightthickness=0)
        self.var, self._bg = variable, bg
        self.cv = tk.Canvas(self, width=self.W, height=self.H, bg=bg, highlightthickness=0, bd=0, cursor="hand2")
        self.cv.pack(side="left")
        self.lbl = tk.Label(self, text=text, bg=bg, fg=fg or FG, font=font or ("Segoe UI", 10), cursor="hand2",
                            bd=0, padx=0, pady=0)
        self.lbl.pack(side="left", padx=(8, 0))
        for w in (self, self.cv, self.lbl):
            w.bind("<Button-1>", self._toggle)
        self._pos = 1.0 if variable.get() else 0.0
        self._anim = None
        variable.trace_add("write", lambda *a: self._animate())
        self._draw()

    def _toggle(self, _e=None):
        self.var.set(not bool(self.var.get()))

    def _draw(self):
        W, H, K = self.W, self.H, self.KNOB
        r = H // 2
        track = mix(self.OFF, ACCENT, self._pos)
        cv = self.cv
        cv.delete("all")
        cv.create_image(0, 0, anchor="nw", image=cap_image(H, r, track, self._bg, "left"))
        cv.create_image(W, 0, anchor="ne", image=cap_image(H, r, track, self._bg, "right"))
        cv.create_rectangle(r, 0, W - r, H, fill=track, width=0)
        x = 2 + self._pos * (W - K - 4)
        cv.create_image(x, (H - K) // 2, anchor="nw", image=circle_image(K, "#f4f3f1", track))

    def _animate(self):
        target = 1.0 if self.var.get() else 0.0
        if self._anim:
            self.after_cancel(self._anim)
            self._anim = None

        def step():
            d = target - self._pos
            if abs(d) <= 0.21:
                self._pos = target
            else:
                self._pos = round(self._pos + (0.2 if d > 0 else -0.2), 1)
            self._draw()
            if self._pos != target:
                self._anim = self.after(16, step)
            else:
                self._anim = None
        step()


class ThinProgress(tk.Canvas):
    """Тонка (3 px) зелена смужка прогресу аналізу; розуміє progress["value"] і ["maximum"], як ttk.Progressbar."""

    def __init__(self, master, height=3):
        super().__init__(master, height=height, bg=parent_bg(master), highlightthickness=0, bd=0)
        self._val, self._max = 0.0, 100.0
        self.bind("<Configure>", lambda e: self._draw())

    def __setitem__(self, key, value):
        if key == "value":
            self._val = float(value)
        elif key == "maximum":
            self._max = float(value) or 1.0
        else:
            self.configure(**{key: value})
            return
        self._draw()

    def __getitem__(self, key):
        if key == "value":
            return self._val
        if key == "maximum":
            return self._max
        return self.cget(key)

    def _draw(self):
        self.delete("all")
        frac = max(0.0, min(1.0, self._val / self._max)) if self._max else 0.0
        if frac > 0:
            w, h = self.winfo_width(), self.winfo_height()
            self.create_rectangle(0, 0, w * frac, h, fill=ACCENT, width=0)


def round_window(win):
    """Windows 11: заокруглені кути квадрата (DWM) і тонка рамка в колір програми."""
    if sys.platform != "win32":
        return
    try:
        import ctypes
        hwnd = ctypes.windll.user32.GetParent(win.winfo_id()) or win.winfo_id()
        dwm = ctypes.windll.dwmapi.DwmSetWindowAttribute
        v = ctypes.c_int(2)                          # DWMWCP_ROUND
        dwm(hwnd, 33, ctypes.byref(v), ctypes.sizeof(v))
        r, g, b = (int(BORDER[i:i + 2], 16) for i in (1, 3, 5))
        c = ctypes.c_int(r | (g << 8) | (b << 16))    # DWMWA_BORDER_COLOR
        dwm(hwnd, 34, ctypes.byref(c), ctypes.sizeof(c))
    except Exception:  # noqa: BLE001
        pass


def premove_targets(piece, sq):
    """Куди фігура може піти за правилами свого ходу, не зважаючи на інші фігури (хід наперед, 1.25.7)."""
    f, r = chess.square_file(sq), chess.square_rank(sq)
    out = []

    def add(ff, rr):
        if 0 <= ff < 8 and 0 <= rr < 8:
            out.append(chess.square(ff, rr))

    t = piece.piece_type
    if t == chess.KNIGHT:
        for df, dr in ((1, 2), (2, 1), (2, -1), (1, -2), (-1, -2), (-2, -1), (-2, 1), (-1, 2)):
            add(f + df, r + dr)
    elif t == chess.KING:
        for df in (-1, 0, 1):
            for dr in (-1, 0, 1):
                if df or dr:
                    add(f + df, r + dr)
        if f == 4 and r == (0 if piece.color == chess.WHITE else 7):    # рокіровка
            add(6, r)
            add(2, r)
    elif t == chess.PAWN:
        d = 1 if piece.color == chess.WHITE else -1
        add(f, r + d)
        if r == (1 if piece.color == chess.WHITE else 6):
            add(f, r + 2 * d)
        add(f - 1, r + d)
        add(f + 1, r + d)
    else:
        dirs = []
        if t in (chess.BISHOP, chess.QUEEN):
            dirs += [(1, 1), (1, -1), (-1, 1), (-1, -1)]
        if t in (chess.ROOK, chess.QUEEN):
            dirs += [(1, 0), (-1, 0), (0, 1), (0, -1)]
        for df, dr in dirs:
            for k in range(1, 8):
                add(f + df * k, r + dr * k)
    return out


class BoardView(tk.Canvas):
    ANIM_SECONDS = 0.15   # тривалість анімації ходу (1.25.6: 10 кроків по ~15 мс)
    ANIM_DELAY = 5        # мс до першого кадру; далі ~180 кадрів/с (1.25.16, на прохання користувача)

    def __init__(self, master, size=76, on_move=None):
        super().__init__(master, width=size * 8, height=size * 8, bg=BG, highlightthickness=0)
        self.SQ = size
        self.on_move = on_move          # on_move(uci, dragged)
        self.interactive = False
        self.flipped = False
        self.theme = "Ocean"
        self.alien = False              # 1.26.8: «режим прибульця» - своя дошка, фігури й збої
        self.alien_side = "w"           # 1.27.4: чиї фігури - прибульці (колір Witty Alien), у гравця - звичайні
        self._glitch_after = None
        self.fen = chess.STARTING_FEN
        self.last = None
        self.badge = None
        self.arrow = None
        self.shapes = []                # стрілки й кола гравця: ["Ge2e4", "Re4"]
        self.on_shapes = None           # on_shapes(новий список) - гравець змінив позначки
        self._rdrag = None
        self.premove_color = None       # 1.25.3: колір гравця, який може ходити наперед (партія з ботом)
        self.premoves = []              # 1.25.7: черга ходів наперед (uci), як на chess.com
        self.on_premove = None          # on_premove(uci | None)
        self._shape_imgs = {}           # прозорі позначки: (позначка, SQ, flipped) -> (x, y, PhotoImage)
        self.selected = None
        self._drag = None
        self.piece_items = {}
        self._photos = {}
        self._anim_token = 0
        self._anim_after = None
        self.bind("<ButtonPress-1>", self._press)
        self.bind("<B1-Motion>", self._motion)
        self.bind("<ButtonRelease-1>", self._release)
        self.bind("<ButtonPress-3>", self._rpress)       # права кнопка - стрілки й кола
        self.bind("<B3-Motion>", self._rmotion)
        self.bind("<ButtonRelease-3>", self._rrelease)
        self.bind("<Motion>", self._hover)
        self.bind("<Leave>", lambda e: self._set_cursor(""))
        self._cursor = ""
        self._movable = (None, set())   # (fen, клітинки фігур, якими можна ходити)
        self.draw()

    # --- публічні методи
    def set_position(self, fen, last_uci=None, badge=None, arrow_uci=None, shapes=None):
        self._cancel_anim()
        same = fen == self.fen                  # та сама позиція (напр. прийшла оцінка ходу) - фігура в руці лишається
        self.fen, self.last, self.badge, self.arrow = fen, last_uci, badge, arrow_uci
        self.shapes = list(shapes or [])
        keep = self.selected is not None and (
            same or (self.premove_color is not None
                     and self._held_board().color_at(self.selected) == self.premove_color))
        if not keep:                            # партія з ботом: фігура в руці лишається після ходу бота
            self.selected = None
            self._drag = None
        self.draw()

    def set_alien(self, on):
        """1.26.8: дошка прибульця (ALIEN_THEME, ALIEN_PIECES) і раз на кілька секунд «збій» - смуги поверх дошки."""
        on = bool(on)
        if on == self.alien:
            return
        self.alien = on
        if self._glitch_after is not None:
            self.after_cancel(self._glitch_after)
            self._glitch_after = None
        self.draw()
        if on:
            self._glitch_after = self.after(random.randint(1500, 4000), self._glitch)

    def _glitch(self):
        self._glitch_after = None
        if not self.alien:
            return
        S8 = self.SQ * 8
        self.delete("aglitch")
        for _ in range(random.randint(2, 5)):
            y = random.randint(0, S8 - 6)
            h = random.randint(3, max(4, self.SQ // 3))
            x = random.randint(-S8 // 4, S8 // 6)
            self.create_rectangle(x, y, x + random.randint(S8 // 3, S8), y + h, width=0, tags="aglitch",
                                  fill=random.choice(("#39ff14", "#ff1744", "#b388ff", "#00e5ff")),
                                  stipple=random.choice(("gray50", "gray25", "gray75")))
        self.after(random.randint(70, 160), lambda: self.delete("aglitch"))
        self._glitch_after = self.after(random.randint(2500, 8000), self._glitch)

    def set_look(self, theme=None):
        if theme in BOARD_THEMES:
            self.theme = theme
        self._cancel_anim()
        self.draw()

    def set_square(self, size):
        self._cancel_anim()
        self.SQ = size
        self.config(width=size * 8, height=size * 8)
        self.draw()

    def flip(self):
        self._cancel_anim()
        self.flipped = not self.flipped
        self.draw()

    def animate_move(self, fen_before, prev_last, uci, done, badge=None):
        """Плавно пересуває фігуру, потім викликає done(). Колір клітинок і значок ходу - одразу (1.25.14)."""
        self._cancel_anim()
        self.fen, self.last, self.badge, self.arrow = fen_before, uci, badge, None
        self.shapes = []
        if self.premove_color is None or self.selected is None \
                or self._held_board().color_at(self.selected) != self.premove_color:
            self.selected = None                # у партії з ботом своя фігура в руці / вибрана лишається (премув)
            self._drag = None
        self.draw()

        board = chess.Board(fen_before)
        move = chess.Move.from_uci(uci)
        pairs = [(move.from_square, move.to_square)]
        if board.is_castling(move):
            rank = chess.square_rank(move.from_square)
            if chess.square_file(move.to_square) > chess.square_file(move.from_square):
                pairs.append((chess.square(7, rank), chess.square(5, rank)))
            else:
                pairs.append((chess.square(0, rank), chess.square(3, rank)))

        captured_sq = None
        if board.is_en_passant(move):
            captured_sq = chess.square(chess.square_file(move.to_square),
                                       chess.square_rank(move.from_square))
        elif board.is_capture(move):
            captured_sq = move.to_square
        captured_items = list(self.piece_items.get(captured_sq, [])) if captured_sq is not None else []

        movers = []
        for src, dst in pairs:
            ids = list(self.piece_items.get(src, []))
            x1, y1 = self._xy(src)
            x2, y2 = self._xy(dst)
            for it in ids:
                self.tag_raise(it)
            movers.append((ids, x2 - x1, y2 - y1))
        self.tag_raise("badge")                    # значок ходу - над фігурою, що їде

        if not any(m[0] for m in movers):
            done()
            return

        token = self._anim_token
        self._anim_done = done
        state = {"t0": time.perf_counter(), "prev": 0.0, "hidden": False, "frames": 0}
        self._hires(True)

        def tick():
            if token != self._anim_token:
                return
            now = time.perf_counter()
            state["frames"] += 1
            t = min(1.0, (time.perf_counter() - state["t0"]) / self.ANIM_SECONDS)   # 1.25.16: за часом, не за кроками
            e = t * t * (3 - 2 * t)  # плавний старт і зупинка
            de = e - state["prev"]
            state["prev"] = e
            for ids, dx, dy in movers:
                for it in ids:
                    self.move(it, dx * de, dy * de)
            if captured_items and not state["hidden"] and t >= 0.6:
                for it in captured_items:
                    self.delete(it)
                state["hidden"] = True
            if t >= 1.0:
                self._anim_after = None
                self._anim_done = None
                self._anim_frames = state["frames"]
                self._hires(False)
                done()
            else:                                # ~180 кадрів/с: пауза = період мінус час, що забрав сам кадр
                spent = (time.perf_counter() - now) * 1000
                self._anim_after = self.after(max(1, int(1000 / 180 - spent)), tick)

        self._anim_after = self.after(self.ANIM_DELAY, tick)

    def finish_anim(self):
        """Закінчити анімацію ходу одразу (клік під час неї - щоб можна було ходити наперед)."""
        done = getattr(self, "_anim_done", None)
        self._cancel_anim()
        self._anim_done = None
        if done:
            done()

    # --- внутрішнє
    def _hires(self, on):
        """Точний таймер Windows (1 мс) лише на час анімації: інакше after(5) спрацьовує раз на ~15,6 мс."""
        if on == getattr(self, "_hires_on", False) or sys.platform != "win32":
            return
        try:
            import ctypes
            (ctypes.windll.winmm.timeBeginPeriod if on else ctypes.windll.winmm.timeEndPeriod)(1)
            self._hires_on = on
        except Exception:  # noqa: BLE001
            pass

    def _cancel_anim(self):
        self._hires(False)
        self._anim_token += 1
        if self._anim_after is not None:
            try:
                self.after_cancel(self._anim_after)
            except Exception:
                pass
            self._anim_after = None

    def _xy(self, sq):
        S = self.SQ
        f, r = chess.square_file(sq), chess.square_rank(sq)
        if self.flipped:
            return (7 - f) * S, r * S
        return f * S, (7 - r) * S

    def _sq_at(self, x, y):
        S = self.SQ
        if not (0 <= x < S * 8 and 0 <= y < S * 8):
            return None
        cx, cy = int(x // S), int(y // S)
        if self.flipped:
            return chess.square(7 - cx, cy)
        return chess.square(cx, 7 - cy)

    def _photo(self, code):
        # з 1.18.4 фігури більші: картинка 88 px плавно масштабується до SQ*PIECE_SCALE (король ~88% клітинки);
        # прозорі поля картинки виходять за клітинку, сама фігура - всередині
        ps = max(16, round(self.SQ * PIECE_SCALE))
        if self.alien and code[0] == self.alien_side:   # 1.27.4: прибульці - лише фігури Witty Alien (фіолетові)
            acode = "b" + code[1]
            key = ("alien", ps, acode)
            if key not in self._photos:
                data = ALIEN_PIECES[acode] if abs(ps - 88) <= 2 else piece_png(acode, ps, True)
                self._photos[key] = tk.PhotoImage(master=self, data=data)
            return self._photos[key]
        near = min(PIECE_DATA, key=lambda s: abs(s - ps))
        if abs(near - ps) <= 2:
            ps = near                      # готова картинка без масштабування - найчіткіша (HD)
        key = (ps, code)
        if key not in self._photos:
            try:
                data = PIECE_DATA[ps][code] if ps in PIECE_DATA else piece_png(code, ps)
            except Exception:  # noqa: BLE001  - запасний варіант: старі готові розміри
                data = PIECE_DATA[max([s for s in PIECE_DATA if s <= self.SQ] or [min(PIECE_DATA)])][code]
            self._photos[key] = tk.PhotoImage(master=self, data=data)
        return self._photos[key]

    def _run_fx(self, hl, dots):
        """
        Анімації дошки: колір клітинок ходу (оцінка Stockfish) плавно наливається (~0,25 с),
        кружечки можливих ходів «виростають» (~0,12 с). Нове малювання зупиняє попередню анімацію.
        """
        self._fx_token = getattr(self, "_fx_token", 0) + 1
        token = self._fx_token
        frames = 10

        def tick(i=1):
            if token != self._fx_token:
                return
            t = i / frames
            e = 1 - (1 - t) ** 3
            for item, c0, c1 in hl:
                self.itemconfig(item, fill=mix(c0, c1, e))
            k = min(1.0, e * 1.7)                      # кружечки швидші
            for item, cx, cy, r, ring, w in dots:
                rr = r * (0.35 + 0.65 * k)
                self.coords(item, cx - rr, cy - rr, cx + rr, cy + rr)
                if ring:
                    self.itemconfig(item, width=max(1.0, w * k))
            if i < frames:
                self.after(24, tick, i + 1)
        if hl or dots:
            tick()

    def draw(self):
        self.delete("all")
        self.piece_items = {}
        S = self.SQ
        fx_hl, fx_dots = [], []
        pos_key = (self.last, self.badge)      # 1.25.14: без fen - після анімації колір не наливається вдруге
        new_pos = pos_key != getattr(self, "_fx_pos", None)      # колір клітинок анімуємо лише для нового ходу
        self._fx_pos = pos_key
        new_sel = self.selected is not None and self.selected != getattr(self, "_fx_sel", None)
        self._fx_sel = self.selected
        th = ALIEN_THEME if self.alien else BOARD_THEMES[self.theme]
        board = chess.Board(self.fen)
        last_move = chess.Move.from_uci(self.last) if self.last else None
        qcolor = self.badge[0] if self.badge else None

        targets = {}
        if self.selected is not None:
            mb, moves = self._move_board()
            for m in moves:
                if m.from_square == self.selected:
                    targets[m.to_square] = mb.is_capture(m)
        pre_sqs = set()                                 # клітинки ходів наперед
        for u in self.premoves:
            m = chess.Move.from_uci(u)
            pre_sqs.update((m.from_square, m.to_square))
        if self.premoves:                               # фігури - уже на місцях після ходів наперед
            board = self._premove_board()

        for sq in chess.SQUARES:
            x, y = self._xy(sq)
            f, r = chess.square_file(sq), chess.square_rank(sq)
            light = (f + r) % 2 == 1
            base = th["light"] if light else th["dark"]
            color = base
            if last_move and sq in (last_move.from_square, last_move.to_square):
                if qcolor:
                    # клітинки ходу фарбуються кольором його оцінки
                    color = mix(base, qcolor, 0.75 if sq == last_move.to_square else 0.45)
                else:
                    color = th["hl_light"] if light else th["hl_dark"]
            if sq in pre_sqs:
                color = mix(base, "#c0504d", 0.55)    # хід наперед
            if sq == self.selected:
                color = mix(base, "#ffe066", 0.6)
            rect = self.create_rectangle(x, y, x + S, y + S, fill=color, width=0)
            if new_pos and color != base and sq != self.selected and sq not in pre_sqs:   # хід наперед - не «кліпає»
                self.itemconfig(rect, fill=base)
                fx_hl.append((rect, base, color))

            txt_color = th["dark"] if light else th["light"]
            bottom_rank = 7 if self.flipped else 0
            left_file = 7 if self.flipped else 0
            if r == bottom_rank:
                self.create_text(x + S - 7, y + S - 9, text="abcdefgh"[f],
                                 fill=txt_color, font=("Segoe UI", 9, "bold"))
            if f == left_file:
                self.create_text(x + 8, y + 9, text=str(r + 1),
                                 fill=txt_color, font=("Segoe UI", 9, "bold"))

            if sq in targets:
                hint = mix(base, "#000000", 0.28)
                cx, cy = x + S / 2, y + S / 2
                if targets[sq]:
                    it = self.create_oval(x + S * 0.07, y + S * 0.07, x + S * 0.93, y + S * 0.93,
                                          outline=hint, width=S * 0.075)
                    if new_sel:
                        fx_dots.append((it, cx, cy, S * 0.43, True, S * 0.075))
                else:
                    rr = S * 0.17
                    it = self.create_oval(cx - rr, cy - rr, cx + rr, cy + rr, fill=hint, outline="")
                    if new_sel:
                        fx_dots.append((it, cx, cy, rr, False, 0))

        for sq in chess.SQUARES:
            piece = board.piece_at(sq)
            if piece:
                x, y = self._xy(sq)
                code = ("w" if piece.color == chess.WHITE else "b") + piece.symbol().upper()
                item = self.create_image(x + S / 2, y + S / 2, image=self._photo(code))
                self.piece_items[sq] = [item]

        if self.arrow:
            m = chess.Move.from_uci(self.arrow)
            x1, y1 = self._xy(m.from_square)
            x2, y2 = self._xy(m.to_square)
            self.create_line(x1 + S / 2, y1 + S / 2, x2 + S / 2, y2 + S / 2,
                             width=S * 0.13, fill="#ff8a1f", arrow=tk.LAST,
                             arrowshape=(S * 0.26, S * 0.26, S * 0.12), capstyle=tk.ROUND)

        for sh in self.shapes:
            self._draw_shape(sh)

        if self.badge and last_move:
            color, symbol = self.badge
            x, y = self._xy(last_move.to_square)
            if symbol in BADGE_GLYPHS:              # гладкий значок-картинка
                d = int(S * 0.40)
                self.create_image(x + S - d // 2 - 1, y + d // 2 + 1,
                                  image=badge_image(symbol, color, d), tags="badge")
            else:                                    # запасний варіант: коло з текстом
                bx, by = x + S - 14, y + 14
                self.create_oval(bx - 13, by - 13, bx + 13, by + 13,
                                 fill=color, outline="#ffffff", width=2)
                self.create_text(bx, by, text=symbol, fill="#ffffff",
                                 font=("Segoe UI", 9 if len(symbol) > 1 else 11, "bold"))
        d = self._drag                          # фігура в руці лишається в руці після перемальовки (хід бота)
        if d:
            items = self.piece_items.get(d["sq"])
            if items:
                d["item"] = items[0]
                self.tag_raise(items[0])
                if d["moved"] and "x" in d:
                    self.coords(items[0], d["x"], d["y"])
            else:
                self._drag = None
        self._run_fx(fx_hl, fx_dots)

    # --- ходи мишею: перетягування та клік-клік
    def _premoving(self):
        return self.premove_color is not None and (" w " in self.fen) != (self.premove_color == chess.WHITE)

    def _held_board(self):
        """Дошка, на якій гравець бачить фігури: з чергою ходів наперед - уже після них (1.25.11)."""
        return self._premove_board() if self.premoves else chess.Board(self.fen)

    def _premove_board(self):
        """Дошка після всіх ходів наперед (без перевірки правил), хід - за гравцем."""
        board = chess.Board(self.fen)
        board.turn, board.ep_square = self.premove_color, None
        for u in self.premoves:
            m = chess.Move.from_uci(u)
            p = board.remove_piece_at(m.from_square)
            if p is None:
                continue
            ff, tf = chess.square_file(m.from_square), chess.square_file(m.to_square)
            if p.piece_type == chess.KING and abs(tf - ff) == 2:       # рокіровка - і тура
                rank = chess.square_rank(m.from_square)
                rf, rt = (7, 5) if tf > ff else (0, 3)
                rook = board.remove_piece_at(chess.square(rf, rank))
                if rook:
                    board.set_piece_at(chess.square(rt, rank), rook)
            board.set_piece_at(m.to_square, chess.Piece(chess.QUEEN, p.color) if m.promotion else p)
        return board

    def _move_board(self):
        """(дошка, ходи) для вибору ходу; під час ходу суперника - хід наперед (премув): як фігура ходить,
        без огляду на інші фігури (як на chess.com); чи можливий - перевіряється, коли до нього дійде черга."""
        if self._premoving():
            board = self._premove_board()
            moves = []
            for sq in chess.SquareSet(board.occupied_co[self.premove_color]):
                for to in premove_targets(board.piece_at(sq), sq):
                    p = board.piece_at(sq)
                    last = 7 if p.color == chess.WHITE else 0
                    promo = chess.QUEEN if p.piece_type == chess.PAWN and chess.square_rank(to) == last else None
                    moves.append(chess.Move(sq, to, promotion=promo))
            return board, moves
        board = chess.Board(self.fen)
        return board, list(board.legal_moves)

    def _find_move(self, from_sq, to_sq):
        board, moves = self._move_board()
        cands = [m for m in moves if m.from_square == from_sq and m.to_square == to_sq]
        if not cands:
            return None
        for m in cands:                       # перетворення пішака - завжди на ферзя
            if m.promotion == chess.QUEEN:
                return m
        return cands[0]

    def _emit(self, move, dragged):
        self.selected = None
        self._drag = None
        if self._premoving():                       # хід наперед: зіграється, щойно до нього дійде черга
            self.premoves.append(move.uci())
            self.draw()
            if self.on_premove:
                self.on_premove(move.uci())
            return
        if self.on_move:
            self.on_move(move.uci(), dragged)
        else:
            self.draw()

    def _press(self, e):
        if self._anim_after is not None:
            self.finish_anim()                        # клік під час анімації її завершує - можна ходити далі (1.26.1.5: і в аналізі)
        if not self.interactive:
            return
        if self.shapes and self.on_shapes is not None:   # ліва кнопка - стерти всі стрілки й кола (як на lichess)
            self.shapes = []
            self.draw()
            self.on_shapes([])
        sq = self._sq_at(e.x, e.y)
        if sq is None:
            return
        board, _moves = self._move_board()
        if self.selected is not None and sq != self.selected:
            mv = self._find_move(self.selected, sq)   # 1.25.18: хід наперед і на клітинку своєї фігури, якщо вибрана туди ходить
            if mv:
                self._emit(mv, dragged=False)
                return
        piece = board.piece_at(sq)
        if piece and piece.color == board.turn:
            self.selected = sq
            self.draw()
            items = self.piece_items.get(sq)
            if items:
                cx, cy = self.coords(items[0])
                self.tag_raise(items[0])
                self._drag = {"sq": sq, "item": items[0], "x0": e.x, "y0": e.y,
                              "cx": cx, "cy": cy, "moved": False}
        else:
            self.selected = None
            if self.premoves:                         # клік на порожнє місце скасовує ходи наперед
                self._clear_premoves()
            self.draw()

    def _clear_premoves(self):
        self.premoves = []
        if self.on_premove:
            self.on_premove(None)

    def _motion(self, e):
        d = self._drag
        if not d:
            return
        dx, dy = e.x - d["x0"], e.y - d["y0"]
        if abs(dx) + abs(dy) > 5:
            d["moved"] = True
        d["x"], d["y"] = e.x, e.y
        if d["moved"]:
            self._set_cursor(CURSORS["grab"])  # фігуру несуть - кулак
            self.coords(d["item"], e.x, e.y)   # центр фігури - рівно під курсором (як на lichess/chess.com)

    def _set_cursor(self, cur):
        if cur != self._cursor:
            self._cursor = cur
            try:
                self.config(cursor=cur)
            except tk.TclError:                # свій курсор не завантажився - стандартний
                self.config(cursor="hand2" if cur else "")

    def _hover(self, e):
        """Курсор-рука над фігурою, якою можна ходити, і над клітинкою, куди може піти вибрана."""
        if self._drag:
            return
        cur = ""
        if self.interactive and self._anim_after is None and self.fen:
            sq = self._sq_at(e.x, e.y)
            if sq is not None:
                key = (self.fen, self._premoving(), tuple(self.premoves))
                if self._movable[0] != key:
                    self._movable = (key, {mv.from_square for mv in self._move_board()[1]})
                if sq in self._movable[1]:
                    cur = CURSORS["open"]
                elif self.selected is not None and self._find_move(self.selected, sq):
                    cur = CURSORS["open"]
        self._set_cursor(cur)

    def _release(self, e):
        d = self._drag
        self._drag = None
        self._set_cursor("")
        if not d or not d["moved"]:
            return
        target = self._sq_at(e.x, e.y)
        mv = self._find_move(d["sq"], target) if (target is not None and target != d["sq"]) else None
        if mv:
            self._emit(mv, dragged=True)
        else:
            self.draw()               # повернути фігуру на місце

    # --- стрілки й кола правою кнопкою миші (як на lichess)
    def _draw_shape(self, sh, tag=None):
        """Стрілка або коло гравця - напівпрозора картинка (1.25.3); хід конем - стрілка «Г», як на lichess."""
        key = (sh, self.SQ, self.flipped)
        if key not in self._shape_imgs:
            if len(self._shape_imgs) > 300:
                self._shape_imgs.clear()
            self._shape_imgs[key] = self._shape_image(sh)
        got = self._shape_imgs[key]
        if got:
            x, y, img = got
            self.create_image(x, y, image=img, anchor="nw", tags=tag)

    def _shape_image(self, sh):
        try:
            a = chess.parse_square(sh[1:3])
            b = chess.parse_square(sh[3:5]) if len(sh) == 5 else None
        except ValueError:
            return None
        S = self.SQ
        hexc = SHAPE_COLORS.get(sh[0], SHAPE_COLORS["G"])
        rgb = bytes(int(hexc[i:i + 2], 16) for i in (1, 3, 5))
        ax, ay = self._xy(a)
        if b is None:                                   # коло
            w = max(3.0, S * 0.08)
            rows = _fill_polys(S, S, [], [(S / 2, S / 2, S / 2 - 1, S / 2 - 1 - w)])
            return ax, ay, tk.PhotoImage(master=self, data=_png_pal(S, S, rows, rgb, 170))
        bx, by = self._xy(b)
        p0, p2 = (ax + S / 2, ay + S / 2), (bx + S / 2, by + S / 2)
        df = abs(chess.square_file(a) - chess.square_file(b))
        dr = abs(chess.square_rank(a) - chess.square_rank(b))
        pts = [p0, p2]
        if {df, dr} == {1, 2}:                          # хід конем: спершу довша сторона, потім коротша
            corner = (p2[0], p0[1]) if abs(p2[0] - p0[0]) > abs(p2[1] - p0[1]) else (p0[0], p2[1])
            pts = [p0, corner, p2]
        ws, hl, hw = S * 0.15, S * 0.34, S * 0.27       # товщина, довжина й півширина наконечника
        polys = []
        for i in range(len(pts) - 1):
            (x1, y1), (x2, y2) = pts[i], pts[i + 1]
            ln = math.hypot(x2 - x1, y2 - y1) or 1
            ux, uy = (x2 - x1) / ln, (y2 - y1) / ln
            nx, ny = -uy, ux
            last = i == len(pts) - 2
            if i > 0:                                   # стик відрізків - без щілини
                x1, y1 = x1 - ux * ws / 2, y1 - uy * ws / 2
            ex, ey = (x2 - ux * hl, y2 - uy * hl) if last else (x2 + ux * ws / 2, y2 + uy * ws / 2)
            polys.append([(x1 + nx * ws / 2, y1 + ny * ws / 2), (ex + nx * ws / 2, ey + ny * ws / 2),
                          (ex - nx * ws / 2, ey - ny * ws / 2), (x1 - nx * ws / 2, y1 - ny * ws / 2)])
            if last:
                polys.append([(ex + nx * hw, ey + ny * hw), (x2, y2), (ex - nx * hw, ey - ny * hw)])
        xs = [x for poly in polys for x, _ in poly]
        ys = [y for poly in polys for _, y in poly]
        x0, y0 = int(min(xs)) - 1, int(min(ys)) - 1
        w, h = int(max(xs)) - x0 + 2, int(max(ys)) - y0 + 2
        polys = [[(x - x0, y - y0) for x, y in poly] for poly in polys]
        return x0, y0, tk.PhotoImage(master=self, data=_png_pal(w, h, _fill_polys(w, h, polys), rgb, 170))

    def _shape_color(self, e):
        """Колір за клавішами: Shift - червоний, Ctrl - синій, обидві - жовтий; без клавіш - вибраний
        під дошкою колір «Позначки» (з 1.18.11; раніше завжди зелений)."""
        shift, ctrl = bool(e.state & 0x0001), bool(e.state & 0x0004)
        if shift and ctrl:
            return "Y"
        if shift:
            return "R"
        if ctrl:
            return "B"
        return getattr(self, "default_shape", "G")

    def _rpress(self, e):
        self._rdrag = None
        if self.premoves:                             # права кнопка скасовує всі ходи наперед (як на chess.com)
            self._drag, self.selected = None, None
            self._clear_premoves()
            self._set_cursor("")
            self.draw()
            return
        if self._drag or self.selected is not None:   # 1.25.5: права кнопка, поки тримаєш фігуру, - повернути її на місце
            self._drag, self.selected = None, None
            self._set_cursor("")
            self.draw()
            return
        if not self.interactive or self._anim_after is not None or self.on_shapes is None:
            return
        sq = self._sq_at(e.x, e.y)
        if sq is not None:
            self._rdrag = {"from": sq, "color": self._shape_color(e)}

    def _rmotion(self, e):
        pass                                            # 1.25.3: стрілка з'являється лише після відпускання кнопки

    def _rrelease(self, e):
        d = self._rdrag
        self._rdrag = None
        self.delete("shape_preview")
        if not d or not self.interactive:
            return
        sq = self._sq_at(e.x, e.y)
        if sq is None:
            return
        body = chess.square_name(d["from"]) + ("" if sq == d["from"] else chess.square_name(sq))
        same = [s for s in self.shapes if s[1:] == body]
        shapes = [s for s in self.shapes if s[1:] != body]
        if not same or same[0][0] != d["color"]:      # та сама позначка тим самим кольором - стерти
            shapes.append(d["color"] + body)
        self.shapes = shapes
        self.draw()
        self.on_shapes(list(shapes))


class EvalBar(tk.Canvas):
    R = 6                                   # радіус заокруглених кутів шкали

    def __init__(self, master, height):
        self._outer = parent_bg(master)
        super().__init__(master, width=28, height=height, bg=PANEL2, highlightthickness=0)
        self.h = height
        self._cp = 0
        self._flipped = False
        self.set(0)

    def resize(self, height):
        self.h = height
        self.config(height=height)
        self.set(self._cp, self._flipped)

    def set(self, cp, flipped=False):
        """Нова оцінка: смужка плавно доїжджає до неї (~0,2 с)."""
        target = win_percent(cp) / 100
        start = getattr(self, "_wp", None)
        self._cp, self._flipped = cp, flipped
        if getattr(self, "_anim", None):
            self.after_cancel(self._anim)
            self._anim = None
        if start is None or abs(target - start) < 0.004:
            self._draw(target)
            return
        steps = 8

        def tick(i=1):
            t = i / steps
            e = 1 - (1 - t) ** 3                      # м'яке гальмування в кінці
            self._draw(start + (target - start) * e)
            self._anim = self.after(22, tick, i + 1) if i < steps else None
        tick()

    def _draw(self, wp):
        self._wp = wp
        cp, flipped = self._cp, self._flipped
        self.delete("all")
        white_h = wp * self.h
        dark, light = "#3a3733", "#f0efec"
        if flipped:
            self.create_rectangle(0, 0, 28, white_h, fill=light, width=0)
            self.create_rectangle(0, white_h, 28, self.h, fill=dark, width=0)
        else:
            self.create_rectangle(0, 0, 28, self.h - white_h, fill=dark, width=0)
            self.create_rectangle(0, self.h - white_h, 28, self.h, fill=light, width=0)
        # заокруглені кути (колір кута - того шматка шкали, що біля краю)
        top, bot = (light, dark) if flipped else (dark, light)
        r, o = self.R, self._outer
        self.create_image(0, 0, anchor="nw", image=corner_image(r, top, o, "tl"))
        self.create_image(28, 0, anchor="ne", image=corner_image(r, top, o, "tr"))
        self.create_image(0, self.h, anchor="sw", image=corner_image(r, bot, o, "bl"))
        self.create_image(28, self.h, anchor="se", image=corner_image(r, bot, o, "br"))
        if abs(cp) >= MATE_SCORE - 100:
            n = MATE_SCORE - abs(cp)
            txt = f"M{n}" if n else "M"
        else:
            txt = f"{abs(cp) / 100:.1f}"
        white_ahead = cp >= 0
        at_bottom = white_ahead != flipped
        y = self.h - 12 if at_bottom else 12
        color = "#2b2927" if white_ahead else "#f0efec"
        self.create_text(14, y, text=txt, fill=color, font=("Segoe UI", 8, "bold"))


class EvalGraph(tk.Canvas):
    def __init__(self, master, on_click):
        super().__init__(master, height=110, bg=PANEL, highlightthickness=0)
        self.on_click = on_click
        self.evals = []
        self.moves = []
        self.index = 0
        self._hover = None
        self.bind("<Configure>", lambda e: self.redraw())
        self.bind("<Button-1>", self._click)
        self.bind("<B1-Motion>", self._click)
        self.bind("<Motion>", self._on_motion)
        self.bind("<Leave>", lambda e: self._set_hover(None))

    def _k_at(self, x):
        w = max(1, self.winfo_width())
        n = len(self.evals) - 1
        return int(round(min(max(x, 0), w) / w * n))

    def _on_motion(self, e):
        self._set_hover(self._k_at(e.x) if len(self.evals) >= 2 else None)

    def _set_hover(self, k):
        if k != self._hover:
            self._hover = k
            self.redraw()

    def set_data(self, evals, moves):
        self.evals, self.moves = evals, moves
        self.redraw()

    def set_index(self, k):
        self.index = k
        self.redraw()

    def _x(self, i, w):
        n = max(1, len(self.evals) - 1)
        return i / n * w

    def _click(self, e):
        if len(self.evals) < 2:
            return
        w = max(1, self.winfo_width())
        n = len(self.evals) - 1
        k = int(round(min(max(e.x, 0), w) / w * n))
        self.on_click(k)

    def redraw(self):
        """Графік як на chess.com: світла частина - перевага білих, темна - чорних; точки - помітні ходи.
        Під мишею - вертикальна лінія і підказка «хід і оцінка» (з 1.18.0)."""
        self.delete("all")
        w, h = max(1, self.winfo_width()), max(1, self.winfo_height())
        if len(self.evals) < 2:
            self.create_rectangle(0, 0, w, h, fill="#2a2825", width=0)
            self.create_line(0, h / 2, w, h / 2, fill="#3d3a36", dash=(3, 3))
            self.create_text(w / 2, h / 2, text=tr("Графік оцінки з'явиться після аналізу"),
                             fill=MUTED, font=("Segoe UI", 9))
            return
        self.create_rectangle(0, 0, w, h, fill="#34312d", width=0)
        pts = [(self._x(i, w), h * (1 - win_percent(cp) / 100)) for i, cp in enumerate(self.evals)]
        poly = [0, h]
        for x, y in pts:
            poly += [x, y]
        poly += [w, h]
        self.create_polygon(*poly, fill="#e6e4e0", outline="")
        self.create_line(0, h / 2, w, h / 2, fill="#8a857e", dash=(2, 4))
        hk = self._hover
        if hk is not None and 0 <= hk < len(pts):
            self.create_line(pts[hk][0], 0, pts[hk][0], h, fill="#9a958e")
        for i, m in enumerate(self.moves, start=1):
            if m["quality"] in GRAPH_MARKS:
                x, y = pts[i]
                self.create_oval(x - 4, y - 4, x + 4, y + 4, fill=QUALITY[m["quality"]][0], outline=PANEL, width=1.5)
        k = min(self.index, len(pts) - 1)
        x, y = pts[k]
        self.create_line(x, 0, x, h, fill=ACCENT, width=2)
        self.create_oval(x - 4.5, y - 4.5, x + 4.5, y + 4.5, fill=ACCENT, outline=PANEL, width=2)
        if hk is not None and 0 <= hk < len(pts):
            self._tooltip(hk, pts[hk], w)

    def _tooltip(self, k, pt, w):
        """Підказка над графіком: «12. Кf3  +0.8» (хід, на який вказує миша)."""
        if k == 0:
            txt = tr("Початкова позиція")
        elif k - 1 < len(self.moves):
            m = self.moves[k - 1]
            txt = f"{m['label']} {m['san']}"
        else:
            return
        txt += "   " + fmt_eval(self.evals[k])
        f = ("Segoe UI", 9)
        tid = self.create_text(0, 0, text=txt, font=f, fill=FG, anchor="nw")
        x1, y1, x2, y2 = self.bbox(tid)
        tw, th = x2 - x1 + 16, y2 - y1 + 8
        x = min(max(4, pt[0] + 10 if pt[0] + 10 + tw < w else pt[0] - 10 - tw), max(4, w - tw - 4))
        y = 6
        round_rect(self, x, y, x + tw, y + th, 6, fill="#1b1a18", outline="")
        self.coords(tid, x + 8, y + 4)
        self.tag_raise(tid)


FIGURINES = {True: dict(K="♔", Q="♕", R="♖", B="♗", N="♘"), False: dict(K="♚", Q="♛", R="♜", B="♝", N="♞")}


def figurine(san, white):
    """«Nf3» -> «♘f3»: літера фігури значком (як на lichess)."""
    fig = FIGURINES[bool(white)]
    out = fig.get(san[:1], san[:1]) + san[1:] if san and san[0] in fig else san
    return re.sub(r"=([QRBN])", lambda m: "=" + fig[m.group(1)], out)


def fmt_spent(sec):
    if sec is None:
        return ""
    if sec >= 60:
        return f"{int(sec // 60)}m {int(round(sec % 60))}s"
    return f"{sec:.1f}s"


def clock_spent(game):
    """Скільки секунд думав гравець над кожним ходом (з [%clk] у PGN); None, якщо годинника немає."""
    tc = game.headers.get("TimeControl", "")
    m = re.match(r"(\d+)(?:\+(\d+(?:\.\d+)?))?$", tc.strip())
    base = float(m.group(1)) if m else None
    inc = float(m.group(2) or 0) if m else 0.0
    last = {True: base, False: base}
    out = []
    board = game.board()
    for node in game.mainline():
        side = board.turn
        clk = node.clock()
        spent = None
        if clk is not None and last[side] is not None:
            spent = max(0.0, last[side] - clk + inc)
        last[side] = clk if clk is not None else None
        out.append(spent)
        board.push(node.move)
    return out if any(s is not None for s in out) else None


class MoveList(tk.Canvas):
    """
    Список ходів як на lichess: «1. ♘f3 d6» парами, значок якості, справа - смужки часу на хід
    (якщо в PGN є годинник), під ходом - рядки «↳» збережених варіантів. Клік - перейти.
    """
    ROW = 27

    def __init__(self, master, on_ply, on_line, on_node=None):
        super().__init__(master, bg=PANEL, highlightthickness=0, height=6 * self.ROW, takefocus=1)
        self.on_ply, self.on_line, self.on_node = on_ply, on_line, on_node
        self.res, self.lines, self.cur_ply, self.cur_line = None, [], 0, None
        self.cur_node = None                 # позиція у варіанті ("k/e2e4/...") - підсвічений хід
        self.plain = False                   # партія з ботом (1.25.0): без оцінок і значків якості
        self.notes = {}                      # коментарі до ходів (показуються прямо в списку, з 1.18.11)
        self.on_menu = None                  # права кнопка на ході: on_menu(key, line, j, is_main, x, y)
        self.main_keys = set()
        self.hits = []                     # (y1, y2, x1, x2, ("ply", k) або ("line", id))
        self.f = ("Segoe UI", 10)
        self.fs = ("Segoe UI Symbol", 11)
        self.fb = ("Segoe UI", 10, "bold")
        self.bind("<Configure>", lambda e: self.redraw())
        self.bind("<Button-1>", self._click)
        self.bind("<Button-3>", self._menu)
        self.bind("<Motion>", self._hover)
        self.bind("<Leave>", lambda e: (self.delete("hov"), self.config(cursor="")))
        self.bind("<MouseWheel>", lambda e: self.yview_scroll(-1 if e.delta > 0 else 1, "units"))
        self.configure(yscrollincrement=self.ROW)

    def set_data(self, res, lines=None):
        self.res, self.lines = res, list(lines or [])
        self.redraw()

    def select(self, ply=None, line_id=None, node=None):
        self.cur_ply, self.cur_line, self.cur_node = ply, line_id, node
        self.redraw()
        self._see()

    def _see(self):
        for y1, y2, _x1, _x2, (kind, val) in self.hits:
            if (kind == "ply" and val == self.cur_ply and self.cur_line is None and self.cur_node is None) or \
                    (kind == "node" and App._line_key(val[0], val[1]) == self.cur_node):
                h = max(1, self.winfo_height())
                total = float(self.bbox("all")[3] if self.bbox("all") else h)
                top, bot = self.canvasy(0), self.canvasy(h)
                if y1 < top or y2 > bot:
                    self.yview_moveto(max(0.0, (y1 - h / 2 + self.ROW) / max(total, 1)))
                return

    def redraw(self):
        self.delete("all")
        self.hits = []
        w = max(200, self.winfo_width())
        R = self.ROW
        res = self.res
        sel_bg = "#45413c"

        def sel(x1, y1, x2, y2):
            """Вибраний хід: заокруглена «пілюля» із зеленою рискою зліва (з 1.18.0)."""
            round_rect(self, x1, y1, x2, y2, 6, fill=sel_bg, outline="")
            self.create_rectangle(x1 + 1, y1 + 5, x1 + 4, y2 - 5, fill=ACCENT, width=0)

        y = 0
        # «Початкова позиція» (позиція 0)
        if self.cur_ply == 0 and self.cur_line is None:
            sel(4, y + 2, w - 4, y + R - 2)
        self.create_text(14, y + R / 2, text=tr("Початкова позиція"), anchor="w", fill=FG, font=self.f)
        self.hits.append((y, y + R, 0, w, ("ply", 0)))
        y += R
        if not res:
            self.configure(scrollregion=(0, 0, w, y))
            return
        # головна лінія - стовпчиком (як на lichess): номер | хід білих | хід чорних | оцінка.
        # У вільній грі (без партії) головна лінія - перший зіграний варіант, решта - блоки під ходами.
        moves = res["moves"]
        col = []                                         # ходи стовпчика
        after = {}                                       # номер ходу -> варіанти (вузли дерева) під його рядком
        if moves:
            evals = res.get("evals") or []
            for k, m in enumerate(moves, start=1):
                col.append({"label": m["label"], "san": m["san"], "q": m["quality"], "spent": m.get("spent"),
                            "cp": evals[k] if k < len(evals) else None, "hit": ("ply", k),
                            "sel": self.cur_ply == k and self.cur_line is None and self.cur_node is None})
            n = len(moves)
            groups = {}
            for ln in sorted(self.lines, key=lambda l: l["base"]):
                if ln["rows"] and ln.get("id") is not None:
                    groups.setdefault(min(ln["base"] + 1, n), []).append(ln)
            for p_, lns in groups.items():
                after[p_] = self._trie(lns)["kids"]
        else:
            root = self._trie([ln for ln in self.lines if ln["rows"] and ln.get("id") is not None])
            node, j = root, 0
            while node["kids"]:
                main, alts = node["kids"][0], node["kids"][1:]
                j += 1
                pe = main["line"]["pes"][main["j"]] if main["j"] < len(main["line"]["pes"]) else None
                col.append({"label": main["row"]["label"], "san": main["row"]["san"],
                            "q": (("Геніальний" if main["row"].get("fake_bril") else
                                   "Груба помилка" if main["row"].get("fake_blunder") else None) if self.plain
                                  else main["row"].get("quality")),
                            "spent": None, "cp": pe["cp"] if pe and not self.plain else None, "hit": ("node", (main["line"], main["j"])),
                            "sel": main["key"] == self.cur_node})
                if alts:
                    after[j] = alts
                node = main
        n = len(col)
        self.main_keys = {self._hit_key(c["hit"]) for c in col}
        spent = [c["spent"] for c in col]
        have_time = any(s is not None for s in spent)
        tmax = max([s for s in spent if s is not None] or [1.0]) or 1.0
        bar_w = 70 if have_time else 0
        time_x = w - bar_w - 52 if have_time else w
        ev_w = 46                                        # оцінка праворуч у рядку
        cw = max(90, (time_x - ev_w - 48) // 2)         # ширина клітинки ходу
        NUM_W = 40

        def cell(c, x):
            if c["sel"]:
                sel(x - 6, y + 2, x + cw - 6, y + R - 2)
            q = c["q"]
            color, sym, _n = QUALITY.get(q) or (MUTED, "", "")
            if q and sym in BADGE_GLYPHS:
                self.create_image(x + 8, y + R / 2, image=badge_image(sym, color, 16))
            txt_color = color if q in BAD or q in ("Геніальний", "Чудовий") else FG
            self.create_text(x + 20, y + R / 2, text=figurine(c["san"], c["label"].endswith(".")),
                             anchor="w", fill=txt_color, font=self.fs)
            self.hits.append((y, y + R, x - 4, x + cw - 6, c["hit"]))

        k = 1
        while k <= n:
            c = col[k - 1]
            num = c["label"].rstrip(".…")
            white_first = c["label"].endswith(".")
            self.create_rectangle(0, y, NUM_W, y + R, fill="#1c1b19", width=0)       # стовпчик номерів
            self.create_line(0, y + R - 1, w, y + R - 1, fill="#2a2825")
            self.create_text(NUM_W / 2, y + R / 2, text=num, anchor="center", fill="#7d7973", font=self.f)
            plies = []
            if white_first:
                cell(c, 48)
                plies.append(k)
                if k + 1 <= n and not col[k]["label"].endswith("."):
                    cell(col[k], 48 + cw)
                    plies.append(k + 1)
            else:
                self.create_text(48 + 6, y + R / 2, text="…", anchor="w", fill=MUTED, font=self.f)
                cell(c, 48 + cw)
                plies.append(k)
            cp = col[plies[-1] - 1]["cp"]
            if cp is not None:
                self.create_text(time_x - 8, y + R / 2, text=fmt_eval(cp), anchor="e", fill=MUTED,
                                 font=("Segoe UI", 9))
            if have_time:                                # смужки часу: білі зверху, чорні знизу
                for p_ in plies:
                    s = spent[p_ - 1]
                    if s is None:
                        continue
                    white = col[p_ - 1]["label"].endswith(".")
                    yy = y + (7 if white else R - 8)
                    bw = max(2, bar_w * s / tmax)
                    self.create_rectangle(time_x, yy - 3, time_x + bw, yy + 3, width=0,
                                          fill="#e8e6e3" if white else "#7d7974")
                    self.create_text(time_x + bar_w + 6, yy, text=fmt_spent(s), anchor="w",
                                     fill=FG if white else MUTED, font=("Segoe UI", 8))
            y += R
            for p_ in plies:                             # коментарі до ходів рядка - під ним, курсивом
                key = self._hit_key(col[p_ - 1]["hit"])
                if self.notes.get(key):
                    y = self._comment_rows(self.notes[key], y, w)
            for p_ in plies:                             # варіанти - блоком під рядком (як на lichess)
                if after.get(p_):
                    y = self._var_block_nodes(after[p_], y, w)
            k = plies[-1] + 1
        self.configure(scrollregion=(0, 0, w, y))

    # ---- варіанти всередині списку ходів (з 1.18.7, як на lichess)
    VR = 23                                     # висота рядка у блоці варіантів

    def _measure(self, font, text):
        return int(self.tk.call("font", "measure", font, "-displayof", self._w, text))

    @staticmethod
    def _trie(lines):
        """Дерево ходів з варіантів (варіанти з однаковим початком - одна гілка)."""
        root = {"kids": [], "map": {}}
        for ln in lines:
            node = root
            for j, r in enumerate(ln["rows"], start=1):
                ch = node["map"].get(r["uci"])
                if ch is None:
                    ch = {"row": r, "line": ln, "j": j, "kids": [], "map": {}, "key": App._line_key(ln, j)}
                    node["map"][r["uci"]] = ch
                    node["kids"].append(ch)
                node = ch
        return root

    def _var_block_nodes(self, tops, y, w):
        """Блок варіантів під рядком: кожен варіант з нового рядка, гілки в дужках. Повертає новий y."""
        f_main, f_sub = ("Segoe UI Symbol", 10), ("Segoe UI Symbol", 10, "italic")
        x0, x_max = 14, w - 10
        items = []                              # (x, y, text, font, color, node або None)
        pos = {"x": x0, "y": y + 4}

        def put(text, font, color, node=None, gap=4):
            tw = self._measure(font, text)
            if text == ")":
                pos["x"] -= 3                   # дужка впритул до ходу: «(4.dxe5)»
            if pos["x"] > x0 and pos["x"] + tw > x_max:
                pos["x"], pos["y"] = x0 + 10, pos["y"] + self.VR       # перенос рядка (з відступом)
            items.append((pos["x"], pos["y"], text, font, tw, color, node))
            pos["x"] += tw + gap

        def tok(node, numbered, depth):
            r = node["row"]
            white = r["label"].endswith(".")
            san = figurine(r["san"], white)
            text = (r["label"] + san) if (white or numbered) else san
            q = (("Геніальний" if r.get("fake_bril") else "Груба помилка" if r.get("fake_blunder") else None)
                 if self.plain else r.get("quality"))
            color = (QUALITY[q][0] if q in BAD or q in ("Геніальний", "Чудовий") else
                     ("#d9d6d1" if depth == 0 else "#a9a59f"))
            put(text, f_main if depth == 0 else f_sub, color, node)
            note = self.notes.get(node["key"])
            if note:                                     # коментар до ходу - одразу після нього
                for word in note.split():
                    put(word, ("Segoe UI", 9, "italic"), "#c9b98a")

        def emit(node, depth):
            tok(node, True, depth)
            cur, need_num = node, False
            while cur["kids"]:
                main, alts = cur["kids"][0], cur["kids"][1:]
                tok(main, need_num, depth)
                need_num = False
                for alt in alts:                # інші ходи на цьому місці - у дужках
                    put("(", f_sub, MUTED, gap=1)
                    emit(alt, depth + 1)
                    put(")", f_sub, MUTED)
                    need_num = True             # після дужок хід чорних пишемо з номером: «5…Nf6»
                cur = main

        for top in tops:                        # кожен варіант - з нового рядка
            if pos["x"] > x0:
                pos["x"], pos["y"] = x0, pos["y"] + self.VR
            emit(top, 0)
        y_end = pos["y"] + self.VR + 4
        # фон блоку і риска зліва, як на lichess
        self.create_rectangle(4, y + 1, w - 4, y_end - 1, fill="#2a2825", width=0, tags="vbg")
        self.create_rectangle(4, y + 1, 6, y_end - 1, fill="#4a4641", width=0, tags="vbg")
        for x, yy, text, font, tw, color, node in items:
            if node is not None and node["key"] == self.cur_node:
                round_rect(self, x - 3, yy, x + tw + 3, yy + self.VR - 2, 5, fill="#4b6b2f", outline="")
                color = "#ffffff"
            self.create_text(x, yy + (self.VR - 2) / 2, text=text, anchor="w", fill=color, font=font)
            if node is not None:
                self.hits.append((yy, yy + self.VR - 2, x - 3, x + tw + 3, ("node", (node["line"], node["j"]))))
        return y_end

    @staticmethod
    def _hit_key(hit):
        kind, val = hit
        return str(val) if kind == "ply" else App._line_key(val[0], val[1])

    def _comment_rows(self, text, y, w):
        """Коментар до ходу головної лінії - рядок курсивом під ходом (переноситься)."""
        tid = self.create_text(48, y + 4, text=text, anchor="nw", width=w - 60, fill="#c9b98a",
                               font=("Segoe UI", 9, "italic"))
        y2 = self.bbox(tid)[3] + 5
        r = self.create_rectangle(4, y, w - 4, y2, fill="#262420", width=0, tags="vbg")
        self.tag_lower(r)
        return y2

    def _menu(self, e):
        """Права кнопка на ході - меню (коментар; для варіанту - «зробити основним»)."""
        cy = self.canvasy(e.y)
        for y1, y2, x1, x2, (kind, val) in self.hits:
            if y1 <= cy < y2 and x1 <= e.x <= x2 and self.on_menu:
                if kind == "ply":
                    self.on_menu(str(val), None, val, True, e.x_root, e.y_root)
                elif kind == "node":
                    key = App._line_key(val[0], val[1])
                    self.on_menu(key, val[0], val[1], key in self.main_keys, e.x_root, e.y_root)
                return

    def _hover(self, e):
        """Підсвітка ходу під мишею (як на lichess) і курсор-рука."""
        cy = self.canvasy(e.y)
        self.delete("hov")
        for y1, y2, x1, x2, (kind, _val) in self.hits:
            if y1 <= cy < y2 and x1 <= e.x <= x2:
                if kind == "node":
                    r = round_rect(self, x1, y1, x2, y2, 5, fill="#3b3834", outline="", tags="hov")
                else:
                    r = round_rect(self, x1 + 1, y1 + 3, x2 - 1, y2 - 3, 6, fill="#2f2c29", outline="", tags="hov")
                self.tag_lower(r)
                if self.find_withtag("vbg"):
                    self.tag_raise(r, "vbg")
                self.config(cursor="hand2")
                return
        self.config(cursor="")

    def _click(self, e):
        self.focus_set()
        cy = self.canvasy(e.y)
        for y1, y2, x1, x2, (kind, val) in self.hits:
            if y1 <= cy < y2 and x1 <= e.x <= x2:
                if kind == "ply":
                    self.on_ply(val)
                elif kind == "node":
                    self.on_node(*val)
                else:
                    self.on_line(val)
                return


# -------------------------------------------------------------- застосунок ---

class OverlayBox:
    """
    Квадрат поверх програми (налаштування, «Що нового»): з'являється рівно по центру,
    перетягується за заголовок у межах вікна програми, їздить разом з нею і ховається,
    коли програму згортають.
    Це шар без рамки Windows (overrideredirect Toplevel): вкладений Frame через place
    при перетягуванні лишав «сліди» - Windows не встигав перемальовувати те, що під ним.
    """

    def __init__(self, app, title, on_close=None):
        self.app = app
        self.on_close = on_close
        self.is_open = False
        self.off = (0, 0)                              # зсув квадрата від кута програми
        self._drag = None
        box = tk.Toplevel(app, bg=BORDER, bd=0)       # тонка рамка (з 1.18.0 - спокійна, не зелена)
        box.withdraw()
        box.overrideredirect(True)                    # без заголовка і кнопок Windows
        box.transient(app)                            # завжди над програмою
        self.box = box
        app.__dict__.setdefault("_overlays", []).append(self)
        app.bind("<Configure>", lambda e: e.widget is app and self.is_open and self.place(), add="+")
        app.bind("<Unmap>", lambda e: e.widget is app and self.is_open and box.withdraw(), add="+")
        app.bind("<Map>", lambda e: e.widget is app and self.is_open and box.deiconify(), add="+")

        head = tk.Frame(box, bg=PANEL, cursor="fleur")
        head.pack(fill="x", padx=2, pady=(2, 0))
        self.title = tk.Label(head, text=title, bg=PANEL, fg=FG, cursor="fleur",
                              font=fsemi(12), padx=16, pady=10)
        self.title.pack(side="left")
        close = tk.Label(head, text="✕", bg=PANEL, fg=MUTED, cursor="hand2",
                         font=("Segoe UI", 12), padx=14)
        close.pack(side="right")
        close.bind("<Button-1>", lambda e: self.hide())
        close.bind("<Enter>", lambda e: close.configure(fg=FG, bg=PANEL2))
        close.bind("<Leave>", lambda e: close.configure(fg=MUTED, bg=PANEL))
        tk.Frame(box, bg=BORDER, height=1).pack(fill="x", padx=2)      # лінія під заголовком
        for w in (head, self.title):                  # перетягування за заголовок
            w.bind("<ButtonPress-1>", self.drag_start)
            w.bind("<B1-Motion>", self.drag)

    def show(self):
        app, box = self.app, self.box
        for other in getattr(app, "_overlays", []):     # одночасно відкритий лише один квадрат
            if other is not self and other.is_open:
                other.hide()
        self.is_open = True
        app.update_idletasks()
        bw, bh = box.winfo_reqwidth(), box.winfo_reqheight()
        self.off = ((app.winfo_width() - bw) // 2, (app.winfo_height() - bh) // 2)
        self.place()
        try:                                           # плавна поява квадрата (~0,15 с)
            box.attributes("-alpha", 0.0)
        except tk.TclError:
            pass
        box.deiconify()
        box.lift()
        round_window(box)

        def fade(a=0.2):
            try:
                box.attributes("-alpha", min(1.0, a))
            except tk.TclError:
                return
            if a < 1.0 and self.is_open:
                box.after(18, fade, a + 0.2)
        fade()

    def hide(self):
        if not self.is_open:
            return
        self.is_open = False
        self.box.withdraw()
        if self.on_close:
            self.on_close()

    def toggle(self):
        self.hide() if self.is_open else self.show()

    def place(self):
        """Ставить квадрат на його місце відносно вікна програми (в його межах)."""
        app, box = self.app, self.box
        bw = box.winfo_width() if box.winfo_ismapped() else box.winfo_reqwidth()
        bh = box.winfo_height() if box.winfo_ismapped() else box.winfo_reqheight()
        ox = max(0, min(app.winfo_width() - bw, self.off[0]))
        oy = max(0, min(app.winfo_height() - bh, self.off[1]))
        self.off = (ox, oy)
        box.geometry(f"+{app.winfo_rootx() + ox}+{app.winfo_rooty() + oy}")

    def drag_start(self, e):
        self._drag = (e.x_root, e.y_root) + self.off

    def drag(self, e):
        """Тягнемо за заголовок, не випускаючи за межі вікна програми."""
        if not self._drag:
            return
        x0, y0, ox, oy = self._drag
        self.off = (ox + e.x_root - x0, oy + e.y_root - y0)
        self.place()


