    def _set_app_icon(self):
        """
        Значок вікна й панелі задач - як у телефонній версії (зелений квадрат з конем).
        Справжній .ico (з APP_ICON) через iconbitmap: на панелі задач Windows iconphoto не завжди спрацьовує
        і лишалось стандартне перо Tk.
        """
        try:
            import base64
            import struct
            pngs = [(n, base64.b64decode(APP_ICON[n])) for n in sorted(APP_ICON)]
            head = struct.pack("<HHH", 0, 1, len(pngs))
            entries, data, off = b"", b"", 6 + 16 * len(pngs)
            for n, p in pngs:
                entries += struct.pack("<BBBBHHII", n, n, 0, 0, 1, 32, len(p), off)
                data += p
                off += len(p)
            ico = os.path.join(tempfile.gettempdir(), f"chess_analyzer_icon_{APP_VERSION}.ico")
            if not os.path.exists(ico):
                with open(ico, "wb") as f:
                    f.write(head + entries + data)
            self.iconbitmap(default=ico)        # для квадратів (Toplevel)
            self.wm_iconbitmap(ico)             # і саме для головного вікна - без цього значок не ставиться
            return
        except Exception:  # noqa: BLE001
            pass
        try:
            self._icons = [tk.PhotoImage(data=APP_ICON[n]) for n in (64, 48, 32, 16)]
            self.iconphoto(True, *self._icons)
        except tk.TclError:
            pass

    def _typing(self):
        try:
            w = self.focus_get()
        except Exception:
            return False
        if isinstance(w, tk.Text):                   # поле коментаря (а не панель тренера)
            return str(w.cget("state")) == "normal"
        return isinstance(w, (tk.Entry, ttk.Entry, ttk.Spinbox))

    def _key(self, fn):
        def handler(_e):
            if not self._typing():
                fn()
        return handler

    def _depth(self):
        """Глибина з поля «Глибина» (у межах 4-40)."""
        try:
            d = int(self.depth_var.get())
        except (ValueError, tk.TclError):
            d = 14
        return max(4, min(40, d))

    def _fit_window(self):
        if self.state() == "zoomed":      # розгорнуте на весь екран вікно не чіпаємо
            return
        self.update_idletasks()
        w = max(self.winfo_width(), self.winfo_reqwidth())
        h = max(self.winfo_height(), self.winfo_reqheight())
        w = min(w, self.winfo_screenwidth())
        h = min(h, self.winfo_screenheight() - 70)
        self.geometry(f"{w}x{h}")

    # ---------- стиль
    def _setup_style(self):
        """Стиль ttk (з 1.18.0): тонкі смуги прокрутки без стрілок, поля з рамкою-підсвіткою, тонкий прогрес."""
        s = ttk.Style(self)
        s.theme_use("clam")
        field = "#2b2926"
        s.configure(".", background=BG, foreground=FG, fieldbackground=field,
                    bordercolor=BORDER, lightcolor=field, darkcolor=field,
                    font=("Segoe UI", 10), focuscolor=ACCENT)
        s.configure("TFrame", background=BG)
        s.configure("Panel.TFrame", background=PANEL)
        s.configure("TLabel", background=BG, foreground=FG)
        s.configure("Panel.TLabel", background=PANEL, foreground=FG)
        s.configure("Muted.TLabel", background=BG, foreground=MUTED, font=("Segoe UI", 9))
        s.configure("PanelMuted.TLabel", background=PANEL, foreground=MUTED, font=("Segoe UI", 9))
        # підписи розділів: дрібні, приглушені, напівжирні (ОЦІНКА ПАРТІЇ, ВАШ ВАРІАНТ ...)
        s.configure("Section.TLabel", background=PANEL, foreground=MUTED, font=fsemi(8))
        s.configure("Title.TLabel", background=BG, foreground=FG, font=fsemi(15))
        s.configure("PanelTitle.TLabel", background=PANEL, foreground=FG, font=fsemi(12))
        for name in ("TEntry", "TSpinbox", "TCombobox"):
            s.configure(name, fieldbackground=field, foreground=FG, insertcolor=FG, bordercolor=BORDER,
                        lightcolor=field, darkcolor=field, padding=(8, 5), arrowcolor=MUTED,
                        background=field, arrowsize=12)
            s.map(name, bordercolor=[("focus", ACCENT), ("hover", "#4a4641")],
                  lightcolor=[("focus", field)], darkcolor=[("focus", field)],
                  fieldbackground=[("readonly", field), ("disabled", PANEL)],
                  foreground=[("readonly", FG), ("disabled", MUTED)],
                  selectbackground=[("readonly", field)], selectforeground=[("readonly", FG)],
                  background=[("active", "#3b3834"), ("pressed", "#46423d")],
                  arrowcolor=[("active", FG)])
        s.configure("TSpinbox", padding=(6, 4))
        s.configure("TCheckbutton", background=BG, foreground=FG, focuscolor=BG)
        s.map("TCheckbutton", background=[("active", BG)], foreground=[("active", FG)])
        s.configure("Panel.TCheckbutton", background=PANEL, foreground=FG, focuscolor=PANEL)
        s.map("Panel.TCheckbutton", background=[("active", PANEL)], foreground=[("active", FG)])
        s.configure("TButton", background=PANEL2, foreground=FG, padding=(12, 6),
                    borderwidth=0, focusthickness=0)
        s.map("TButton", background=[("active", "#3b3834"), ("disabled", PANEL)],
              foreground=[("disabled", MUTED)])
        # тонкий прогрес аналізу (3 px) і прогрес завантаження оновлення
        s.configure("Horizontal.TProgressbar", troughcolor=PANEL2, background=ACCENT,
                    bordercolor=PANEL2, lightcolor=ACCENT, darkcolor=ACCENT, thickness=6)
        s.configure("Thin.Horizontal.TProgressbar", troughcolor=BG, background=ACCENT,
                    bordercolor=BG, lightcolor=ACCENT, darkcolor=ACCENT, thickness=3)
        s.configure("Treeview", background=PANEL, fieldbackground=PANEL, foreground=FG,
                    rowheight=25, borderwidth=0, bordercolor=PANEL, lightcolor=PANEL, darkcolor=PANEL)
        s.map("Treeview", background=[("selected", "#3d5229")],
              foreground=[("selected", "#ffffff")])
        s.configure("Treeview.Heading", background=PANEL, foreground=MUTED,
                    font=fsemi(8), borderwidth=0, padding=(4, 4), relief="flat",
                    bordercolor=PANEL, lightcolor=PANEL, darkcolor=PANEL)
        s.map("Treeview.Heading", background=[("active", PANEL)])
        s.layout("Treeview", [("Treeview.treearea", {"sticky": "nswe"})])     # без рамки навколо таблиці
        # смуга прокрутки: тонка, без стрілок, повзунок-«пілюля»
        for orient in ("Vertical", "Horizontal"):
            s.layout(f"{orient}.TScrollbar", [(f"{orient}.Scrollbar.trough", {"sticky": "nswe", "children": [
                (f"{orient}.Scrollbar.thumb", {"expand": "1", "sticky": "nswe"})]})])
            s.configure(f"{orient}.TScrollbar", troughcolor=PANEL, background="#45413c", bordercolor=PANEL,
                        lightcolor="#45413c", darkcolor="#45413c", arrowsize=8, gripcount=0, relief="flat")
            s.map(f"{orient}.TScrollbar", background=[("active", "#5a554f"), ("pressed", "#66615a")],
                  lightcolor=[("active", "#5a554f")], darkcolor=[("active", "#5a554f")])
        self.option_add("*TCombobox*Listbox.background", "#2b2926")
        self.option_add("*TCombobox*Listbox.foreground", FG)
        self.option_add("*TCombobox*Listbox.selectBackground", ACCENT)
        self.option_add("*TCombobox*Listbox.selectForeground", "#10200a")
        self.option_add("*TCombobox*Listbox.font", ("Segoe UI", 10))
        self.option_add("*TCombobox*Listbox.borderWidth", 0)
        self.option_add("*TCombobox*Listbox.highlightThickness", 0)

    # ---------- побудова інтерфейсу
    def _make_tree(self, parent, height=None):
        cols = ("ply", "move", "eval", "quality")
        kw = {"height": height} if height else {}
        tree = ttk.Treeview(parent, columns=cols, show="headings", selectmode="browse", **kw)
        for c, t, w, a in (("ply", "№", 60, "center"), ("move", "Хід", 110, "w"),
                           ("eval", "Оцінка", 80, "center"), ("quality", "Якість", 160, "w")):
            tree.heading(c, text=t)
            tree.column(c, width=w, anchor=a)
        for name, (color, _sym, _note) in QUALITY.items():
            tree.tag_configure(name, foreground=color)
        tree.tag_configure("line", background="#2c2a27")   # збережений варіант гравця (↳)
        for key, fn in (("<Left>", lambda: self.step(-1)), ("<Right>", lambda: self.step(1)),
                        ("<Home>", self.go_start), ("<End>", self.go_end),
                        ("<space>", self.toggle_play)):
            tree.bind(key, lambda e, f=fn: (f(), "break")[1])
        return tree

