    def _build_settings_box(self):
        """Налаштування - квадрат поверх програми (OverlayBox), кнопка ⚙ показує його по центру.
        З 1.18.0 - розділи «Вигляд / Аналіз / Оновлення» і перемикачі замість прапорців."""
        self.settings = OverlayBox(self, "⚙  Налаштування", on_close=self._save_config)
        box = self.settings.box
        self.settings_box = box

        self.settings_frame = ttk.Frame(box, style="Panel.TFrame", padding=(20, 14))
        self.settings_frame.pack(fill="both", expand=True, padx=2, pady=(0, 2))
        sf = self.settings_frame
        r = 0

        def section(text, top=0):
            nonlocal r
            ttk.Label(sf, text=text, style="Section.TLabel").grid(row=r, column=0, columnspan=3, sticky="w",
                                                                  pady=(top, 6))
            r += 1

        section("ВИГЛЯД")
        for label, var, values, width in (("Мова", self.lang_var, [n for _c, n in LANGS], 14),
                                          ("Дошка", self.board_var, list(BOARD_THEMES), 14),
                                          ("Розмір", self.size_var, SIZE_CHOICES, 14)):
            ttk.Label(sf, text=label, style="Panel.TLabel").grid(row=r, column=0, sticky="w",
                                                                 padx=(0, 16), pady=4)
            ttk.Combobox(sf, textvariable=var, values=values, state="readonly",
                         width=width).grid(row=r, column=1, sticky="w", pady=4)
            r += 1
        Switch(sf, "Анімація ходів", self.anim_var).grid(row=r, column=0, columnspan=3, sticky="w", pady=(8, 2))
        r += 1
        Switch(sf, "Тренер", self.coach_var).grid(row=r, column=0, columnspan=3, sticky="w", pady=2)
        r += 1
        Switch(sf, "ШІ-тренер (потрібен інтернет)", self.ai_var).grid(row=r, column=0, columnspan=3, sticky="w", pady=2)
        r += 1
        Switch(sf, "Шкала оцінки", self.evalbar_var).grid(row=r, column=0, columnspan=3, sticky="w", pady=2)
        r += 1
        section("АНАЛІЗ", 16)
        ttk.Label(sf, text="Файл рушія", style="Panel.TLabel").grid(row=r, column=0, sticky="w",
                                                                    padx=(0, 16), pady=4)
        ttk.Entry(sf, textvariable=self.engine_var, width=34).grid(row=r, column=1, sticky="ew", pady=4)
        RButton(sf, text="Обрати…", style="Small.TButton", command=self.pick_engine).grid(
            row=r, column=2, sticky="w", padx=(8, 0), pady=4)
        r += 1
        section("ОНОВЛЕННЯ", 16)
        RButton(sf, text="⬆ Перевірити оновлення", style="Small.TButton",
                command=lambda: self.check_update(True)).grid(row=r, column=0, columnspan=3, sticky="w")
        r += 1
        RButton(sf, text="🐞 Повідомити про помилку", style="Small.TButton",
                command=self._open_bug).grid(
            row=r, column=0, columnspan=3, sticky="w", pady=(6, 0))
        r += 1
        section("СТАТИСТИКА", 16)
        Switch(sf, "Надсилати анонімну статистику", self.tele_var).grid(row=r, column=0, columnspan=3, sticky="w",
                                                                        pady=(0, 6))
        r += 1
        self.stats_label = ttk.Label(sf, style="PanelMuted.TLabel", justify="left")
        self.stats_label.grid(row=r, column=0, columnspan=3, sticky="w")
        r += 1
        self._stats, self._stats_time, self._stats_busy = None, 0.0, False
        tk.Frame(sf, bg=BORDER, height=1).grid(row=r, column=0, columnspan=3, sticky="ew", pady=(16, 12))
        r += 1
        btns = ttk.Frame(sf, style="Panel.TFrame")
        btns.grid(row=r, column=0, columnspan=3, sticky="e")
        RButton(btns, text="Скинути налаштування", style="Small.TButton",
                command=self._reset_settings).pack(side="left", padx=(0, 8))
        RButton(btns, text="Готово", style="Accent.TButton", command=self.toggle_settings).pack(side="left")
        sf.columnconfigure(1, weight=1)

    def _draw_color_pick(self):
        """Кольори позначок (стрілки й кола правою кнопкою): вибраний - у світлому кільці."""
        cv = self._color_pick
        cv.delete("all")
        cur = self.shape_color_var.get()
        for i, c in enumerate("GRBY"):
            x = i * 26 + 3
            if c == cur:
                cv.create_image(x, 2, anchor="nw", image=circle_image(20, "#e8e6e3", BG))
                cv.create_image(x + 2, 4, anchor="nw", image=circle_image(16, BG, "#e8e6e3"))
            cv.create_image(x + 4, 6, anchor="nw", image=circle_image(12, SHAPE_COLORS[c],
                                                                      BG if c != cur else BG))
        self.board.default_shape = cur

    def _player_row(self, parent, name_var, acc_var):
        """Рядок гравця над/під дошкою: картка з іменем, праворуч - «пілюля» з точністю (після аналізу)."""
        row = Card(parent, pad=(12, 5), r=8)
        row.pack(fill="x", padx=(34, 0), pady=2)
        tk.Label(row.body, textvariable=name_var, bg=PANEL, fg=FG, font=fsemi(10), bd=0).pack(side="left")
        tk.Frame(row.body, bg=PANEL, width=1, height=BTN_KINDS["acc"]["h"]).pack(side="right")  # стала висота
        chip = RButton(row.body, text="", kind="acc")

        def show(*_a):
            t = acc_var.get()
            if t:
                chip.configure(text=t)
                if not chip.winfo_manager():
                    chip.pack(side="right")
            else:
                chip.pack_forget()
        acc_var.trace_add("write", show)

    def _build_summary(self, parent):
        col = tk.Frame(parent, bg=parent_bg(parent), bd=0, highlightthickness=0)   # стовпець: оцінка + підказка
        col.pack(side="left", anchor="n", fill="y")
        self._sumcol = col
        card = Card(col, pad=(12, 10))
        card.pack(fill="x", anchor="n")
        self.summary_box = card
        box = card.body
        # зверху вниз: точність, далі кожна якість (значок + назва) і скільки таких ходів у білих і чорних
        self.sum_labels = {}
        for c, t in ((1, "●  Білі"), (2, "○  Чорні")):
            ttk.Label(box, text=t, style="Section.TLabel").grid(row=0, column=c + 1, padx=(8, 2), pady=(0, 4))
        ttk.Label(box, text="Точність", style="Panel.TLabel", font=fsemi(10)).grid(
            row=1, column=0, columnspan=2, sticky="w", pady=(0, 2))
        for c in (1, 2):
            lbl = ttk.Label(box, text="–", style="Panel.TLabel", foreground=ACCENT, font=fsemi(11))
            lbl.grid(row=1, column=c + 1, padx=(8, 2), pady=(0, 2))
            self.sum_labels[("Точність", c)] = lbl
        tk.Frame(box, bg=BORDER, height=1).grid(row=2, column=0, columnspan=4, sticky="ew", pady=(4, 6))
        for r, q in enumerate(QUALITY, start=3):
            color, sym, _n = QUALITY[q]
            img = badge_image(sym, color, 16) if sym in BADGE_GLYPHS else None
            (tk.Label(box, image=img, bg=PANEL) if img else tk.Label(box, text=sym, bg=PANEL, fg=color)).grid(
                row=r, column=0, padx=(0, 6), pady=1)
            ttk.Label(box, text=q, style="Panel.TLabel", foreground=color, font=("Segoe UI", 9)).grid(
                row=r, column=1, sticky="w", padx=(0, 8), pady=1)
            for c in (1, 2):
                lbl = ttk.Label(box, text="–", style="Panel.TLabel", font=fsemi(9))
                lbl.grid(row=r, column=c + 1, padx=(8, 2), pady=1)
                self.sum_labels[(q, c)] = lbl
        # 1.26.6 (користувач): пропущені «Геніальні» - скільки, клік на число показує їх по черзі
        r = len(QUALITY) + 3
        tk.Frame(box, bg=BORDER, height=1).grid(row=r, column=0, columnspan=4, sticky="ew", pady=(6, 4))
        tk.Label(box, text="💎", bg=PANEL, fg=QUALITY["Геніальний"][0]).grid(row=r + 1, column=0, padx=(0, 6))
        ttk.Label(box, text="Пропущені геніальні", style="Panel.TLabel", foreground=QUALITY["Геніальний"][0],
                  font=("Segoe UI", 9)).grid(row=r + 1, column=1, sticky="w", padx=(0, 8))
        for c in (1, 2):
            lbl = ttk.Label(box, text="–", style="Panel.TLabel", font=fsemi(9), cursor="hand2")
            lbl.grid(row=r + 1, column=c + 1, padx=(8, 2), pady=1)
            lbl.bind("<Button-1>", lambda e, w=(c == 1): self._goto_missed(w))
            self.sum_labels[("missed", c)] = lbl
        # 1.28.3: надіслати партію як «Партію тижня»
        self.gotw_btn = RButton(box, text="🏆  Подати заявку на гру тижня", kind="small", command=self._open_gotw)
        self.gotw_btn.grid(row=r + 2, column=0, columnspan=4, sticky="ew", pady=(8, 0))

    def _missed_list(self, white):
        """Індекси ходів основної партії, де був пропущений «Геніальний» хід (1.26.6)."""
        res = self.result
        if not res or res.get("free"):
            return []
        return [i for i, m in enumerate(res["moves"])
                if m.get("missed_bril") and (" w " in res["fens"][i]) == white]

    def _goto_missed(self, white):
        """Клік на число пропущених «Геніальних»: наступна така позиція (по колу) зі стрілкою геніального ходу."""
        idx = self._missed_list(white)
        if not idx:
            return
        k = next((i for i in idx if i > self.index or (i == self.index and not self._missed_shown)), idx[0])
        if self.var is not None:
            self._clear_var()
        self.goto(k, animate=False)
        m = self.result["moves"][k]
        self.board.arrow = m["best_uci"]
        self.board.draw()
        n = idx.index(k) + 1
        self._set_info(pick(f"💎 Пропущений геніальний хід {n} з {len(idx)}: {m['label']} {m['best_san']} "
                            f"(зіграно {m['san']}).", f"💎 Missed brilliant move {n} of {len(idx)}: "
                            f"{m['label']} {m['best_san']} ({m['san']} was played)."),
                       pick("Натисни число ще раз — наступний.", "Click the number again for the next one."))
        self._missed_shown = True

    def _insert_start_row(self, cp=None):
        """Список ходів порожній (лише «Початкова позиція»)."""
        self.moves_view.set_data(None)
        self.moves_view.select(0)

    # ---------- конфіг
    def _load_config(self):
        path = ""
        try:
            with open(CONFIG_PATH, encoding="utf-8") as f:
                cfg = json.load(f)
            path = cfg.get("engine", "")
            self.depth_var.set(int(cfg.get("depth", DEFAULTS["depth"])))
            if cfg.get("board") in BOARD_THEMES:
                self.board_var.set(cfg["board"])
            if cfg.get("lang") in dict(LANGS):
                STATE["lang"] = "uk" if cfg["lang"] == "uk" else "en"
                STATE["xl"] = cfg["lang"] if cfg["lang"] in ("pt", "es") else None
            # до 1.14.0 розмір за замовчуванням був Large; тепер - Auto (старе «Large» не переносимо)
            if cfg.get("size_v") == 2 and cfg.get("size") in SIZE_CHOICES:
                self.size_var.set(cfg["size"])
            if cfg.get("arrow") in ARROW_MODES:
                self.arrow_var.set(cfg["arrow"])
            if cfg.get("shape_color") in ("G", "R", "B", "Y"):
                self.shape_color_var.set(cfg["shape_color"])
            if isinstance(cfg.get("chesscom_user"), str):
                self._cc_user = cfg["chesscom_user"]
                if hasattr(self, "cc_user_var"):
                    self.cc_user_var.set(self._cc_user)
            if isinstance(cfg.get("bot_stars"), dict):
                self._bot_stars = {k: int(v) for k, v in cfg["bot_stars"].items() if isinstance(v, int)}
            bc = cfg.get("bot")
            if isinstance(bc, list) and len(bc) == 3 and all(isinstance(x, int) for x in bc[1:]):
                self._bot_sel, self._bot_color_i, self._bot_level_i = str(bc[0]), bc[1], bc[2]
            for key, var in (("anim", self.anim_var), ("coach", self.coach_var),
                             ("evalbar", self.evalbar_var), ("ai_coach", self.ai_var)):
                if isinstance(cfg.get(key), bool):
                    var.set(cfg[key])
        except Exception:
            pass
        self.lang_var.set(dict(LANGS)[ui_lang()])
        if not path or not os.path.exists(path):
            path = bundled_engine() or shutil.which("stockfish") or ""
        self.engine_var.set(path)

    def _save_config(self):
        try:
            with open(CONFIG_PATH, "w", encoding="utf-8") as f:
                json.dump({"engine": self.engine_var.get().strip().strip('"'),
                           "depth": self._depth(),
                           "board": self.board_var.get(),
                           "size": self.size_var.get(), "size_v": 2, "lang": ui_lang(),
                           "arrow": self.arrow_var.get(), "anim": bool(self.anim_var.get()),
                           "coach": bool(self.coach_var.get()),
                           "ai_coach": bool(self.ai_var.get()),
                           "evalbar": bool(self.evalbar_var.get()),
                           "shape_color": self.shape_color_var.get(),
                           "chesscom_user": self._cc_user,
                           "bot": [self._bot_sel, self._bot_color_i, self._bot_level_i],
                           "bot_stars": self._bot_stars}, f)
        except Exception:
            pass

    # ---------- завантаження партії
    def pick_engine(self):
        path = filedialog.askopenfilename(
            title=tr("Оберіть файл Stockfish (.exe)"),
            filetypes=[(tr("Програми"), "*.exe"), (tr("Усі файли"), "*.*")])
        if path:
            self.engine_var.set(path)

    def load_clipboard(self):
        try:
            text = self.clipboard_get()
        except tk.TclError:
            messagebox.showwarning(trd("Увага", "Warning"), tr("Буфер обміну порожній. Скопіюй PGN партії."))
            return
        self._load_pgn(text)

    def load_file(self):
        path = filedialog.askopenfilename(
            title=tr("Оберіть PGN"), filetypes=[("PGN", "*.pgn"), (tr("Усі файли"), "*.*")])
        if path:
            with open(path, encoding="utf-8", errors="ignore") as f:
                self._load_pgn(f.read())

    def _load_pgn(self, text):
        tele_count("f.pgn")
        try:
            game = chess.pgn.read_game(io.StringIO(text))
        except Exception:
            game = None
        if game is None or not list(game.mainline_moves()):
            messagebox.showerror(trd("Помилка", "Error"), tr("Не вдалося прочитати PGN або в ньому немає ходів."))
            return
        self.game = game
        h = game.headers
        self._stop_play()
        self._new_doc()               # нова партія - не розділ відкритого дослідження
        self._reset_view()
        white, black = h.get("White", "Білі"), h.get("Black", "Чорні")
        self._set_names(white, h.get("WhiteElo", ""), black, h.get("BlackElo", ""))
        self.status_var.set(f"{tr('Завантажено:')} {white} — {black}")
        self.start_analysis()

    def _start_free(self, res=None):
        """
        Дошка в початковій позиції: можна ходити одразу, без PGN.
        res - уже готовий «вільний» результат (розділ дослідження без партії).
        """
        self._stop_play()
        self._clear_var()
        if res is None:
            self._new_doc()
            res = {
                "free": True,
                "fens": [chess.STARTING_FEN],
                "evals": [0],
                "pos_info": [None],          # оцінку стартової позиції порахує перший хід
                "moves": [],
                "book_path": [True],
                "depth": None,
                "summary": {"white": "Білі", "black": "Чорні", "white_rating": None,
                            "black_rating": None, "white_acc": 0.0, "black_acc": 0.0,
                            "white_counts": {}, "black_counts": {}, "result": "*", "opening": None},
            }
        self.game = None
        self.result = res
        self.index = 0
        self._set_names("Білі", "", "Чорні", "")
        self.top_acc.set("")
        self.bot_acc.set("")
        for lbl in self.sum_labels.values():
            lbl.config(text="–")
        self._insert_start_row()
        self._render_lines()
        self.graph.set_data([], [])
        self.board.set_position(res["fens"][0])
        self.goto(0, animate=False)
        self.status_var.set(tr("Грай з початкової позиції: перетягни фігуру або клікни її."))
        if self._book is None:   # база дебютів для міток «Теорія» вантажиться у фоні
            threading.Thread(target=self._preload_book, daemon=True).start()

    def _preload_book(self):
        try:
            self._get_book()
        except Exception:  # noqa: BLE001
            pass

    def _set_names(self, white, we, black, be):
        w = f"●  {tr(white)}" + (f"  ({we})" if we else "")
        b = f"○  {tr(black)}" + (f"  ({be})" if be else "")
        if self.board.flipped:
            self.top_name.set(w)
            self.bot_name.set(b)
        else:
            self.top_name.set(b)
            self.bot_name.set(w)
        self._names = (white, we, black, be)

    def _reset_view(self):
        self._clear_var()
        self.result = None
        self.index = 0
        self.board.interactive = False
        self._insert_start_row()
        self.top_acc.set("")
        self.bot_acc.set("")
        for lbl in self.sum_labels.values():
            lbl.config(text="–")
        self.graph.set_data([], [])
        self.board.set_position(chess.STARTING_FEN)
        self.evalbar.set(0, self.board.flipped)
        self.info_var.set("")

    # ---------- аналіз
    def start_analysis(self):
        if not self.game:
            messagebox.showinfo(trd("Підказка", "Tip"), tr("Спочатку завантаж партію (PGN з буфера або файл)."))
            return
        path = self.engine_var.get().strip().strip('"')
        if not path or not os.path.exists(path):
            messagebox.showwarning(trd("Увага", "Warning"), tr("Вкажіть шлях до файлу Stockfish (.exe)."))
            return
        if path.lower().endswith(".py"):
            messagebox.showerror(trd("Помилка", "Error"), tr("Це Python-скрипт, а не рушій. Оберіть .exe файл Stockfish."))
            return
        self._save_config()
        self._clear_var()
        self.board.interactive = False
        self._cancel = False
        self.run_btn.config(state="disabled")
        self.progress["value"] = 0
        self.status_var.set(tr("Аналіз…"))
        game, depth = self.game, self._depth()
        doc = self._doc_id             # якщо на дошку відкриють іншу партію - цей аналіз зупиниться

        def worker():
            try:
                book = self._get_book()
                res = analyze_game(
                    game, path, depth,
                    progress=lambda i, n, part=None: self.q.put(("progress", i, n, part, doc)),
                    should_cancel=lambda: self._cancel or doc != self._doc_id,
                    book=book)
                self.q.put(("done", res, doc))
            except Exception as e:  # noqa: BLE001
                self.q.put(("error", str(e), doc))

        self._jobs += 1
        threading.Thread(target=worker, daemon=True).start()
        if self._jobs == 1:
            self.after(100, self._poll)

    def _get_book(self):
        """Завантажує (за потреби) та кешує базу дебютів. Викликається з робочого потоку."""
        if self._book is not None:
            return self._book or None
        try:
            missing = [l for l in "abcde"
                       if not os.path.exists(os.path.join(OPENINGS_DIR, f"{l}.tsv"))]
            if missing:
                self.q.put(("status", tr("Завантажую базу дебютів…")))
                download_openings()
            self.q.put(("status", tr("Готую базу дебютів…")))
            self._book = load_opening_book()
            self._book_error = None if self._book else tr("порожня база")
        except Exception as e:  # noqa: BLE001
            self._book = {}
            self._book_error = str(e)
        return self._book or None

    def _poll(self):
        part = None
        try:
            while True:
                msg = self.q.get_nowait()
                kind = msg[0]
                if kind == "status":
                    self.status_var.set(msg[1])
                    continue
                stale = msg[-1] != self._doc_id      # аналіз партії, якої вже немає на дошці
                if kind == "progress":
                    if not stale:
                        _, i, n, part_i, _doc = msg
                        self.progress["maximum"] = n
                        self.progress["value"] = i
                        self.status_var.set(f"{tr('Аналіз…')} {tr('хід')} {i} {tr('з')} {n}  ·  "
                                            + pick("готові ходи вже можна дивитися", "finished moves can be viewed already"))
                        if part_i is not None:
                            part = part_i
                elif kind in ("done", "error"):
                    self._jobs = max(0, self._jobs - 1)
                    if stale:
                        continue
                    part = None
                    self.run_btn.config(state="normal")
                    if kind == "done":
                        tele_analysis(msg[1])
                        self._show_results(msg[1])
                    else:
                        if self.result and self.result.get("partial"):    # лишаємо те, що встигли
                            self.result.pop("partial", None)
                            self._partial_seen = False
                            self.goto(self.index, animate=False)
                        self.status_var.set(tr("Помилка аналізу"))
                        messagebox.showerror(trd("Помилка", "Error"), msg[1])
        except queue.Empty:
            pass
        if part is not None and self._jobs > 0:
            self._show_partial(part)
        if self._jobs > 0:
            self.after(100, self._poll)

    # ---------- результати
    def _show_partial(self, res):
        """Проміжний результат аналізу (1.22.0): готові ходи видно й можна гортати, поки рушій рахує далі.
        Дошка в цей час лише для перегляду (без власних варіантів), розділ дослідження не зберігається."""
        first = not (self.result and self.result.get("partial"))
        self._partial_seen = True
        if first and self.var is not None:
            self._clear_var()
        self.result = res                     # 1.26.7: варіант гравця не скидається - ходити можна під час аналізу
        self.moves_view.set_data(res, self.lines)
        self.graph.set_data(res["evals"], res["moves"])
        self._fill_summary(res["summary"])
        n = len(res["fens"]) - 1
        if first:
            self.goto(0, animate=False)
        elif self.var is not None:
            v, j = self.var, self.var["index"]
            if j >= 1 and any(ln is v for ln in self.lines):
                self.moves_view.select(ply=None, node=self._line_key(v, j))
            else:
                self.moves_view.select(ply=v["base"])
        elif self.index <= n:
            self.moves_view.select(ply=self.index)
            self.graph.set_index(self.index)

    def _show_results(self, res, save=True):
        self.result = res
        if save and self.chapter is not None:     # перерахували розділ дослідження - зберігаємо
            self.chapter["result"] = res
            self._autosave()
        s = res["summary"]
        extra = ""
        if s.get("opening"):
            extra = f"  ·  {s['opening'][0]} {s['opening'][1]}"
        elif self._book_error:
            extra = "  ·  " + tr("без теорії (базу дебютів не завантажено)")
        self.status_var.set(f"{tr('Готово')} · {tr('результат')} {s['result']}{extra}")

        self.moves_view.set_data(res, self.lines)

        self.graph.set_data(res["evals"], res["moves"])
        self._fill_summary(s)
        self._render_lines()
        self._puzzles_collect(res)
        self.board.interactive = True
        keep = self._partial_seen and 0 <= self.index < len(res["fens"])
        self._partial_seen = False
        if keep and self.var is not None:      # 1.26.7: гравець у своєму варіанті - лишаємо його там
            self._show_var_state(self.var["index"])
            return
        self.goto(self.index if keep else 0, animate=False)   # гравець уже гортав готові ходи - лишаємо там

    def _fill_summary(self, s):
        self.sum_labels[("Точність", 1)].config(text=f"{s['white_acc']:.1f}%")
        self.sum_labels[("Точність", 2)].config(text=f"{s['black_acc']:.1f}%")
        for q in QUALITY:
            self.sum_labels[(q, 1)].config(text=str(s["white_counts"].get(q, 0)))
            self.sum_labels[(q, 2)].config(text=str(s["black_counts"].get(q, 0)))
        for c in (1, 2):
            n = len(self._missed_list(c == 1))
            self.sum_labels[("missed", c)].config(text=str(n), foreground=QUALITY["Геніальний"][0] if n else FG)
        self._update_acc_labels()

    def _update_acc_labels(self):
        if not self.result or self.result.get("free"):
            return
        # 1.27.14: у пігулці лише час з годинника партії (точність - в «Оцінці партії»)
        cw, cb = (clock_at(self.result, self.index, x) for x in (True, False))
        w = f"⏱ {fmt_clock(cw)}" if cw is not None else ""
        b = f"⏱ {fmt_clock(cb)}" if cb is not None else ""
        if self.board.flipped:
            self.top_acc.set(w)
            self.bot_acc.set(b)
        else:
            self.top_acc.set(b)
            self.bot_acc.set(w)

    # ---------- навігація основною лінією
    def step(self, delta):
        if self.var is not None:
            if self._var_busy:
                return
            j = self.var["index"] + delta
            if j < 0:
                self.exit_var()
            else:
                self.goto_var(j)
        else:
            self.goto(self.index + delta)

    def go_start(self):
        if self.var is not None:
            self._clear_var()
        self.goto(0)

    def go_end(self):
        if self.var is not None:
            if not self._var_busy:
                self.goto_var(len(self.var["rows"]))
        else:
            self.goto(10 ** 6)

    def jump(self, k):
        """Перехід до ходу основної партії (граф, список ходів)."""
        if self.var is not None:
            if self._var_busy:
                return
            self._clear_var()
        self.goto(k)

    def goto(self, k, animate=None):
        if not self.result:
            return
        if self.var is not None:
            self._clear_var()
        res = self.result
        n = len(res["fens"]) - 1
        k = max(0, min(n, k))
        self._missed_shown = False             # 1.26.6: показ пропущеного «Геніального» - лише після _goto_missed
        prev_index = self.index
        self.index = k
        self._update_acc_labels()
        if animate is None:
            animate = (k == prev_index + 1)

        last = badge = arrow = None
        info = tr("Початкова позиція")
        rec = self._recommend(res["fens"][k], res["pos_info"][k])
        if k >= 1:
            m = res["moves"][k - 1]
            last = m["uci"]
            color, symbol, note = QUALITY[m["quality"]]
            badge = (color, symbol)
            info = f"{m['label']} {m['san']} — {qname(m['quality'])}.  {tr(note)}"
            if m.get("book") and m.get("opening"):
                info += f"  {m['opening']}"
            info += best_was(m)
        adv = ""
        if rec and k < n and not self._bot_live():
            d = res["pos_info"][k].get("depth") or res.get("depth")
            adv = f"{to_move(res['fens'][k])} — {tr('Stockfish радить:')} {rec}" + (f"  ({tr('глибина')} {d})" if d else "")
        arrow = self._best_arrow(res["moves"][k - 1] if k >= 1 else None,
                                 res["pos_info"][k] if k < n else None)

        fen = res["fens"][k]
        shapes = self.shapes.get(str(k), [])
        if animate and k >= 1 and self.anim_var.get():
            prev_last = res["moves"][k - 2]["uci"] if k >= 2 else None
            self.board.animate_move(
                res["fens"][k - 1], prev_last, last,
                lambda f=fen, l=last, b=badge, a=arrow, s=shapes: self.board.set_position(f, l, b, a, s), badge)
        else:
            self.board.set_position(fen, last, badge, arrow, shapes)

        self.board.interactive = True          # 1.26.7: і поки аналіз партії ще йде
        self.evalbar.set(res["evals"][k], self.board.flipped)
        self.graph.set_index(k)
        on_path = res["book_path"][k] if k < len(res.get("book_path", [])) else True
        self._set_info(info, adv, self._theory_line(fen, on_path))
        self._ask_set_main(k)
        self._coach_show(self._coach_main(k), ai=self._ai_main(k))
        self.moves_view.select(ply=k)
        self._show_note()
        if self.bot or self._bot_ui_on:
            self.after(30, self._bot_tick)

    def _coach_show(self, lines, ai=None):
        """Панель тренера. ai - дані ходу для ШІ-тренера (1.23.2): поки він думає або якщо недоступний,
        показується звичайний тренер; готове пояснення замінює пункти."""
        self._coach_lines = lines
        self._ai_cur = None
        self._ai_btn_show(False)
        if self._bot_live():                 # партія з ботом: замість тренера - репліки бота (ШІ)
            self._bot_coach_render()
            return
        if ai and self.ai_var.get() and not self._ai_off:
            key = (ai[0], ai[1], ui_lang(), ai[2])      # з 1.23.7 - і якість (рання відповідь за швидкою оцінкою)
            self._ai_cur, self._ai_cur_args = key, ai
            if key in self._ai_cache:
                self._coach_render(lines, ai_text=self._ai_cache[key])
                return
            if key in self._ai_busy:
                self._coach_render(lines, waiting=True)
                return
            # 1.28.1: ШІ - лише після кнопки «Пояснити» (раніше питав сам на кожен хід і з'їдав ліміт)
            self._coach_render(lines, note=key in self._ai_failed)
            self._ai_btn_show(True)
            return
        self._coach_render(lines, note=bool(ai and self.ai_var.get()))

    def _ai_btn_show(self, on):
        b = getattr(self, "ai_btn", None)
        if b is None:
            return
        if not on:
            if b.winfo_manager():
                b.pack_forget()
            return
        left = ai_quota_left()
        if left > 0:
            b.configure(state="normal", text=pick(f"🤖  Пояснити (ШІ) · ще {left} з {AI_DAILY} сьогодні",
                                                  f"🤖  Explain (AI) · {left} of {AI_DAILY} left today"))
        else:
            b.configure(state="disabled", text=pick(f"🤖  Ліміт ШІ на сьогодні вичерпано ({AI_DAILY})",
                                                    f"🤖  AI limit for today is used up ({AI_DAILY})"))
        if not b.winfo_manager():
            b.pack(anchor="w", pady=(8, 0), after=self.coach)

    def _ai_click(self):
        key, ai = self._ai_cur, self._ai_cur_args
        if key is None or not ai or ai_quota_left() <= 0 or key in self._ai_busy:
            return
        self._ai_failed.pop(key, None)
        self._ai_btn_show(False)
        self._coach_render(self._coach_lines, waiting=True)
        self._ai_start(key, ai)

    def _ai_note(self):
        err = self._ai_err
        if not err:
            return ""
        if err == "quota":
            return pick("🤖 ШІ-тренер на сьогодні вичерпав безплатний ліміт — працює звичайний тренер.",
                        "🤖 The AI coach has used up today's free limit — the regular coach is shown.")
        if err == "rate":
            return pick("🤖 Забагато запитів до ШІ-тренера — спробуйте за хвилину.",
                        "🤖 Too many AI coach requests — try again in a minute.")
        if err == "net":
            return pick("🤖 ШІ-тренер недоступний (немає інтернету?) — працює звичайний тренер.",
                        "🤖 The AI coach is unavailable (no internet?) — the regular coach is shown.")
        return pick("🤖 ШІ-тренер зараз не відповів — працює звичайний тренер.",
                    "🤖 The AI coach did not answer — the regular coach is shown.")

    def _coach_render(self, lines, ai_text=None, waiting=False, note=False, head=None):
        self._coach_last = (lines, ai_text, waiting, note, head)
        t = self.coach
        t.config(state="normal")
        t.delete("1.0", "end")
        if head:                             # свій заголовок (бот) - рядки без позначок
            t.insert("end", head + "\n", "head")
            for ln in lines:
                t.insert("end", ln + "\n", "item")
        elif ai_text or waiting:
            # 1.23.3: поки ШІ думає - лише його заголовок; звичайний тренер - тільки якщо ШІ недоступний
            t.insert("end", pick("🤖 ШІ-тренер", "🤖 AI coach") + "\n", "head")
            if ai_text:
                t.insert("end", ai_text + "\n", "ai")
            else:
                t.insert("end", pick("Думає…", "Thinking…") + "\n", "muted")
        else:
            t.insert("end", pick("🎓 Тренер", "🎓 Coach") + "\n", "head")
            for ln in lines:
                t.insert("end", "•  " + ln + "\n", "item")
            if note and self._ai_note():
                t.insert("end", self._ai_note() + "\n", "muted")
        # запитання гравця до цієї позиції і відповіді ШІ (1.23.5)
        thread = self._ask_threads.get(self._ask_key(), []) if self.ai_var.get() else []
        for it in thread:
            t.insert("end", "❓ " + it["q"] + "\n", "q")
            if it.get("a"):
                t.insert("end", it["a"] + "\n", "ai")
            elif it.get("err"):
                t.insert("end", self._ask_err_text(it["err"]) + "\n", "muted")
            else:
                t.insert("end", pick("Думає…", "Thinking…") + "\n", "muted")
        t.config(state="disabled")
        if thread:
            t.see("end")

    def _ai_main(self, k):
        res = self.result
        try:
            if k <= 0 or res.get("free"):
                return None
            m = res["moves"][k - 1]
            if not m.get("quality"):
                return None
            return (res["fens"][k - 1], m["uci"], m["quality"], m.get("best_san") or "",
                    res["pos_info"][k - 1], res["pos_info"][k])
        except (AttributeError, IndexError, KeyError, TypeError):
            return None

    def _ai_var_args(self, j):
        v = self.var
        try:
            row = v["rows"][j - 1]
            if row.get("pending") or not row.get("quality") or v["pes"][j] is None:
                return None
            return (v["fens"][j - 1], row["uci"], row["quality"], row.get("best_san") or "", v["pes"][j - 1], v["pes"][j])
        except (IndexError, KeyError, TypeError):
            return None

    def _ai_request(self, key, ai):
        """Запит до ШІ-тренера - із затримкою 0,35 с, щоб швидке гортання ходів не слало зайвих запитів."""
        if self._ai_after:
            self.after_cancel(self._ai_after)
        self._ai_after = self.after(350, lambda: self._ai_start(key, ai))

    def _ai_prefetch(self, ai):
        """1.23.7: ШІ починає думати, щойно є швидка оцінка ходу (повний аналіз Stockfish ще йде).
        Якщо повна оцінка дасть ту саму якість ходу - пояснення вже готове або в дорозі."""
        return                     # 1.28.1: вимкнено - ШІ лише після кнопки «Пояснити» (ліміт)

    def _ai_start(self, key, ai, force=False):
        if not force:
            self._ai_after = None
        if (key != self._ai_cur and not force) or key in self._ai_busy:
            return
        try:
            facts = ai_facts(*ai)
        except Exception:  # noqa: BLE001
            self._ai_failed[key] = time.time()
            self._ai_err = "facts"
            if key == self._ai_cur:
                self._coach_render(self._coach_lines, note=True)
            return
        self._ai_busy.add(key)
        lang = key[2]
        tele_count("f.ai")

        def work():
            try:
                self._aiq.put((key, fetch_ai_coach(facts, lang), None))
            except Exception as e:  # noqa: BLE001
                self._aiq.put((key, None, str(e)))
        threading.Thread(target=work, daemon=True).start()
        if not self._ai_polling:
            self._ai_polling = self.after(150, self._ai_poll)

    # ---- запитання до ШІ-тренера (1.23.5) ----
    def _ask_key(self):
        c = self._ask_ctx
        return (c["fen"], tuple(c["sans"])) if c else None

    def _ask_set_main(self, k):
        res = self.result
        try:
            sans = [m["san"] for m in res["moves"][:k]]
            self._ask_ctx = {"fen": res["fens"][k], "pe": res["pos_info"][k], "sans": sans, "last": self._ai_main(k)}
        except (AttributeError, IndexError, KeyError, TypeError):
            self._ask_ctx = None

    def _ask_set_var(self, j):
        v, res = self.var, self.result
        try:
            sans = [m["san"] for m in res["moves"][:v["base"]]] + [r["san"] for r in v["rows"][:j]]
            pe = v["pes"][j] or {}
            self._ask_ctx = {"fen": v["fens"][j], "pe": pe, "sans": sans, "last": self._ai_var_args(j) if j else None}
        except (AttributeError, IndexError, KeyError, TypeError):
            self._ask_ctx = None

    def _ask_hint(self, on):
        """Підказка в порожньому полі запитання."""
        e = self.ask_entry
        try:
            focused = self.focus_get() is e
        except (KeyError, tk.TclError):
            focused = False
        if on and not e.get().strip() and not focused:
            e.delete(0, "end")
            if self._bot_ui_on and self.bot:          # 1.27.11: чат з ботом
                e.insert(0, pick("Написати ботові…", f"Message {bot_name(self.bot['spec'])}…"))
            else:
                e.insert(0, pick("Спитати ШІ-тренера про позицію…", "Ask the AI coach about the position…"))
            e.config(fg=MUTED)
            self._ask_hint_on = True
        elif not on and self._ask_hint_on:
            e.delete(0, "end")
            e.config(fg=FG)
            self._ask_hint_on = False

    def _ask_row_update(self):
        # 1.27.11: у партії з ботом це поле - чат з ботом (без інтернету бот відповідає запасною фразою)
        if self.ai_var.get() or self._bot_ui_on:
            if not self.ask_row.winfo_ismapped():
                self.ask_row.pack(fill="x", pady=(8, 0))
        else:
            self.ask_row.pack_forget()
        if getattr(self, "_ask_hint_on", False):          # підказка в полі - для потрібного режиму
            self._ask_hint_on = False
            self.ask_entry.delete(0, "end")
            self._ask_hint(True)

    def _ask_err_text(self, err):
        if err == "limit":
            return pick(f"🤖 Ліміт ШІ на сьогодні вичерпано ({AI_DAILY} пояснень і запитань). Завтра знову.",
                        f"🤖 Today's AI limit is used up ({AI_DAILY} explanations and questions). Back tomorrow.")
        if err == "quota":
            return pick("🤖 ШІ-тренер на сьогодні вичерпав безплатний ліміт.", "🤖 The AI coach has used up today's free limit.")
        if err == "rate":
            return pick("🤖 Забагато запитів — спробуйте за хвилину.", "🤖 Too many requests — try again in a minute.")
        if err == "net":
            return pick("🤖 Немає зв'язку з ШІ-тренером (немає інтернету?).", "🤖 Can't reach the AI coach (no internet?).")
        return pick("🤖 ШІ-тренер зараз не відповів — спробуйте ще раз.", "🤖 The AI coach did not answer — try again.")

    def _ask_clear(self):
        """Очистити чат з ШІ-тренером у поточній позиції (відповіді, що ще йдуть, нікуди не потраплять)."""
        if self._bot_ui_on and self.bot:                 # 1.27.11: чат з ботом
            self.bot["chat"] = [x for x in self.bot["chat"] if not isinstance(x, dict)]
            self._bot_coach_render()
            return
        if self._ask_threads.pop(self._ask_key(), None) is not None:
            self._coach_render(*self._coach_last)

    def _ask_send(self):
        if self._ask_hint_on:
            return
        q = self.ask_entry.get().strip()[:500]
        if self._bot_ui_on and self.bot:                 # 1.27.11: повідомлення ботові
            if q and self._bot_live():
                self._bot_chat_send(q[:300])
            return
        ctx, key = self._ask_ctx, self._ask_key()
        if not q or not ctx or not self.ai_var.get():
            return
        self.ask_entry.delete(0, "end")
        thread = self._ask_threads.setdefault(key, [])
        history = [{"q": it["q"], "a": it["a"]} for it in thread if it.get("a")]
        item = {"q": q, "a": None, "err": None}
        thread.append(item)
        if ai_quota_left() <= 0:                     # 1.28.1: ліміт на сьогодні
            item["err"] = "limit"
            self._coach_render(*self._coach_last)
            return
        self._coach_render(*self._coach_last)
        lang = ui_lang()
        try:
            facts = ask_facts(ctx["fen"], ctx["pe"], ctx["sans"], ctx["last"])
        except Exception:  # noqa: BLE001
            facts = pick("Позиція (FEN): ", "Position (FEN): ") + ctx["fen"]
        qkey = ("ask", id(item))
        self._ai_busy.add(qkey)
        tele_count("f.ask")

        def work():
            try:
                self._aiq.put((qkey, (item, fetch_ai_coach(facts, lang, question=q, history=history)), None))
            except Exception as e:  # noqa: BLE001
                self._aiq.put((qkey, (item, None), str(e)))
        threading.Thread(target=work, daemon=True).start()
        if not self._ai_polling:
            self._ai_polling = self.after(150, self._ai_poll)

    def _ai_poll(self):
        self._ai_polling = None
        while True:
            try:
                key, text, err = self._aiq.get_nowait()
            except queue.Empty:
                break
            self._ai_busy.discard(key)
            if key[0] == "ask":
                item, ans = text
                item["a"], item["err"] = ans, (None if ans else (err or "ai"))
                if ans:
                    ai_quota_use()
                self._coach_render(*self._coach_last)
                if self.ai_btn.winfo_manager():
                    self._ai_btn_show(True)          # оновити «ще N»
                continue
            if text:
                ai_quota_use()
                self._ai_cache[key] = text
                self._ai_err = None
            else:
                self._ai_failed[key] = time.time()
                self._ai_err = err
                if err == "quota":
                    self._ai_off = True          # до кінця сеансу - лише звичайний тренер
            if key == self._ai_cur:
                self._coach_render(self._coach_lines, ai_text=text, note=not text)
                if not text and not self._ai_off:
                    self._ai_btn_show(True)          # не вийшло - можна натиснути ще раз
        if self._ai_busy:
            self._ai_polling = self.after(150, self._ai_poll)

    def _coach_main(self, k):
        res = self.result
        if k == 0:
            return [pick("Почніть партію: перетягніть фігуру або клікніть її.",
                         "Start the game: drag a piece or click it.")]
        m = res["moves"][k - 1]
        lines = coach_lines(res["fens"][k - 1], m["uci"], m["quality"], m["best_san"],
                            res["pos_info"][k - 1], res["pos_info"][k])
        return lines + _book_note(m)

    def _coach_var(self, j):
        v = self.var
        row = v["rows"][j - 1]
        lines = coach_lines(v["fens"][j - 1], row["uci"], row["quality"], row["best_san"],
                            v["pes"][j - 1], v["pes"][j])
        return lines + _book_note(row)

    def _on_lang_change(self):
        new = next((c for c, n in LANGS if n == self.lang_var.get()), "en")
        if new == ui_lang():
            return
        STATE["lang"] = "uk" if new == "uk" else "en"
        STATE["xl"] = new if new in ("pt", "es") else None
        self._apply_lang()
        self._save_config()

    # ---------- донат

    def _build_donate(self, parent):
        """Яскрава жовта кнопка «☕ Підтримати кавою» (колір Buy Me a Coffee), із заокругленими кутами."""
        btn = RButton(parent, text="☕  Підтримати кавою", kind="donate", command=self.open_donate)
        btn.pack(side="right", padx=(0, 8))
        self.donate_btn = btn

    def open_donate(self):
        """Кнопка «☕»: квадрат з карткою автора (monobank) і кнопкою «Копіювати номер»."""
        if DONATE_URL:
            webbrowser.open(DONATE_URL)
            return
        for b in (self.settings, self.changelog, self.studies_box, self.update_box):
            b.hide()
        if not self.donate_box.is_open:
            self._render_donate()
        self.donate_box.toggle()

    # ---------- 1.27.12: анонімна статистика
    def _build_tele_box(self):
        self.tele_box = OverlayBox(self, "📊  Анонімна статистика")
        body = ttk.Frame(self.tele_box.box, style="Panel.TFrame", padding=(22, 14))
        body.pack(fill="both", expand=True, padx=2, pady=(0, 2))
        self.tele_text = ttk.Label(body, style="Panel.TLabel", wraplength=440, justify="left")
        self.tele_text.pack(anchor="w")
        btns = ttk.Frame(body, style="Panel.TFrame")
        btns.pack(pady=(14, 0), anchor="e")
        RButton(btns, text="Так, надсилати", style="Accent.TButton",
                command=lambda: self._tele_answer(True)).pack(side="left", padx=(0, 8))
        RButton(btns, text="Ні, дякую", style="Small.TButton",
                command=lambda: self._tele_answer(False)).pack(side="left")

    def _tele_start(self):
        if TELE["on"] is None:
            self.tele_text.configure(text=pick(
                "Можна допомогти зробити програму кращою: надсилати анонімну статистику — скільки партій "
                "проаналізовано, які оцінки ходів, з якими ботами грають, якими функціями користуються, версію "
                "програми, мову й країну.\n\nНе надсилаються: партії, ніки, тексти повідомлень, IP-адреса. "
                "Загальні цифри видно всім у ⚙ «Статистика». Вимкнути можна будь-коли в ⚙.",
                "You can help make the app better by sending anonymous statistics: how many games were analyzed, "
                "move grades, which bots people play, which features are used, the app version, language and "
                "country.\n\nNot sent: games, usernames, message texts, IP address. The totals are visible to "
                "everyone in ⚙ Statistics. You can turn it off any time in ⚙."))
            self.tele_box.show()
            return
        if TELE["on"]:
            tele_count("start")
            self._tele_tick()

    def _tele_answer(self, on):
        self.tele_box.hide()
        self.tele_var.set(on)            # → _tele_set
        if on:
            tele_count("start")
            self._tele_tick()

    def _tele_set(self, on):
        if TELE["on"] == on:
            return
        TELE["on"] = on
        if not on:
            with _tele_lock:
                TELE["pending"] = {}
        tele_save()

    def _tele_tick(self):
        """Надсилання накопиченого: зараз і далі раз на 10 хвилин (лише коли є що)."""
        if getattr(self, "_tele_timer", None):
            self.after_cancel(self._tele_timer)
        if TELE["on"] and TELE["pending"]:
            threading.Thread(target=tele_send, daemon=True).start()
        self._tele_timer = self.after(600000, self._tele_tick)

    def _build_donate_box(self):
        self.donate_box = OverlayBox(self, "☕  Підтримати кавою")
        body = ttk.Frame(self.donate_box.box, style="Panel.TFrame", padding=(22, 14))
        body.pack(fill="both", expand=True, padx=2, pady=(0, 2))
        self.donate_text = ttk.Label(body, style="Panel.TLabel", wraplength=380, justify="left")
        self.donate_text.pack(anchor="w")
        tk.Label(body, text=DONATE_CARD, bg=PANEL, fg=FG, font=("Segoe UI", 20, "bold")).pack(pady=(12, 0))
        self.donate_bank = ttk.Label(body, style="PanelMuted.TLabel")
        self.donate_bank.pack()
        btns = ttk.Frame(body, style="Panel.TFrame")
        btns.pack(pady=(14, 0))
        RButton(btns, text="📋 Копіювати номер", style="Accent.TButton",
                command=self._copy_card).pack(side="left", padx=(0, 8))
        RButton(btns, text="Закрити", style="Small.TButton", command=self.donate_box.hide).pack(side="left")

    def _render_donate(self):
        self.donate_text.configure(text=pick(
            "Програма безкоштовна. Якщо вона вам подобається, можна пригостити автора кавою - "
            "переказ на картку:",
            "The app is free. If you like it, you can treat the author to a coffee - "
            "a transfer to the card:"))
        self.donate_bank.configure(text=pick("monobank, Україна", "monobank, Ukraine"))

    def _copy_card(self):
        self.clipboard_clear()
        self.clipboard_append(DONATE_CARD.replace(" ", ""))
        self.donate_bank.configure(text=pick("Номер скопійовано ✓", "Number copied ✓"))

    def _apply_lang(self):
        """Перемальовує статичні написи, таблиці та поточні тексти мовою STATE['lang']."""
        self.title(tr("Аналізатор шахових партій"))
        if self._ask_hint_on:
            self._ask_hint_on = False
            self.ask_entry.delete(0, "end")
            self._ask_hint(True)
        mp = {}                       # 1.30.0: будь-який відомий варіант напису (uk/en/pt/es) -> поточна мова
        for uk, en in TR_EN.items():
            target = xl(en) if STATE["lang"] == "en" else uk
            for k in (uk, en) + tuple(I18N.get(en, ())):
                mp[k] = target
        stack = [self]
        while stack:
            w = stack.pop()
            stack.extend(w.winfo_children())
            if isinstance(w, ttk.Treeview):
                for c in w["columns"]:
                    t = w.heading(c, "text")
                    w.heading(c, text=mp.get(t, t))
                for iid in w.get_children(""):
                    vals = [mp.get(str(x), x) for x in w.item(iid, "values")]
                    w.item(iid, values=vals)
                continue
            try:
                t = w.cget("text")
            except Exception:  # noqa: BLE001
                continue
            if isinstance(t, str) and t in mp:
                w.configure(text=mp[t])
        st = self.status_var.get()
        self.status_var.set(mp.get(st, st))
        self._update_arrow_combo()
        self._render_changelog()
        self._render_lines()
        self._render_study_panel()
        if self.studies_box.is_open:
            self._refresh_studies_list()
        if self._names:
            self._set_names(*self._names)
        self._refresh_view()
        self._show_note()
        self._render_update()
        self._render_donate()
        self._render_stats()
        if hasattr(self, "cc_tree"):
            self._cc_render_lang()
        if hasattr(self, "bots_box"):
            self._bots_render()
            for lbl in self._credit_links:
                lbl.configure(text="ⓘ " + pick("Ліцензія фото", "Photo license"))
            if self._bot_live():
                self._bot_card_render()
            if self.bot:                               # 1.26.1.5: факти «Інших шахістів» і рядок стану - новою мовою
                self._bot_side_render()
                if getattr(self, "_bot_status", None) and st in self._bot_status_texts(*self._bot_status):
                    self._bot_status_set()

    def _set_info(self, first, advice="", theory=""):
        """Підказка до ходу (у стовпці «Оцінка партії»): лише непорожні рядки."""
        self.info_var.set("\n".join(x for x in (first, advice, theory) if x))

    def _theory_line(self, fen, on_path=True):
        """
        Теоретичні ходи з бази дебютів для цієї позиції (якщо вона є в базі).
        on_path=False - партія вже вийшла з теорії: продовжень не показуємо.
        """
        if not on_path or self._bot_live():      # у партії з ботом дебютних підказок немає
            return ""
        book = self._book
        nxt = getattr(book, "next_moves", None) if book else None
        if not nxt:
            return ""
        board = chess.Board(fen)
        key = board.epd()
        ucis = nxt.get(key)
        if not ucis:
            return ""
        sans = []
        for u in sorted(ucis):
            try:
                sans.append(board.san(chess.Move.from_uci(u)))
            except Exception:
                pass
        if not sans:
            return ""
        name = book.get(key)
        tail = f"  ·  {name[0]} {name[1]}" if name else ""
        return "📖 " + pick("Теорія", "Theory") + ": " + ", ".join(sans[:8]) + tail

    def _recommend(self, fen, pe):
        """Текст «найкращий хід за Stockfish (оцінка)» для позиції."""
        if not pe or not pe.get("best"):
            return ""
        try:
            board = chess.Board(fen)
            san = board.san(chess.Move.from_uci(pe["best"]))
        except Exception:
            return ""
        return f"{san} ({fmt_eval(pe['cp'])})"

    def _on_ply_click(self, k):
        """Клік по ходу в списку ходів партії."""
        if not self.result:
            return
        self._stop_play()
        if self.var is not None or k != self.index:
            self.jump(k)

    def _on_line_click(self, lid):
        """Клік по рядку «↳» - збереженому варіанту гравця."""
        line = self._line_by_id(lid)
        if line is not None and line is not self.var:
            self._open_line(line, 1)

    # ---------- власні варіанти на дошці
    def _current_cp(self):
        if self.var is not None:
            pe = self.var["pes"][self.var["index"]]
            return pe["cp"] if pe else 0
        if self.result:
            return self.result["evals"][self.index]
        return 0

    def _on_user_move(self, uci, dragged):
        """Гравець зробив хід на дошці (перетягуванням або кліком)."""
        if not self.result or self._var_busy:
            self.board.set_position(self.board.fen, self.board.last, self.board.badge, self.board.arrow,
                                    self.board.shapes)
            return
        # партія з ботом: фігурами бота ходить лише бот
        cur = self.var["fens"][self.var["index"]] if self.var is not None else self.result["fens"][self.index]
        if self._bot_live() and not self._bot_inject and (" w " in cur) == (self.bot["color"] == chess.WHITE):
            self.board.set_position(self.board.fen, self.board.last, self.board.badge, self.board.arrow,
                                    self.board.shapes)
            return
        self._stop_play()
        res = self.result

        if self.var is not None:
            v = self.var
            j = v["index"]
            base = v["base"]
            if j < len(v["rows"]) and v["rows"][j]["uci"] == uci:      # наступний хід цього ж варіанту
                self.goto_var(j + 1, animate=not dragged)
                return
            if j == 0 and base < len(res["moves"]) and res["moves"][base]["uci"] == uci:
                self._clear_var()                                    # хід партії - назад в основну лінію
                self.goto(base + 1, animate=not dragged)
                return
            same = self._find_line(base, [r["uci"] for r in v["rows"][:j]] + [uci])
            if same is not None:                                     # такий варіант уже збережено
                self._open_line(same, j + 1, animate=not dragged)
                return

        if self.var is None:
            k = self.index
            # хід збігається з ходом партії - просто йдемо далі основною лінією
            if k < len(res["moves"]) and res["moves"][k]["uci"] == uci:
                self.goto(k + 1, animate=not dragged)
                return
            # 1.26.7: аналіз ще йде, а це наступний хід партії, якого ще не оцінено - не робимо з нього варіант
            if res.get("partial") and k == len(res["moves"]) and self.game is not None:
                gm = list(self.game.mainline_moves())
                if k < len(gm) and gm[k].uci() == uci:
                    self.goto(k, animate=False)
                    self.status_var.set(pick("Цей хід партії ще аналізується — зачекай трохи.",
                                             "This game move is still being analysed — wait a moment."))
                    return
            same = self._find_line(k, [uci])
            if same is not None:                                     # такий варіант уже збережено
                self._open_line(same, 1, animate=not dragged)
                return
            prev = res["moves"][k - 1] if k >= 1 else None
            base_opening = ""
            if res["book_path"][k]:
                for m in reversed(res["moves"][:k]):
                    if m.get("opening"):
                        base_opening = m["opening"]
                        break
            self.var = {
                "base": k, "rows": [], "index": 0,
                "fens": [res["fens"][k]], "pes": [res["pos_info"][k]],
                "prev_drop": prev["drop"] if prev else 0.0,
                "prev_cap": prev["cap_sq"] if prev else None,
                "book_path": [bool(res["book_path"][k])],
                "base_opening": base_opening,
                "opening": base_opening,
                "id": None,                 # номер з'явиться, коли варіант збережеться (перший хід)
            }
            self._show_var_bar()
            self.vtree.delete(*self.vtree.get_children())

        v = self.var
        j = v["index"]
        if j < len(v["rows"]):
            # новий хід посеред варіанту: старий варіант лишається, а новий - його копія до цього
            # місця плюс новий хід (як гілка на lichess). Списки нижче - нові, старі не змінюються.
            v = dict(v, id=None)
            self.var = v
            v["rows"] = v["rows"][:j]
            v["fens"] = v["fens"][:j + 1]
            v["pes"] = v["pes"][:j + 1]
            v["book_path"] = v["book_path"][:j + 1]
            v["opening"] = (v["rows"][j - 1].get("opening") or v["base_opening"]) if j >= 1 else v["base_opening"]
            for iid in list(self.vtree.get_children())[j:]:
                self.vtree.delete(iid)

        board = chess.Board(v["fens"][j])
        move = chess.Move.from_uci(uci)
        if move not in board.legal_moves:
            self._show_var_state(j, animate=False)
            return

        path = self.engine_var.get().strip().strip('"')
        if not path or not os.path.exists(path):
            messagebox.showwarning(trd("Увага", "Warning"), tr("Вкажіть шлях до файлу Stockfish (.exe)."))
            self._show_var_state(j, animate=False)
            return

        # хід з'являється одразу (позначка «…»), а Stockfish оцінює його у фоні - можна ходити далі
        after = board.copy()
        after.push(move)
        row = {"label": f"{board.fullmove_number}." if board.turn == chess.WHITE else f"{board.fullmove_number}…",
               "san": board.san(move), "uci": uci, "fen": after.fen(), "pending": True, "quality": None}
        if self._bot_inject and getattr(self, "_bot_fake_bril", False):
            row["fake_bril"] = True       # 1.26.10: Nxf7 Witty Alien - «!!» лише поки йде гра (справжня оцінка - своя)
        if (not self._bot_inject and uci == "c7c6" and board.fullmove_number == 1 and self.bot and self._bot_live()
                and self.bot["spec"]["id"] == "wittyalien" and self.bot["color"] == chess.WHITE):
            row["fake_blunder"] = True    # 1.27.7: Каро-Канн проти Witty Alien - «??» лише поки йде гра
        v["rows"].append(row)
        v["fens"].append(row["fen"])
        v["pes"].append(None)
        v["index"] = len(v["rows"])
        if not any(ln is v for ln in self.lines):            # перший хід нового варіанту - зберігаємо
            v["id"] = self._next_line_id()
            self.lines.append(v)
        self._fill_vtree(v)
        self._render_lines()
        self._show_var_state(v["index"], animate=not dragged)
        self._queue_eval(v, row, path, self._depth())
        if getattr(self, "_puzzle", None):
            self._puzzle_instant(v, row)

    # ---------- черга оцінок ходів гравця (по одному, по порядку - кожна спирається на попередню)
    def _queue_eval(self, v, row, path, depth):
        if not hasattr(self, "_eval_q"):
            self._eval_q = queue.Queue()
            threading.Thread(target=self._eval_worker, daemon=True).start()
        if not self._pending_evals:
            self._status_before_eval = self.status_var.get()
        self._ai_early_ok = (bool(self.ai_var.get()) and not self._ai_off and bool(self.coach_var.get())
                             and not self._bot_live())
        self._pending_evals += 1
        self._eval_status()
        self._deep_tok += 1                 # новий хід - глибше думати над старим не треба
        self._eval_q.put((v, row, path, depth))
        self._poll_start()

    def _poll_start(self):
        if not self._poll_on:
            self._poll_on = True
            self.after(80, self._poll_var)

    def _eval_status(self):
        if self._pending_evals > 0 and self._bot_live():
            return                          # у партії з ботом аналіз не видно
        if self._pending_evals > 0:
            self.status_var.set(f"⏳ {pick('Stockfish оцінює ходи', 'Stockfish is evaluating moves')}… "
                                f"({self._pending_evals})")
        elif self._status_before_eval is not None:
            self.status_var.set(self._status_before_eval)
            self._status_before_eval = None

    def _eval_worker(self):
        while True:
            v, row, path, depth = self._eval_q.get()
            err = None
            try:
                self._eval_row(v, row, path, depth)
            except Exception as e:  # noqa: BLE001
                err = str(e)
                row.update(pending=False, failed=True, quality="Добрий", best_uci=None, best_san="",
                           drop=0.0, cap_sq=None, acc=100.0, loss=0, book=False, book_bad=False, opening="")
            self.vq.put(("done", row, err))

    def _eval_row(self, v, row, path, depth):
        """Робочий потік: оцінює один хід варіанту й записує результат прямо в row (і pes усіх гілок)."""
        rows = v["rows"]
        j = next((i + 1 for i, r in enumerate(rows) if r is row), 0)
        if not j or not row.get("pending") or not self.result:
            return                                  # хід уже скасували
        prev = rows[j - 2] if j >= 2 else None
        board = chess.Board(v["fens"][j - 1])
        move = chess.Move.from_uci(row["uci"])
        s = self.result["summary"]
        rating = s["white_rating"] if board.turn == chess.WHITE else s["black_rating"]
        prev_drop = prev["drop"] if prev else v["prev_drop"]
        prev_cap = prev["cap_sq"] if prev else v["prev_cap"]
        book = self._book or None
        opening_str = (prev.get("opening") or v["base_opening"]) if prev else v["base_opening"]
        book_hit = False
        on_path = v["book_path"][j - 1] if j - 1 < len(v["book_path"]) else False
        after = chess.Board(row["fen"])
        if book and on_path and after.epd() in book:
            book_hit = True
            name = book[after.epd()]
            if name:
                opening_str = f"{name[0]} · {name[1]}"
        limit = chess.engine.Limit(depth=depth)
        with self.live.lock:
            t0 = time.time()
            eng = self.live.get(path)
            pb = v["pes"][j - 1]
            if pb is None and j == 1:                   # 1.28.2: могли порахувати у фоні (тренування)
                pb = (self.result.get("pos_info") or [None] * (v["base"] + 1))[v["base"]]
            if pb is None or pb.get("req_depth") != depth:
                pb = pos_eval(_analyse(eng, board, limit), depth)
            # 1.23.7: спершу швидка оцінка (на 4 глибини менше) - за нею ШІ-тренер починає думати одразу,
            # поки Stockfish рахує хід повністю (кеш рушія від швидкої оцінки ще й пришвидшує повну)
            qd = depth - 4
            if False and qd >= 8 and self._ai_early_ok:      # 1.28.2: ШІ - лише за кнопкою, рання оцінка не потрібна
                try:
                    rq, peq = evaluate_move(eng, chess.engine.Limit(depth=qd), board, move, pb, prev_drop, prev_cap,
                                            rating, book_hit)
                    self.vq.put(("early", (v["fens"][j - 1], row["uci"], rq["quality"], rq.get("best_san") or "",
                                           pb, peq), None))
                except Exception:  # noqa: BLE001
                    pass
            prev_q = prev["quality"] if prev else (self.result["moves"][v["base"] - 1].get("quality")
                                                   if v["base"] >= 1 and v["base"] - 1 < len(self.result["moves"]) else None)
            r, pe_after = evaluate_move(eng, limit, board, move, pb, prev_drop, prev_cap, rating, book_hit,
                                        prev_bril=prev_q == "Геніальний")
        r["elapsed"] = time.time() - t0
        r["opening"] = opening_str if book_hit else ""
        row.update(r)
        row.pop("pending", None)
        # той самий хід може бути в кількох гілках (вони ділять початок) - оновлюємо всі
        for L in [ln for ln in self.lines] + ([self.var] if self.var else []):
            i = next((k + 1 for k, rr in enumerate(L["rows"]) if rr is row), 0)
            if not i:
                continue
            L["pes"][i - 1] = pb
            L["pes"][i] = pe_after
            while len(L["book_path"]) <= i:
                L["book_path"].append(False)
            L["book_path"][i] = book_hit and row["quality"] == "Теорія"
            if i == len(L["rows"]):
                L["opening"] = r["opening"] or opening_str

    def _poll_var(self):
        try:
            while True:
                msg = self.vq.get_nowait()
                if msg[0] == "early":
                    self._ai_prefetch(msg[1])
                    continue
                if msg[0] == "deep":
                    self._deep_show(msg[1], msg[2])
                    continue
                if msg[0] == "deepend":
                    self._deep_end(msg[1])
                    continue
                if msg[0] != "done":
                    continue
                _, row, err = msg
                self._pending_evals = max(0, self._pending_evals - 1)
                if getattr(self, "_puzzle", None) and not err:
                    self._puzzle_check(row)
                self._eval_status()
                self._render_lines()
                self._doc_changed()
                v = self.var
                if v is not None and any(r is row for r in v["rows"]):
                    at = next(i + 1 for i, r in enumerate(v["rows"]) if r is row)
                    self._fill_vtree(v)
                    if v["index"] in (at, at - 1):
                        self._show_var_state(v["index"], animate=False)
                if err:
                    messagebox.showerror(trd("Помилка Stockfish", "Stockfish error"), err)
                elif not self._pending_evals:
                    self._deep_start()
        except queue.Empty:
            pass
        if self._pending_evals > 0 or self._deep_running:
            self.after(80, self._poll_var)
        else:
            self._poll_on = False

    # ---------- 1.30.1: поки гравець дивиться на свій хід, Stockfish думає глибше (+2, +4 … до +DEEP_EXTRA)
    def _deep_start(self):
        self._deep_tok += 1
        v = self.var
        if (v is None or self._pending_evals or not self.result or self._bot_live()
                or getattr(self, "_puzzle", None) or not 1 <= v["index"] <= len(v["rows"])):
            return
        row = v["rows"][v["index"] - 1]
        depth = self._depth()
        top = min(DEEP_MAX, depth + DEEP_EXTRA)
        if (row.get("pending") or row.get("failed") or row.get("quality") == "Теорія"
                or (row.get("deep_depth") or depth) >= top):
            return
        path = self.engine_var.get().strip().strip('"')
        if not path or not os.path.exists(path):
            return
        tok = self._deep_tok
        if not self._deep_running:
            self._deep_prev_status = self.status_var.get()
        self._deep_running = tok             # токен потоку, що думає зараз (False - ніхто)
        threading.Thread(target=self._deep_worker, args=(tok, v, row, path, depth, top), daemon=True).start()
        self._poll_start()

    def _deep_worker(self, tok, v, row, path, depth, top):
        d = row.get("deep_depth") or depth
        try:
            while d < top and tok == self._deep_tok:
                d = min(top, d + 2)
                if not self._deep_step(tok, v, row, path, d):
                    break
                self.vq.put(("deep", row, d))
        except Exception:  # noqa: BLE001 - глибша оцінка лише бонус, звичайна вже є
            pass
        self.vq.put(("deepend", tok))

    def _deep_step(self, tok, v, row, path, d):
        rows = v["rows"]
        j = next((i + 1 for i, r in enumerate(rows) if r is row), 0)
        if not j or self.var is not v or v["index"] != j or not self.result:
            return False
        prev = rows[j - 2] if j >= 2 else None
        board = chess.Board(v["fens"][j - 1])
        move = chess.Move.from_uci(row["uci"])
        s = self.result["summary"]
        rating = s["white_rating"] if board.turn == chess.WHITE else s["black_rating"]
        prev_drop = prev["drop"] if prev else v["prev_drop"]
        prev_cap = prev["cap_sq"] if prev else v["prev_cap"]
        prev_q = prev["quality"] if prev else (self.result["moves"][v["base"] - 1].get("quality")
                                               if v["base"] >= 1 and v["base"] - 1 < len(self.result["moves"]) else None)
        limit = chess.engine.Limit(depth=d)
        with self.deeplive.lock:
            if tok != self._deep_tok:
                return False
            eng = self.deeplive.get(path)
            pb = pos_eval(_analyse(eng, board, limit), d)
            if tok != self._deep_tok:
                return False
            r, pe_after = evaluate_move(eng, limit, board, move, pb, prev_drop, prev_cap, rating, False,
                                        prev_bril=prev_q == "Геніальний")
        if tok != self._deep_tok:
            return False
        r["elapsed"] = row.get("elapsed")
        r["opening"] = row.get("opening", "")
        row.update(r)
        row["deep_depth"] = d
        for L in [ln for ln in self.lines] + ([self.var] if self.var else []):
            i = next((k + 1 for k, rr in enumerate(L["rows"]) if rr is row), 0)
            if i:
                L["pes"][i - 1] = pb
                L["pes"][i] = pe_after
        return True

    def _deep_show(self, row, d):
        v = self.var
        if v is None or not any(r is row for r in v["rows"]):
            return
        self._fill_vtree(v)
        self._render_lines()
        if 1 <= v["index"] <= len(v["rows"]) and v["rows"][v["index"] - 1] is row:
            self._show_var_state(v["index"], animate=False)
        if not self._pending_evals:
            self._deep_text = (f"🔍 {pick('Stockfish думає глибше', 'Stockfish is thinking deeper')}: "
                               f"{pick('глибина', 'depth')} {d}")
            self.status_var.set(self._deep_text)

    def _deep_end(self, tok):
        if tok != self._deep_running:
            return                          # закінчився старий потік, а вже думає новий
        self._deep_running = False
        if getattr(self, "_deep_text", None) and self.status_var.get() == self._deep_text:
            self.status_var.set(self._deep_prev_status)
        self._deep_text = None
        self._doc_changed()

    def goto_var(self, j, animate=None):
        v = self.var
        if v is None or self._var_busy:
            return
        j = max(0, min(len(v["rows"]), j))
        prev = v["index"]
        v["index"] = j
        if animate is None:
            animate = (j == prev + 1)
        self._show_var_state(j, animate)
        self._deep_start()                  # 1.30.1: думати глибше над ходом, на який дивимось

    def _show_var_state(self, j, animate=False):
        v = self.var
        if v is None:
            return
        fen = v["fens"][j]
        last = badge = arrow = None
        rec = self._recommend(fen, v["pes"][j])
        if j == 0:
            info = tr("Початок варіанту — позиція з партії.")
        else:
            row = v["rows"][j - 1]
            last = row["uci"]
            fake = ("Геніальний" if row.get("fake_bril") else "Груба помилка" if row.get("fake_blunder") else None)
            if fake and self._bot_live():     # 1.26.10 / 1.27.7: під час гри - «Геніальний» / «Груба помилка»
                badge = (QUALITY[fake][0], QUALITY[fake][1])
                info = f"{row['label']} {row['san']} — {qname(fake)}."
            elif row.get("pending"):
                info = f"⏳ {row['label']} {row['san']} — " + pick("Stockfish оцінює цей хід…",
                                                                   "Stockfish is evaluating this move…")
            else:
                color, symbol, note = QUALITY[row["quality"]]
                badge = None if self._bot_live() else (color, symbol)      # у партії з ботом - без оцінок
                info = f"{row['label']} {row['san']} — {qname(row['quality'])}.  {tr(note)}"
                if row.get("book") and row.get("opening"):
                    info += f"  {row['opening']}"
                info += best_was(row)
        adv = ""
        if rec and not self._bot_live() and not self._pz_hide():
            d = v["pes"][j].get("depth")
            el = v["rows"][j - 1].get("elapsed") if j >= 1 else None
            parts = ([f"{tr('глибина')} {d}"] if d else []) + ([f"{el:.1f} {tr('с')}"] if el else [])
            adv = f"{to_move(v['fens'][j])} — {tr('Stockfish радить:')} {rec}" + (f"  ({', '.join(parts)})" if parts else "")
        arrow = self._best_arrow(v["rows"][j - 1] if j >= 1 else None, v["pes"][j])
        shapes = self.shapes.get(self._line_key(v, j), [])

        if animate and j >= 1 and self.anim_var.get():
            if j >= 2:
                prev_last = v["rows"][j - 2]["uci"]
            elif v["base"] >= 1:
                prev_last = self.result["moves"][v["base"] - 1]["uci"]
            else:
                prev_last = None
            self.board.animate_move(
                v["fens"][j - 1], prev_last, last,
                lambda f=fen, l=last, b=badge, a=arrow, s=shapes: self.board.set_position(f, l, b, a, s), badge)
        else:
            self.board.set_position(fen, last, badge, arrow, shapes)

        self.board.interactive = True
        known = j                                       # поки хід оцінюється - остання відома оцінка
        while known > 0 and not v["pes"][known]:
            known -= 1
        pe_j = v["pes"][known]
        self.evalbar.set(pe_j["cp"] if pe_j else 0, self.board.flipped)
        self.graph.set_index(v["base"])
        on_path = bool(v["book_path"][j]) if j < len(v["book_path"]) else False
        self._set_info(info, adv, self._theory_line(fen, on_path))
        self._ask_set_var(j)
        if j == 0:
            self._coach_show([tr("Початок варіанту — позиція з партії.")])
        elif v["rows"][j - 1].get("pending"):
            lines = [pick("Тренер пояснить хід, щойно Stockfish його оцінить.",
                          "The coach will explain the move once Stockfish has evaluated it.")]
            self._coach_show(lines)
            if self.ai_var.get() and not self._ai_off and not self._bot_live():
                self._coach_render(lines, waiting=True)     # 1.23.7: ШІ вже думає (за швидкою оцінкою)
        else:
            self._coach_show(self._coach_var(j), ai=self._ai_var_args(j))
        if j >= 1:
            self.vtree.selection_set(str(j))
            self.vtree.see(str(j))
        else:
            self.vtree.selection_remove(self.vtree.selection())
        # у списку ходів партії підсвічуємо рядок «↳» цього варіанту
        if j >= 1 and any(ln is v for ln in self.lines):
            self.moves_view.select(ply=None, node=self._line_key(v, j))
        else:
            self.moves_view.select(ply=v["base"])
        self._show_note()
        if self.bot or self._bot_ui_on:
            self.after(30, self._bot_tick)

    def _on_vtree_select(self, _event):
        sel = self.vtree.selection()
        if not sel or self.var is None or self._var_busy:
            return
        alt = getattr(self, "_vtree_alts", {}).get(sel[0])
        if alt is not None:                           # підрозділ - відкрити гілку на її ході
            self._open_line(alt[0], alt[1])
            return
        if int(sel[0]) != self.var["index"]:
            self.goto_var(int(sel[0]))

    def undo_var(self, _bot=False):
        """«Скасувати хід»: прибирає останній хід варіанту (порожній варіант зникає)."""
        if not _bot and self._bot_live():
            return self._bot_undo()
        v = self.var
        if v is None or self._var_busy or not v["rows"]:
            return
        v["rows"].pop()
        v["fens"].pop()
        v["pes"].pop()
        del v["book_path"][len(v["rows"]) + 1:]
        rows = v["rows"]
        v["opening"] = (rows[-1].get("opening") or v["base_opening"]) if rows else v["base_opening"]
        self.vtree.delete(str(len(rows) + 1))
        if not rows:
            self._drop_line(v)
            self.exit_var()
            self._render_lines()
            self._doc_changed()
            return
        # варіант став початком іншого збереженого варіанту - залишаємо лише довший
        twin = self._find_line(v["base"], [r["uci"] for r in rows], exclude=v)
        if twin is not None:
            self._drop_line(v)
            self._render_lines()
            self._doc_changed()
            self._open_line(twin, len(rows))
            return
        self._prune_annotations()
        self._render_lines()
        self._doc_changed()
        v["index"] = len(rows)
        self._show_var_state(v["index"], animate=False)

    def delete_var(self):
        """«Видалити варіант»: прибирає весь варіант гравця і повертає до партії."""
        v = self.var
        if v is None or self._var_busy:
            return
        self._drop_line(v)
        self.exit_var()
        self._render_lines()
        self._doc_changed()

    # ---------- збережені варіанти гравця
    def _line_by_id(self, lid):
        for ln in self.lines:
            if str(ln.get("id")) == str(lid):
                return ln
        return None

    def _next_line_id(self):
        return max([ln.get("id") or 0 for ln in self.lines] + [0]) + 1

    def _find_line(self, base, ucis, exclude=None):
        """Збережений варіант від позиції base, що починається ходами ucis."""
        n = len(ucis)
        for ln in self.lines:
            if ln is exclude or ln["base"] != base or len(ln["rows"]) < n:
                continue
            if [r["uci"] for r in ln["rows"][:n]] == ucis:
                return ln
        return None

    def _drop_line(self, line):
        """Прибирає варіант зі списку (той самий список, що й у розділі дослідження)."""
        for i, ln in enumerate(self.lines):
            if ln is line:
                del self.lines[i]
                break
        self._prune_annotations()

    def _prune_annotations(self):
        """Коментарі й стрілки позицій, яких більше немає (після видалення ходів)."""
        if not self.result:
            return
        keys = {str(k) for k in range(len(self.result["fens"]))}
        for ln in self.lines:
            for j in range(1, len(ln["rows"]) + 1):
                keys.add(self._line_key(ln, j))
        for d in (self.notes, self.shapes):
            for key in [k for k in d if k not in keys]:
                del d[key]

    @staticmethod
    def _line_key(line, j):
        """Шлях позиції після j-го ходу варіанту: "k/e2e4/e7e5"."""
        return "/".join([str(line["base"])] + [r["uci"] for r in line["rows"][:j]])

    def _node_key(self):
        """Шлях позиції, яка зараз на дошці."""
        if self.var is not None:
            return self._line_key(self.var, self.var["index"])
        return str(self.index)

    @staticmethod
    def _line_text(line, budget=30):
        """«13…Qc5+ 14.Kh1 Qxe5 …» - як варіант записують у PGN (коротко, щоб влазило в колонку)."""
        parts = []
        for i, r in enumerate(line["rows"]):
            part = r["label"] + r["san"] if i == 0 or r["label"].endswith(".") else r["san"]
            if parts and len(" ".join(parts + [part])) > budget:
                parts.append("…")
                break
            parts.append(part)
        return " ".join(parts)

    # ---------- права кнопка на ході: коментар, «зробити основним» (з 1.18.11)
    def _move_menu(self, key, line, j, is_main, x, y):
        if self.result and self.result.get("partial"):
            return                                   # аналіз ще йде
        m = tk.Menu(self, tearoff=0, bg=PANEL2, fg=FG, activebackground="#3d5229", activeforeground="#ffffff",
                    bd=0, relief="flat", font=("Segoe UI", 10))
        has = bool(self.notes.get(key))
        m.add_command(label=pick("💬 Змінити коментар…", "💬 Edit comment…") if has else
                      pick("💬 Коментар…", "💬 Comment…"),
                      command=lambda: self._edit_comment(key, line, j))
        if has:
            m.add_command(label=pick("🗑 Видалити коментар", "🗑 Delete comment"),
                          command=lambda: self._set_comment(key, ""))
        m.add_separator()
        if line is not None and not is_main:
            m.add_command(label=pick("⬆ Зробити основним", "⬆ Make main line"),
                          command=lambda: self.promote_line(line, j))
        if line is not None or j >= 1:
            m.add_command(label=pick("✂ Видалити з цього місця", "✂ Delete from here"),
                          command=lambda: self.delete_from(line, j, None if line is not None else j))
        try:
            m.tk_popup(x, y)
        finally:
            m.grab_release()

    def _move_title(self, key, line, j):
        if line is not None:
            r = line["rows"][j - 1]
            return f"{r['label']} {r['san']}"
        k = int(key)
        if self.result and 1 <= k <= len(self.result["moves"]):
            mv = self.result["moves"][k - 1]
            return f"{mv['label']} {mv['san']}"
        return tr("Початкова позиція")

