        self.gl_comment.pack(anchor="w", pady=(8, 0))
        bot = ttk.Frame(body, style="Panel.TFrame")
        bot.pack(fill="x", pady=(10, 0))
        self.gl_status = ttk.Label(bot, style="PanelMuted.TLabel")
