    def _gl_like_text(self):
        sel = self.gl_tree.selection()
        liked = bool(sel) and int(sel[0]) in self._likes["liked"]
        self.gl_like_btn.configure(text=pick("💔  Прибрати ❤", "💔  Unlike") if liked else pick("❤  Подобається", "❤  Like"),
                                   state="normal" if sel else "disabled")

    def _gl_sort(self, key):
        self._gl_sortkey = key
        self._gl_render_lang()
        self._gl_load()

    def _gl_net(self, fn, done):
        """Мережа у потоці, відповідь - у done(результат або None) в головному потоці."""
        self._gl_seq += 1
        seq = self._gl_seq

        def work():
            try:
                self.glq.put((seq, done, fn(), None))
            except urllib.error.HTTPError as e:
                self.glq.put((seq, done, None, "rate" if e.code == 429 else "err"))
            except Exception:  # noqa: BLE001
                self.glq.put((seq, done, None, "net"))
        threading.Thread(target=work, daemon=True).start()
        self.after(150, self._gl_poll)

    def _gl_poll(self):
        try:
            seq, done, data, err = self.glq.get_nowait()
        except queue.Empty:
            self.after(150, self._gl_poll)
            return
        if data is None:
            self.gl_status.configure(text={"rate": pick("Забагато запитів - спробуйте за хвилину.", "Too many requests - try in a minute."),
                                           "net": pick("Немає з'єднання з інтернетом.", "No internet connection.")}
                                     .get(err, pick("Сервер зараз недоступний.", "The server is unavailable right now.")))
            return
        done(data)

    def _gl_load(self):
        self.gl_status.configure(text=pick("Завантажую…", "Loading…"))
        key = self._gl_sortkey
        self._gl_net(lambda: gotw_http(f"/list?sort={key}"), self._gl_fill)

    def _gl_fill(self, data):
        self._gl_rows = data.get("games") or []
        tv = self.gl_tree
        keep = tv.selection()
        tv.delete(*tv.get_children())
        for g in self._gl_rows:
            acc = (f"{g['white_acc']:.0f}% / {g['black_acc']:.0f}%" if g.get("white_acc") is not None
                   and g.get("black_acc") is not None else "–")
            heart = ("❤ " if g["n"] in self._likes["liked"] else "♡ ") + str(g.get("likes", 0))
            tv.insert("", "end", iid=str(g["n"]), values=(heart, g.get("white") or "?", g.get("black") or "?",
                      g.get("result") or "", acc, g.get("nick") or "—", (g.get("at") or "")[:10]))
        if keep and tv.exists(keep[0]):
            tv.selection_set(keep[0])
        self.gl_status.configure(text=pick(f"Партій: {len(self._gl_rows)}", f"Games: {len(self._gl_rows)}")
                                 if self._gl_rows else pick("Ще ніхто не подав заявку - будьте першим!",
                                                            "No applications yet - be the first!"))
        self._gl_show_comment()

    def _gl_show_comment(self):
        sel = self.gl_tree.selection()
        g = next((x for x in self._gl_rows if sel and str(x["n"]) == sel[0]), None)
        self.gl_comment.configure(text=("💬 " + g["comment"]) if g and g.get("comment") else "")
        self._gl_like_text()

    def _gl_like(self):
        sel = self.gl_tree.selection()
        if not sel:
            return
        n = int(sel[0])
        on = n not in self._likes["liked"]
        lid = self._likes["id"]

        def done(data):
            if on and n not in self._likes["liked"]:
                self._likes["liked"].append(n)
            elif not on and n in self._likes["liked"]:
                self._likes["liked"].remove(n)
            likes_save(self._likes)
            for g in self._gl_rows:
                if g["n"] == n:
                    g["likes"] = data.get("likes", g.get("likes", 0))
            self._gl_fill({"games": self._gl_rows})
        tele_count("gotw.like")
        self._gl_net(lambda: gotw_http("/like", {"n": n, "id": lid, "on": on}), done)

    def _gl_open(self):
        sel = self.gl_tree.selection()
        if not sel:
            return
        n = sel[0]
        self.gl_status.configure(text=pick("Завантажую партію…", "Loading the game…"))

        def done(data):
            if not data.get("pgn"):
                return
            self.gl_box.hide()
            self._load_pgn(data["pgn"])
        self._gl_net(lambda: gotw_http(f"/pgn?n={n}"), done)

    def _send_gotw(self):
        res, game = self.result, self.game
        if not res or game is None:
            return
        s = res["summary"]
        payload = {"pgn": str(game), "nick": self.gotw_nick.get().strip(), "comment": self.gotw_text.get("1.0", "end").strip(),
                   "white": s.get("white"), "black": s.get("black"), "result": s.get("result"),
                   "white_acc": s.get("white_acc"), "black_acc": s.get("black_acc"),
                   "p": "pc", "v": APP_VERSION, "lang": STATE["lang"], "public": True}
        self.gotw_send_btn.configure(state="disabled")
        self.gotw_status.configure(text=pick("Надсилаю…", "Sending…"))
        out = queue.Queue()

        def work():
            req = urllib.request.Request(GOTW_URL, data=json.dumps(payload).encode("utf-8"), method="POST",
                                         headers={"Content-Type": "application/json", "User-Agent": "ChessAnalyzer"})
            try:
                with urllib.request.urlopen(req, timeout=20) as r:
                    out.put(bool(json.loads(r.read().decode("utf-8")).get("ok")) or "error")
            except urllib.error.HTTPError as e:
                out.put("rate" if e.code == 429 else "error")
            except Exception:  # noqa: BLE001
                out.put("net")
        threading.Thread(target=work, daemon=True).start()
        tele_count("f.gotw")

        def poll():
            try:
                r = out.get_nowait()
            except queue.Empty:
                self.after(200, poll)
                return
            if r is True:
                self.gotw_text.delete("1.0", "end")
                self.gotw_status.configure(text=pick("✓ Дякуємо! Заявку подано - партія вже у «🏆 Партіях тижня».",
                                                    "✓ Thank you! Applied - the game is in «🏆 Games of the week»."))
                self.after(1800, self.gotw_box.hide)
                return
            self.gotw_send_btn.configure(state="normal")
            self.gotw_status.configure(text={
                "net": pick("Немає з'єднання з інтернетом. Спробуйте пізніше.", "No internet connection. Try later."),
                "rate": pick("Забагато спроб. Спробуйте за хвилину.", "Too many attempts. Try again in a minute."),
            }.get(r, pick("Не вдалося надіслати. Спробуйте пізніше.", "Could not send. Try later.")))
        poll()

    def _open_bug(self):
        """1.27.18: квадрат «Повідомити про помилку» - текст, контакт (необов'язково), PGN партії (за бажанням)."""
        if not hasattr(self, "bug_box"):
            self.bug_box = OverlayBox(self, "🐞  Повідомити про помилку")
            body = ttk.Frame(self.bug_box.box, style="Panel.TFrame", padding=(18, 12))
            body.pack(fill="both", expand=True, padx=2, pady=(0, 2))
            self.bug_hint = ttk.Label(body, style="PanelMuted.TLabel", justify="left", wraplength=420)
            self.bug_hint.pack(anchor="w")
            self.bug_text = tk.Text(body, width=52, height=7, wrap="word", bg="#2b2926", fg=FG, insertbackground=FG,
                                    bd=0, relief="flat", padx=8, pady=6, font=("Segoe UI", 10),
                                    highlightthickness=1, highlightbackground=BORDER, highlightcolor=ACCENT)
            self.bug_text.pack(fill="both", expand=True, pady=(8, 8))
            self.bug_contact_lbl = ttk.Label(body, style="Panel.TLabel")
            self.bug_contact_lbl.pack(anchor="w")
            self.bug_contact = tk.StringVar()
            ttk.Entry(body, textvariable=self.bug_contact, width=40).pack(anchor="w", fill="x", pady=(2, 8))
            self.bug_pgn_var = tk.BooleanVar(value=False)
            Switch(body, "Додати поточну партію (PGN)", self.bug_pgn_var).pack(anchor="w", pady=(0, 6))
            self.bug_status = ttk.Label(body, style="PanelMuted.TLabel", wraplength=420)
            self.bug_status.pack(anchor="w", pady=(0, 6))
            btns = ttk.Frame(body, style="Panel.TFrame")
            btns.pack(fill="x")
            RButton(btns, text="🐙 Через GitHub", style="Small.TButton",
                    command=lambda: webbrowser.open(bug_report_url(
                        f"Windows (build {sys.getwindowsversion().build})"))).pack(side="left")
            self.bug_send_btn = RButton(btns, text="Надіслати", style="Accent.TButton", command=self._send_bug)
            self.bug_send_btn.pack(side="right")
            RButton(btns, text="Скасувати", style="Small.TButton",
                    command=self.bug_box.hide).pack(side="right", padx=(0, 8))
            if STATE["lang"] == "en":
                self._apply_lang()
        self.bug_box.title.configure(text=pick("🐞  Повідомити про помилку", "🐞  Report a bug"))
        self.bug_hint.configure(text=pick("Опишіть, що сталося і що ви робили перед цим. Звіт отримає автор програми.",
                                          "Describe what happened and what you did before it. "
                                          "The report goes to the author of the app."))
        self.bug_contact_lbl.configure(text=pick("Як з вами зв'язатися (необов'язково): Telegram, пошта…",
                                                 "How to contact you (optional): Telegram, email…"))
        self.bug_status.configure(text="")
        self.bug_send_btn.configure(state="normal")
        self.bug_box.show()
        self.bug_text.focus_set()

    def _bug_pgn(self):
        try:
            res = self.result
            if not res or not res.get("moves") or res.get("partial"):
                return str(self.game) if self.game is not None else ""   # аналіз ще йде - партія як є
            headers = {} if res.get("free") or self.game is None else dict(self.game.headers)
            return chapter_pgn({"name": "bug", "headers": headers, "result": res, "lines": self.lines,
                                "notes": {}, "shapes": {}})
        except Exception:  # noqa: BLE001
            return ""

    def _send_bug(self):
        text = self.bug_text.get("1.0", "end").strip()
        if len(text) < 3:
            self.bug_status.configure(text=pick("Напишіть кілька слів про проблему.",
                                                "Write a few words about the problem."))
            return
        pgn = self._bug_pgn() if self.bug_pgn_var.get() else ""
        contact = self.bug_contact.get().strip()
        self.bug_send_btn.configure(state="disabled")
        self.bug_status.configure(text=pick("Надсилаю…", "Sending…"))
        out = queue.Queue()
        threading.Thread(target=lambda: out.put(send_bug_report(text, contact, pgn)), daemon=True).start()

        def poll():
            try:
                r = out.get_nowait()
            except queue.Empty:
                self.after(200, poll)
                return
            if r is True:
                self.bug_text.delete("1.0", "end")
                self.bug_status.configure(text=pick("✓ Дякуємо! Звіт надіслано.", "✓ Thank you! The report was sent."))
                self.after(1800, self.bug_box.hide)
                return
            self.bug_send_btn.configure(state="normal")
            self.bug_status.configure(text={
                "net": pick("Немає з'єднання з інтернетом. Спробуйте пізніше або через GitHub.",
                            "No internet connection. Try later or via GitHub."),
                "rate": pick("Забагато звітів. Спробуйте за хвилину.", "Too many reports. Try again in a minute."),
            }.get(r, pick("Не вдалося надіслати. Спробуйте через GitHub.", "Could not send. Try via GitHub.")))
        poll()

    # ---------- 1.28.0: «🧩 Тренування» ----------
    def _pz_hide(self):
        pz = getattr(self, "_puzzle", None)
        return bool(pz) and not pz.get("solved") and not pz.get("shown")

    def _puzzles_collect(self, res):
        """Після аналізу партії - позиції з поганими ходами стають задачами (лише гравця chess.com, якщо він у партії)."""
        try:
            s = res.get("summary") or {}
            me, nick = None, (getattr(self, "_cc_user", "") or "").strip().lower()
            if nick and nick == str(s.get("white") or "").lower():
                me = True
            elif nick and nick == str(s.get("black") or "").lower():
                me = False
            n = puzzles_add(puzzles_from_result(res, me))
            if n:
                self.status_var.set(self.status_var.get() + "  ·  " + pick(f"🧩 нових задач: {n}", f"🧩 new puzzles: {n}"))
        except Exception:  # noqa: BLE001
            pass

    def _build_puzzle_card(self):
        card = Card(self._right, pad=(14, 10))
        self.pz_card = card
        self.pz_title = tk.Label(card.body, bg=PANEL, fg=MUTED, font=fsemi(9), anchor="w")
        self.pz_title.pack(fill="x")
        self.pz_text = tk.Label(card.body, bg=PANEL, fg=FG, font=("Segoe UI", 11), anchor="w", justify="left",
                                wraplength=460)
        self.pz_text.pack(fill="x", pady=(4, 8))
        self.pz_text.bind("<Configure>", lambda e: self.pz_text.configure(wraplength=max(200, e.width - 8)))
        row = tk.Frame(card.body, bg=PANEL)
        row.pack(fill="x")
        self.pz_hint_btn = RButton(row, text="💡", command=self._puzzle_hint)
        self.pz_hint_btn.pack(side="left")
        self.pz_show_btn = RButton(row, text="✔", command=self._puzzle_show)
        self.pz_show_btn.pack(side="left", padx=(6, 0))
        self.pz_next_btn = RButton(row, text="⏭", kind="accent", command=self.puzzle_start)
        self.pz_next_btn.pack(side="left", padx=(6, 0))
        self.pz_exit_btn = RButton(row, text="✕", command=self._puzzle_exit)
        self.pz_exit_btn.pack(side="right")

    def puzzle_start(self):
        """Наступна задача (кнопка «🧩 Тренування» і «Наступна»)."""
        if self._bot_live():
            self.status_var.set(pick("Спершу завершіть партію з ботом.", "Finish the game with the bot first."))
            return
        tele_count("f.puzzle")
        now = time.time()
        d = puzzles_load()
        cur = getattr(self, "_puzzle", None)
        p = puzzle_next(d, now, skip=cur["id"] if cur and len(d["list"]) > 1 else None) or puzzle_next(d, now)
        if p is None:
            if not d["list"]:
                msg = pick("Задач ще немає. Проаналізуйте свої партії - позиції з помилками стануть задачами.",
                           "No puzzles yet. Analyze your games - positions with mistakes become puzzles.")
            else:
                nxt = min(x.get("due", 0) for x in d["list"])
                days = max(1, round((nxt - now) / 86400))
                msg = pick(f"На сьогодні все розв'язано! Наступна задача - через {days} дн.",
                           f"All done for today! Next puzzle in {days} day(s).")
            if cur:
                self._puzzle["solved"] = True
                self._puzzle_render(msg)
            else:
                messagebox.showinfo(trd("🧩  Тренування", "🧩  Training"), msg)
            return
        due_now = sum(1 for x in d["list"] if x.get("due", 0) <= now)
        res = {"free": True, "fens": [p["fen"]], "evals": [0], "pos_info": [None], "moves": [], "book_path": [False],
               "depth": None,
               "summary": {"white": "Білі", "black": "Чорні", "white_rating": None, "black_rating": None,
                           "white_acc": 0.0, "black_acc": 0.0, "white_counts": {}, "black_counts": {},
                           "result": "*", "opening": None}}
        self._pz_loading = True
        try:
            self._new_doc()
            self._puzzle = dict(p, res=res, tried=False, solved=False, shown=False, arrow=None, left=due_now)
            self._start_free(res)
        finally:
            self._pz_loading = False
        white = chess.Board(p["fen"]).turn == chess.WHITE
        if white == self.board.flipped:          # сторона, що ходить, - знизу
            self.flip_board()
        if not hasattr(self, "pz_card"):
            self._build_puzzle_card()
        if self._graph_box.winfo_manager():
            self._graph_box.pack_forget()
        if not self.pz_card.winfo_manager():
            self.pz_card.pack(fill="x", pady=(0, 10), before=self._mid)
        self._puzzle_render()
        self._puzzle_precalc(res)

    def _puzzle_precalc(self, res):
        """1.28.2: поки гравець думає - Stockfish рахує позицію задачі (тоді хід оцінюється вдвічі швидше)."""
        path, depth = self.engine_var.get().strip().strip('"'), self._depth()
        if not path:
            return

        def work():
            try:
                with self.live.lock:
                    if self.result is not res or res["pos_info"][0] is not None:
                        return
                    pe = pos_eval(_analyse(self.live.get(path), chess.Board(res["fens"][0]),
                                           chess.engine.Limit(depth=depth)), depth)
                    res["pos_info"][0] = pe
                    v = self.var
                    if v is not None and v["base"] == 0 and v["pes"] and v["pes"][0] is None:
                        v["pes"][0] = pe
            except Exception:  # noqa: BLE001
                pass
        threading.Thread(target=work, daemon=True).start()

    def _puzzle_instant(self, v, row):
        """1.28.2: зіграно саме записаний найкращий хід - зараховуємо одразу, не чекаючи Stockfish."""
        pz = self._puzzle
        if pz["solved"] or pz["shown"] or self.result is not pz["res"] or v["base"] != 0 or v["rows"][0] is not row \
                or row["uci"] != pz["best"]:
            return
        pz["solved"] = True
        first = not pz["tried"]
        if first:
            puzzle_result(puzzles_load(), pz["id"], True, time.time())
            tele_count("pz.ok")
        self._puzzle_render(pick(f"✓ Правильно! {row['san']}" + ("" if first else " (не з першої спроби)")
                                 + " - тисніть «Наступна».",
                                 f"✓ Correct! {row['san']}" + ("" if first else " (not on the first try)")
                                 + " - press «Next»."))

    def _puzzle_render(self, text=None):
        pz = self._puzzle
        white = chess.Board(pz["fen"]).turn == chess.WHITE
        qn = pick("пропущений геніальний", "missed brilliant") if pz["q"] == "missed" else qname(pz["q"]).lower()
        self.pz_title.configure(text=pick(f"🧩  ТРЕНУВАННЯ  ·  у черзі: {pz['left']}", f"🧩  TRAINING  ·  in queue: {pz['left']}"))
        if text is None:
            text = (pick(f"Знайдіть найкращий хід за {'білих' if white else 'чорних'}.",
                         f"Find the best move for {'White' if white else 'Black'}.")
                    + "\n" + pick(f"Партія {pz['src']}, хід {pz['move']} - там зіграно {pz['played']} ({qn}).",
                                  f"Game {pz['src']}, move {pz['move']} - {pz['played']} was played ({qn})."))
        self.pz_text.configure(text=text)
        self.pz_hint_btn.configure(text=pick("💡  Підказка", "💡  Hint"),
                                   state="disabled" if pz["solved"] or pz["shown"] else "normal")
        self.pz_show_btn.configure(text=pick("✔  Розв'язок", "✔  Solution"),
                                   state="disabled" if pz["solved"] or pz["shown"] else "normal")
        self.pz_next_btn.configure(text=pick("⏭  Наступна", "⏭  Next"))
        self.pz_exit_btn.configure(text=pick("✕  Вийти", "✕  Exit"))

    def _puzzle_san(self):
        b = chess.Board(self._puzzle["fen"])
        try:
            return b.san(chess.Move.from_uci(self._puzzle["best"]))
        except ValueError:
            return self._puzzle["best"]

    def _puzzle_hint(self):
        pz = getattr(self, "_puzzle", None)
        if not pz or pz["solved"]:
            return
        b = chess.Board(pz["fen"])
        mv = chess.Move.from_uci(pz["best"])
        names = {chess.PAWN: ("пішак", "pawn"), chess.KNIGHT: ("кінь", "knight"), chess.BISHOP: ("слон", "bishop"),
                 chess.ROOK: ("тура", "rook"), chess.QUEEN: ("ферзь", "queen"), chess.KING: ("король", "king")}
        nm = pick(*names[b.piece_type_at(mv.from_square)])
        if not pz["tried"]:
            pz["tried"] = True                  # з підказкою задача не зараховується як розв'язана з першого разу
            puzzle_result(puzzles_load(), pz["id"], False, time.time())
        self._puzzle_render(pick(f"💡 Ходить {nm} з {chess.square_name(mv.from_square)}.",
                                 f"💡 Move the {nm} on {chess.square_name(mv.from_square)}."))

    def _puzzle_show(self):
        pz = getattr(self, "_puzzle", None)
        if not pz or pz["solved"]:
            return
        if not pz["tried"]:
            pz["tried"] = True
            puzzle_result(puzzles_load(), pz["id"], False, time.time())
        pz["shown"] = True
        if self.var is not None:                 # 1.28.2: прибрати свій хід і зіграти розв'язок на дошці
            self._clear_var()
            self.goto(0, animate=False)
        self._on_user_move(pz["best"], False)
        self._puzzle_render(pick(f"Розв'язок: {self._puzzle_san()}. Задача повернеться пізніше.",
                                 f"Solution: {self._puzzle_san()}. The puzzle will come back later."))

    def _puzzle_check(self, row):
        """Оцінено перший хід у позиції задачі - правильно чи ні."""
        pz = self._puzzle
        v = self.var
        if pz["solved"] or pz["shown"] or self.result is not pz["res"] or v is None or v["base"] != 0 or not v["rows"] \
                or v["rows"][0] is not row or row.get("pending"):
            return
        ok = row.get("uci") == pz["best"] or row.get("quality") in PUZZLE_OK
        if ok:
            pz["solved"] = True
            first = not pz["tried"]
            if first:
                puzzle_result(puzzles_load(), pz["id"], True, time.time())
                tele_count("pz.ok")
            self._puzzle_render(pick(f"✓ Правильно! {row['san']}" + ("" if first else " (не з першої спроби)")
                                     + " - тисніть «Наступна».",
                                     f"✓ Correct! {row['san']}" + ("" if first else " (not on the first try)")
                                     + " - press «Next»."))
        else:
            if not pz["tried"]:
                pz["tried"] = True
                puzzle_result(puzzles_load(), pz["id"], False, time.time())
                tele_count("pz.fail")
            self._puzzle_render(pick(f"✗ {row['san']} - {qname(row['quality']).lower()}. Поверніть хід (↶) і спробуйте ще, "
                                     "або подивіться розв'язок.",
                                     f"✗ {row['san']} - {qname(row['quality']).lower()}. Take the move back (↶) and try "
                                     "again, or see the solution."))

    def _puzzle_hide(self):
        self._puzzle = None
        if hasattr(self, "pz_card") and self.pz_card.winfo_manager():
            self.pz_card.pack_forget()
        if not self._graph_box.winfo_manager() and not self.study_panel.winfo_manager():
            self._graph_box.pack(fill="x", pady=(0, 10), before=self._mid)

    def _puzzle_exit(self):
        self._puzzle_hide()
        self._start_free()

    def _edit_comment(self, key, line, j):
        if not hasattr(self, "comment_box"):
            self._build_comment_box()
        for b in (self.settings, self.changelog, self.studies_box, self.update_box, self.donate_box):
            b.hide()
        self._comment_key = key
        self.comment_box.title.configure(text=pick("💬  Коментар", "💬  Comment"))
        self.comment_title.configure(text=self._move_title(key, line, j))
        self.comment_text.delete("1.0", "end")
        self.comment_text.insert("1.0", self.notes.get(key, ""))
        if not self.comment_box.is_open:
            self.comment_box.show()
        self.comment_text.focus_set()

    def _set_comment(self, key, text):
        if key is None:
            return
        text = (text or "").strip()
        if text:
            self.notes[key] = text
        else:
            self.notes.pop(key, None)
        if hasattr(self, "comment_box"):
            self.comment_box.hide()
        self._render_lines()
        self._refresh_selection()
        self._doc_changed()

    def _refresh_selection(self):
        """Після перемальовування списку - знову підсвітити хід, що на дошці."""
        v = self.var
        if v is not None and v["index"] >= 1 and any(ln is v for ln in self.lines):
            self.moves_view.select(ply=None, node=self._line_key(v, v["index"]))
        elif v is not None:
            self.moves_view.select(ply=v["base"])
        else:
            self.moves_view.select(ply=self.index)

    def promote_line(self, line, j):
        """«Зробити основним»: варіант стає головною лінією, колишнє продовження - варіантом (як на lichess).
        Коментарі й стрілки переходять разом з позиціями (ключі перераховуються за шляхом ходів)."""
        res = self.result
        if not res or not any(ln is line for ln in self.lines):
            return
        if any(r.get("pending") for ln in self.lines for r in ln["rows"]):
            messagebox.showinfo(trd("Підказка", "Tip"), pick("Зачекайте, поки Stockfish оцінить ходи варіантів.",
                                                            "Please wait until Stockfish evaluates the variation moves."))
            return
        target = line["base"] + j
        if not res["moves"]:
            # вільна гра: головна лінія - перший варіант; ставимо цей варіант першим
            i = next(i for i, ln in enumerate(self.lines) if ln is line)
            self.lines.insert(0, self.lines.pop(i))
            self._render_lines()
            self._refresh_selection()
            self._doc_changed()
            return
        main, data, paths = self._doc_paths()
        new_main = tuple(main[:line["base"]] + [r["uci"] for r in line["rows"]])
        self._apply_paths(main, data, paths, new_main, new_main[:target])

    def _doc_paths(self):
        """Усі позиції документа як шляхи ходів від початку: (головна лінія, дані позицій, шляхи гілок)."""
        res = self.result
        main = [mv["uci"] for mv in res["moves"]]
        data = {}
        for k in range(1, len(main) + 1):
            data[tuple(main[:k])] = (res["moves"][k - 1], res["fens"][k], res["pos_info"][k], res["book_path"][k])
        paths = [tuple(main)]
        for ln in self.lines:
            pre = main[:ln["base"]]
            us = [r["uci"] for r in ln["rows"]]
            for jj in range(1, len(us) + 1):
                bp = ln["book_path"][jj] if jj < len(ln["book_path"]) else False
                data.setdefault(tuple(pre + us[:jj]), (ln["rows"][jj - 1], ln["fens"][jj], ln["pes"][jj], bp))
            paths.append(tuple(pre + us))
        return main, data, paths

    def _apply_paths(self, main, data, paths, new_main, target_path, cut=None):
        """Перебудовує партію й варіанти з шляхів: new_main - нова головна лінія, решта шляхів - варіанти.
        cut - шлях видаленого ходу (коментарі/стрілки цієї гілки зникають). Після - позиція target_path."""
        res = self.result

        def common(p):
            c = 0
            while c < len(p) and c < len(new_main) and p[c] == new_main[c]:
                c += 1
            return c

        n = len(new_main)
        moves = [data[new_main[:k]][0] for k in range(1, n + 1)]
        fens = [res["fens"][0]] + [data[new_main[:k]][1] for k in range(1, n + 1)]
        pos_info = [res["pos_info"][0]] + [data[new_main[:k]][2] for k in range(1, n + 1)]
        evals = [res["evals"][0]] + [(pe or {}).get("cp", 0) for pe in pos_info[1:]]
        book = [res["book_path"][0]] + [bool(data[new_main[:k]][3]) for k in range(1, n + 1)]
        counts = {True: {}, False: {}}
        accs = {True: [], False: []}
        for mv in moves:
            wht = mv["label"].endswith(".")
            counts[wht][mv["quality"]] = counts[wht].get(mv["quality"], 0) + 1
            if mv.get("acc") is not None:
                accs[wht].append(mv["acc"])
        summary = dict(res["summary"], white_counts=counts[True], black_counts=counts[False],
                       white_acc=game_accuracy(accs[True]), black_acc=game_accuracy(accs[False]))
        new_res = dict(res, moves=moves, fens=fens, pos_info=pos_info, evals=evals, book_path=book, summary=summary)

        # варіанти: усі шляхи (стара головна теж), крім тих, що є початком нової головної чи іншого шляху
        uniq = list(dict.fromkeys(paths))
        keep = [p for p in uniq if p != new_main[:len(p)]
                and not any(q != p and q[:len(p)] == p for q in uniq)]
        new_lines = []
        for i, p in enumerate(keep, start=1):
            b = common(p)
            rows = [data[p[:q]][0] for q in range(b + 1, len(p) + 1)]
            prev = moves[b - 1] if b >= 1 else None
            base_opening = ""
            if book[b]:
                for mv in reversed(moves[:b]):
                    if mv.get("opening"):
                        base_opening = mv["opening"]
                        break
            new_lines.append({
                "base": b, "rows": rows, "index": 0,
                "fens": [fens[b]] + [data[p[:q]][1] for q in range(b + 1, len(p) + 1)],
                "pes": [pos_info[b]] + [data[p[:q]][2] for q in range(b + 1, len(p) + 1)],
                "prev_drop": prev.get("drop", 0.0) if prev else 0.0,
                "prev_cap": prev.get("cap_sq") if prev else None,
                "book_path": [book[b]] + [bool(data[p[:q]][3]) for q in range(b + 1, len(p) + 1)],
                "base_opening": base_opening,
                "opening": (rows[-1].get("opening") if rows else "") or base_opening,
                "id": i,
            })

        def path_of(key):
            parts = str(key).split("/")
            return tuple(main[:int(parts[0])] + parts[1:])

        def key_of(p):
            b = common(p)
            return str(b) if b == len(p) else "/".join([str(b)] + list(p[b:]))

        for d in (self.notes, self.shapes):           # ті самі об'єкти, що й у розділі дослідження
            moved = {key_of(path_of(k)): v for k, v in d.items()
                     if not (cut and path_of(k)[:len(cut)] == tuple(cut))}
            d.clear()
            d.update(moved)
        self._clear_var()
        self.lines[:] = new_lines
        if self.game is not None:                     # партія для повторного аналізу - теж нова головна лінія
            g = chess.pgn.Game()
            for hk, hv in self.game.headers.items():
                g.headers[hk] = hv
            node = g
            for u in new_main:
                node = node.add_variation(chess.Move.from_uci(u))
            self.game = g
        if res.get("free") and not new_main:
            self._render_lines()
        else:
            self._show_results(new_res, save=True)
        self._go_path(tuple(target_path))
        self._doc_changed()

    def _go_path(self, path):
        """Показати позицію за шляхом ходів: на головній лінії - goto, інакше - відкрити варіант."""
        main = [mv["uci"] for mv in self.result["moves"]]
        if list(path) == main[:len(path)]:
            self.goto(len(path), animate=False)
            return
        for ln in self.lines:
            full = main[:ln["base"]] + [r["uci"] for r in ln["rows"]]
            if full[:len(path)] == list(path) and len(path) > ln["base"]:
                self._open_line(ln, len(path) - ln["base"])
                return
        self.goto(0, animate=False)

    def delete_from(self, line, j, k=None):
        """«Видалити з цього місця» (як на lichess): хід і все після нього в цій гілці зникають."""
        res = self.result
        if not res:
            return
        if any(r.get("pending") for ln in self.lines for r in ln["rows"]):
            messagebox.showinfo(trd("Підказка", "Tip"), pick("Зачекайте, поки Stockfish оцінить ходи варіантів.",
                                                            "Please wait until Stockfish evaluates the variation moves."))
            return
        main, data, paths = self._doc_paths()
        if line is not None:
            cut = tuple(main[:line["base"]] + [r["uci"] for r in line["rows"][:j]])
        else:
            cut = tuple(main[:k])
        if not cut:
            return
        n = len(cut)
        trim = lambda p: p[:n - 1] if p[:n] == cut else p      # noqa: E731
        self._apply_paths(main, data, [trim(p) for p in paths], trim(tuple(main)), cut[:-1], cut=cut)

    def _render_lines(self):
        """Збережені варіанти - рядки «↳» у списку ходів, під ходом, замість якого їх зіграно."""
        self.moves_view.notes = self.notes
        self.moves_view.set_data(self.result, self.lines)

    def _alternatives(self, line, j):
        """Інші збережені варіанти, що йдуть тим самим шляхом до j-го ходу, але j-м ходом грають інше
        (по одному на кожен інший хід) - це «підрозділи» j-го ходу в таблиці «Ваш варіант»."""
        pre = [r["uci"] for r in line["rows"][:j - 1]]
        mine = line["rows"][j - 1]["uci"]
        out, seen = [], set()
        for ln in self.lines:
            if ln is line or ln["base"] != line["base"] or len(ln["rows"]) < j:
                continue
            u = ln["rows"][j - 1]["uci"]
            if u == mine or u in seen or [r["uci"] for r in ln["rows"][:j - 1]] != pre:
                continue
            seen.add(u)
            out.append(ln)
        return out

    def _fill_vtree(self, line):
        self.vtree.delete(*self.vtree.get_children())
        self._vtree_alts = {}
        for j, row in enumerate(line["rows"], start=1):
            pe = line["pes"][j]
            if row.get("pending"):                     # ще оцінюється
                self.vtree.insert("", "end", iid=str(j), values=(row["label"], row["san"], "", "…"))
            else:
                self.vtree.insert("", "end", iid=str(j), open=True,
                                  values=(row["label"], row["san"], fmt_eval(pe["cp"]) if pe else "",
                                          qname(row["quality"])),
                                  tags=(row["quality"],))
            # підрозділи: інші ходи замість цього (збережені варіанти-гілки), клік - відкрити гілку
            for k, alt in enumerate(self._alternatives(line, j)):
                ar = alt["rows"][j - 1]
                rest = [r["label"] + r["san"] if r["label"].endswith(".") else r["san"]
                        for r in alt["rows"][j:j + 3]]
                if len(alt["rows"]) > j + 3:
                    rest.append("…")
                last = next((p for p in reversed(alt["pes"]) if p), None)
                iid = f"A{j}_{k}"
                self._vtree_alts[iid] = (alt, j)
                self.vtree.insert(str(j), "end", iid=iid, text="↳",
                                  values=(ar["label"], ar["san"], fmt_eval(last["cp"]) if last else "",
                                          " ".join(rest)),
                                  tags=("alt",) + ((ar["quality"],) if ar.get("quality") else ()))

    def _open_line(self, line, j=1, animate=False):
        """Відкриває збережений варіант на його j-му ході."""
        if self._var_busy:
            return
        self._stop_play()
        if self.var is not line:
            self._var_token += 1
            self.var = line
            self.index = line["base"]
            self._show_var_bar()
            self._fill_vtree(line)
        line["index"] = max(0, min(len(line["rows"]), j))
        self._show_var_state(line["index"], animate)

    def _show_var_bar(self):
        """Кнопки варіанту над списком ходів (таблицю «Ваш варіант» з 1.18.7 замінено ходами в списку)."""
        if not self.var_bar.winfo_manager():
            self.var_bar.pack(fill="x", pady=(0, 8), before=self.tree_frame)

    def exit_var(self):
        if self.var is None:
            return
        base = self.var["base"]
        self._clear_var()
        self.goto(base, animate=False)

    def _clear_var(self):
        self.var = None
        self._var_token += 1
        self._deep_tok += 1
        self._var_busy = False
        self.var_frame.pack_forget()
        self.var_bar.pack_forget()
        self.vtree.delete(*self.vtree.get_children())
        self.board.interactive = bool(self.result)

    # ---------- відтворення партії
    def toggle_play(self):
        if not self.result:
            return
        if self.var is not None:
            self.exit_var()
        if self.playing:
            self._stop_play()
            return
        n = len(self.result["fens"]) - 1
        if self.index >= n:
            self.goto(0, animate=False)
        self.playing = True
        self.play_btn.config(text=tr("⏸ Пауза"))
        self._play_tick()

    def _play_tick(self):
        if not self.playing or not self.result:
            return
        n = len(self.result["fens"]) - 1
        if self.index >= n:
            self._stop_play()
            return
        self.step(1)
        self._play_after = self.after(900, self._play_tick)

    def _stop_play(self):
        self.playing = False
        if self._play_after is not None:
            try:
                self.after_cancel(self._play_after)
            except Exception:
                pass
            self._play_after = None
        if hasattr(self, "play_btn"):
            self.play_btn.config(text=tr("▶ Грати"))

    def flip_board(self):
        self.board.flip()
        if self._names:
            self._set_names(*self._names)
        self._update_acc_labels()
        self.evalbar.set(self._current_cp(), self.board.flipped)
        self._doc_changed()                 # розділ дослідження пам'ятає, з якого боку дивились

    def _best_arrow(self, row, pe_now):
        """
        Стрілка найкращого ходу за налаштуванням arrow_var.
        row - щойно зіграний хід (або None), pe_now - оцінка поточної позиції (або None).
        """
        mode = self.arrow_var.get()
        if getattr(self, "_puzzle", None):    # 1.28.2: у тренуванні стрілки немає зовсім
            return None
        if self._bot_live():                  # у партії з ботом - лише взята підказка (1.25.0)
            return self._bot_hint_arrow()
        if mode == "hint":                    # що найкраще грати зараз
            return (pe_now or {}).get("best")
        if mode == "off" or not row or not row.get("best_uci"):
            return None
        if row.get("quality") == "Теорія":     # після теоретичного ходу «що було краще» не показуємо
            return None
        if mode == "all":                     # що було найкращим замість зіграного ходу
            if row["best_uci"] == row["uci"] or row.get("quality") in ("Найкращий", "Геніальний", "Чудовий"):
                return None                   # хід і так найкращий (або рівноцінний йому) - стрілка не потрібна
            return row["best_uci"]
        return row["best_uci"] if row["quality"] in BAD else None

    def _apply_panels(self):
        """Показує або ховає панель тренера і шкалу оцінки."""
        if self.coach_var.get():
            if not self.coach_card.winfo_manager():
                self.coach_card.pack(fill="x", pady=(0, 8), before=self._bottom_anchor)
        else:
            self.coach_card.pack_forget()
        if self.evalbar_var.get():
            if not self.evalbar.winfo_manager():
                self.evalbar.pack(side="left", padx=(0, 6), before=self.board)
        else:
            self.evalbar.pack_forget()

    # ---------- налаштування (панель у головному вікні)
    ARROW_LABELS = {"off": ("Вимкнено", "Off"),
                    "bad": ("Після помилок", "After mistakes"),
                    "all": ("Після кожного ходу", "After every move"),
                    "hint": ("Найкращий хід зараз", "Best move now")}

    def _arrow_labels(self):
        i = 1 if STATE["lang"] == "en" else 0
        return [self.ARROW_LABELS[mode][i] for mode in ARROW_MODES]

    def _update_arrow_combo(self):
        """Підписи режимів стрілки поточною мовою і вибраний режим."""
        labels = self._arrow_labels()
        self.arrow_cb.configure(values=labels)
        self.arrow_shown.set(labels[ARROW_MODES.index(self.arrow_var.get())])

    def _on_arrow_pick(self, _event=None):
        labels = self._arrow_labels()
        if self.arrow_shown.get() in labels:
            self.arrow_var.set(ARROW_MODES[labels.index(self.arrow_shown.get())])
        self.arrow_cb.selection_clear()

    def toggle_settings(self):
        """Кнопка ⚙: показує налаштування квадратом по центру вікна або ховає їх."""
        self.changelog.hide()
        self.studies_box.hide()
        self.update_box.hide()
        self.donate_box.hide()
        self.settings.toggle()
        if self.settings.is_open:
            tele_count("f.settings")
            self._load_stats()

    def _load_stats(self):
        """Статистика (GitHub, Telegram) - у фоні, не частіше разу на 10 хвилин."""
        self._render_stats()
        if self._stats_busy or (self._stats is not None and time.time() - self._stats_time < 600):
            return
        self._stats_busy = True
        box = {}

        def work():
            try:
                box["v"] = fetch_site_stats()
            except Exception:  # noqa: BLE001
                box["v"] = None
            try:                                   # 1.27.12: загальна статистика програми
                box["a"] = fetch_app_stats()
            except Exception:  # noqa: BLE001
                box["a"] = None
            box["done"] = True

        def poll():
            if not box.get("done"):
                self.after(200, poll)
                return
            self._stats_busy = False
            if box["v"] is not None:
                self._stats, self._stats_time = box["v"], time.time()
                if box.get("a"):
                    self._stats["app"] = box["a"]
            elif self._stats is None:
                self._stats = False
            self._render_stats()

        threading.Thread(target=work, daemon=True).start()
        self.after(200, poll)

    def _render_stats(self):
        if not hasattr(self, "stats_label"):
            return
        s = getattr(self, "_stats", None)
        if s is None:
            txt = pick("Завантажую…", "Loading…")
        elif s is False:
            txt = pick("Не вдалося отримати статистику. Перевірте інтернет.", "Could not get the statistics. Check your internet connection.")
        else:
            g, tg = s.get("github") or {}, s.get("telegram") or {}
            views, visitors = g.get("views", 0), g.get("visitors", 0)
            subs, tgv = tg.get("subscribers", 0), tg.get("views", 0)
            upd = s.get("updated", "")
            v_uk, v_en = ("перегляд", "перегляди", "переглядів"), ("view", "views")
            n_v = _plural(views, v_uk, v_en)
            n_p = _plural(visitors, ("відвідувач", "відвідувачі", "відвідувачів"), ("visitor", "visitors"))
            n_s = _plural(subs, ("підписник", "підписники", "підписників"), ("subscriber", "subscribers"))
            n_t = _plural(tgv, v_uk, v_en)
            txt = pick(f"🐙 GitHub: {n_v} сторінки, {n_p}\n✈ Telegram (t.me/chessanalyser): {n_s}, {n_t} дописів\n"
                       f"(оновлено {upd})",
                       f"🐙 GitHub: {n_v} of the page, {n_p}\n✈ Telegram (t.me/chessanalyser): {n_s}, {n_t} of posts\n"
                       f"(updated {upd})")
            if s.get("app"):
                try:
                    txt = app_stats_text(s["app"]) + "\n" + txt
                except Exception:  # noqa: BLE001
                    pass
        self.stats_label.configure(text=txt)

    def toggle_changelog(self):
        """Кнопка «Що нового»: список оновлень квадратом по центру вікна."""
        self.settings.hide()
        self.studies_box.hide()
        self.update_box.hide()
        self.donate_box.hide()
        if not self.changelog.is_open:
            self._render_changelog()          # поточною мовою
        self.changelog.toggle()

    def _build_changelog_box(self):
        self.changelog = OverlayBox(self, "✨  Що нового")
        body = ttk.Frame(self.changelog.box, style="Panel.TFrame", padding=(16, 12))
        body.pack(fill="both", expand=True, padx=2, pady=(0, 2))
        txt = tk.Text(body, width=66, height=22, wrap="word", bg=PANEL, fg=FG, bd=0, relief="flat",
                      font=("Segoe UI", 10), highlightthickness=0, padx=4, pady=2, cursor="arrow")
        sb = ttk.Scrollbar(body, orient="vertical", command=txt.yview)
        txt.configure(yscrollcommand=sb.set)
        txt.grid(row=0, column=0, sticky="nsew")
        sb.grid(row=0, column=1, sticky="ns", padx=(6, 0))
        txt.tag_configure("ver", font=fsemi(12), foreground=ACCENT, spacing1=12)
        txt.tag_configure("date", font=("Segoe UI", 9), foreground=MUTED)
        txt.tag_configure("item", lmargin1=8, lmargin2=22, spacing1=4)
        self.changelog_text = txt
        RButton(body, text="Закрити", style="Accent.TButton",
                command=self.changelog.hide).grid(row=1, column=0, columnspan=2, sticky="e", pady=(12, 0))
        body.columnconfigure(0, weight=1)
        self._render_changelog()

    def _render_changelog(self):
        """Список оновлень поточною мовою (новіші зверху)."""
        txt = self.changelog_text
        txt.configure(state="normal")
        txt.delete("1.0", "end")
        for i, (ver, date, items) in enumerate(changelog_view()):
            if i:
                txt.insert("end", "\n")
            txt.insert("end", pick(f"Версія {ver}", f"Version {ver}"), "ver")
            note = pick("  ·  поточна", "  ·  current") if ver == APP_VERSION else ""
            txt.insert("end", f"   {ymd_to_ydm(date)}{note}\n", "date")
            for uk, en in items:
                txt.insert("end", "•  " + pick(uk, en) + "\n", "item")
        txt.configure(state="disabled")
        txt.yview_moveto(0)

    # ---------- документ на дошці: партія + варіанти + коментарі + стрілки
    def _new_doc(self):
        """На дошці нова партія: свої варіанти, коментарі й стрілки починаються з нуля."""
        self._flush_save()
        if getattr(self, "_puzzle", None) and not getattr(self, "_pz_loading", False):
            self._puzzle_hide()              # 1.28.0: інша партія на дошці - тренування закінчилось
        self.bot = None                      # партія з ботом (якщо була) на цьому закінчується
        self._bot_ui_sync()
        self._doc_id += 1
        self.lines, self.notes, self.shapes = [], {}, {}   # нові об'єкти: старий розділ не чіпаємо
        self.chapter = None
        self.run_btn.config(state="normal")
        self.progress["value"] = 0
        self._render_study_panel()

    def _doc_changed(self, delay=0):
        """Щось змінилось у партії на дошці: якщо це розділ дослідження - зберігаємо."""
        if self.chapter is not None:
            self._autosave(delay)

    def _autosave(self, delay=0):
        if self.study is None:
            return
        if self._save_after is not None:
            self.after_cancel(self._save_after)
            self._save_after = None
        if delay:
            self._save_after = self.after(delay, self._save_study_now)
        else:
            self._save_study_now()

    def _flush_save(self):
        """Негайно записує відкладене збереження (перед зміною партії чи закриттям програми)."""
        if self._save_after is not None:
            self.after_cancel(self._save_after)
            self._save_after = None
            self._save_study_now()

    def _save_study_now(self):
        self._save_after = None
        if self.study is None or not self.study_path:
            return
        if self.chapter is not None:
            self.chapter["flipped"] = bool(self.board.flipped)
        try:
            save_study(self.study_path, self.study)
        except Exception as e:  # noqa: BLE001
            self.status_var.set(f"{tr('Не вдалося зберегти дослідження:')} {e}")

    def _on_shapes(self, shapes):
        """Гравець намалював або стер стрілку чи коло правою кнопкою миші."""
        if not self.result or self._var_busy:
            return
        key = self._node_key()
        if shapes:
            self.shapes[key] = shapes
        else:
            self.shapes.pop(key, None)
        self._doc_changed()

    def _node_title(self):
        """«12. Ne5» - позиція, до якої пишемо коментар."""
        v = self.var
        if v is not None and v["index"] >= 1:
            r = v["rows"][v["index"] - 1]
            return f"{r['label']} {r['san']}"
        k = v["base"] if v is not None else self.index
        if self.result and 1 <= k <= len(self.result["moves"]):
            m = self.result["moves"][k - 1]
            return f"{m['label']} {m['san']}"
        return tr("Початкова позиція")

    def _show_note(self):
        """(До 1.18.11 - поле «Коментар» у панелі дослідження; тепер коментарі - правою кнопкою на ході.)"""
        if not hasattr(self, "note_text"):
            return
        key = self._node_key() if self.result else None
        self._note_key = key
        self.note_title.set(pick("КОМЕНТАР", "COMMENT") + ("  ·  " + self._node_title() if key else ""))
        self.note_text.delete("1.0", "end")
        if key:
            self.note_text.insert("1.0", self.notes.get(key, ""))

    def _on_note_edit(self, _event=None):
        key = self._note_key
        if key is None:
            return
        txt = self.note_text.get("1.0", "end").strip()
        if txt == self.notes.get(key, ""):
            return
        if txt:
            self.notes[key] = txt
        else:
            self.notes.pop(key, None)
        self._doc_changed(delay=700)

    # ---------- дослідження: панель праворуч
    def _build_study_panel(self, parent):
        """Панель відкритого дослідження - стовпець ліворуч від дошки (як на lichess):
        назва, розділи, назва розділу й кнопки, коментар до ходу, експорт."""
        sp = Card(parent, pad=(12, 12), width=STUDY_COL_W, height=1)
        sp.pack_propagate(False)              # висоту задає вікно, а не вміст - щоб не розтягувати програму
        self.study_panel = sp
        inner = sp.body

        head = ttk.Frame(inner, style="Panel.TFrame")
        head.pack(fill="x")
        ttk.Label(head, text="📚  ДОСЛІДЖЕННЯ", style="Section.TLabel").pack(side="left")
        close = tk.Label(head, text="✕", bg=PANEL, fg=MUTED, cursor="hand2", font=("Segoe UI", 11))
        close.pack(side="right")
        close.bind("<Button-1>", lambda e: self.close_study())
        close.bind("<Enter>", lambda e: close.configure(fg=FG))
        close.bind("<Leave>", lambda e: close.configure(fg=MUTED))
        self.study_name_var = tk.StringVar()
        ttk.Entry(inner, textvariable=self.study_name_var, font=fsemi(11)).pack(fill="x", pady=(6, 10))
        self.study_name_var.trace_add("write", lambda *a: self._on_study_rename())

        # низ стовпця (пакується першим з side="bottom", щоб завжди було видно)
        foot = ttk.Frame(inner, style="Panel.TFrame")
        foot.pack(side="bottom", fill="x", pady=(10, 0))
        RButton(foot, text="⤓ Експорт PGN", style="Small.TButton",
                command=self.export_study).pack(side="left")
        RButton(foot, text="Усі дослідження", style="Small.TButton",
                command=self.toggle_studies).pack(side="left", padx=(6, 0))
        self.study_doc_var = tk.StringVar()
        self._study_doc_label = ttk.Label(inner, textvariable=self.study_doc_var, style="PanelMuted.TLabel",
                                          wraplength=STUDY_COL_W - 30, justify="left")
        self._study_doc_label.pack(side="bottom", anchor="w", pady=(4, 0))
        btns = ttk.Frame(inner, style="Panel.TFrame")
        btns.pack(side="bottom", fill="x", pady=(6, 0))
        self.add_chapter_btn = RButton(btns, text="➕ Новий розділ", style="Small.TButton",
                                       command=self.new_chapter)
        self.add_chapter_btn.pack(side="left")
        self.del_chapter_btn = RButton(btns, text="🗑 Видалити", style="Small.TButton",
                                       command=self.delete_chapter)
        self.del_chapter_btn.pack(side="left", padx=(6, 0))
        self.chapter_name_var = tk.StringVar()
        self.chapter_name_entry = ttk.Entry(inner, textvariable=self.chapter_name_var)
        self.chapter_name_entry.pack(side="bottom", fill="x", pady=(4, 0))
        self.chapter_name_var.trace_add("write", lambda *a: self._on_chapter_rename())
        ttk.Label(inner, text="Назва розділу", style="PanelMuted.TLabel").pack(side="bottom", anchor="w",
                                                                              pady=(10, 0))

        # розділи - решта висоти стовпця
        ttk.Label(inner, text="РОЗДІЛИ", style="Section.TLabel").pack(anchor="w")
        lf = ttk.Frame(inner, style="Panel.TFrame")
        lf.pack(fill="both", expand=True, pady=(4, 0))
        lb = tk.Listbox(lf, height=3, bg="#2b2926", fg=FG, bd=0, highlightthickness=0, relief="flat",
                        selectbackground="#3d5229", selectforeground="#ffffff", activestyle="none",
                        font=("Segoe UI", 10), exportselection=False)
        sb = ttk.Scrollbar(lf, orient="vertical", command=lb.yview)
        lb.configure(yscrollcommand=sb.set)
        lb.pack(side="left", fill="both", expand=True)
        sb.pack(side="right", fill="y")
        lb.bind("<<ListboxSelect>>", self._on_chapter_pick)
        self.chapter_list = lb

    def _after_layout_change(self):
        """Стовпець дослідження з'явився/зник - при «Auto» дошка підлаштовується під нову ширину."""
        if self.size_var.get() == "Auto":
            self.after(30, self._auto_size)

    def _show_summary_box(self):
        self._after_layout_change()
        if not self._graph_box.winfo_manager():
            self._graph_box.pack(fill="x", pady=(0, 10), before=self._mid)
        if not self.summary_box.winfo_manager():
            self.summary_box.pack(fill="x", anchor="n", before=self.info_card)

    def _show_study_panel(self):
        if not self.study_panel.winfo_manager():   # як на lichess: розділи | дошка | ходи
            self.study_panel.pack(side="left", fill="y", before=self._left, padx=(0, 16))
            self._after_layout_change()
        self.summary_box.pack_forget()             # «Оцінка партії» і графік у дослідженні не потрібні
        self._graph_box.pack_forget()
        self._render_study_panel()
        self._show_note()

    def _render_study_panel(self):
        """Оновлює панель: назва дослідження, розділи і який з них зараз на дошці."""
        st = self.study
        if st is None or not hasattr(self, "chapter_list"):
            return
        self._study_ui = True
        try:
            if self.study_name_var.get() != st.get("name", ""):
                self.study_name_var.set(st.get("name", ""))
            lb = self.chapter_list
            lb.delete(0, "end")
            active = None
            for i, ch in enumerate(st["chapters"]):
                lb.insert("end", f"{i + 1}. {ch.get('name') or '—'}")
                if ch is self.chapter:
                    active = i
            if active is not None:
                lb.selection_set(active)
                lb.see(active)
            ch = self.chapter
            self.chapter_name_var.set(ch.get("name", "") if ch else "")
            self.chapter_name_entry.configure(state="normal" if ch else "disabled")
            self.del_chapter_btn.configure(state="normal" if ch else "disabled")
            if ch is not None:
                self.study_doc_var.set(pick("Варіанти, коментарі й стрілки зберігаються самі.",
                                            "Variations, comments and arrows are saved automatically."))
            else:
                self.study_doc_var.set(pick("Партії на дошці немає в дослідженні. «Додати поточну партію» "
                                            "зробить її новим розділом.",
                                            "The game on the board isn't in the study. "
                                            "“Add current game” makes it a new chapter."))
        finally:
            self._study_ui = False

    def _on_study_rename(self):
        if self._study_ui or self.study is None:
            return
        self.study["name"] = self.study_name_var.get().strip()
        self._autosave(delay=800)

    def _on_chapter_rename(self):
        if self._study_ui or self.study is None or self.chapter is None:
            return
        name = self.chapter_name_var.get().strip()
        self.chapter["name"] = name
        for i, ch in enumerate(self.study["chapters"]):
            if ch is self.chapter:
                self._study_ui = True
                try:
                    self.chapter_list.delete(i)
                    self.chapter_list.insert(i, f"{i + 1}. {name or '—'}")
                    self.chapter_list.selection_set(i)
                finally:
                    self._study_ui = False
                break
        self._autosave(delay=800)

    def _on_chapter_pick(self, _event=None):
        if self._study_ui or self.study is None:
            return
        sel = self.chapter_list.curselection()
        if sel:
            self.open_chapter(sel[0])

    @staticmethod
    def _chapter_game(ch):
        """Партія розділу (заголовки PGN + ходи основної лінії) - щоб її можна було перерахувати."""
        res = ch["result"]
        game = chess.pgn.Game()
        for key, val in (ch.get("headers") or {}).items():
            game.headers[str(key)] = str(val)
        if res["fens"][0] != chess.STARTING_FEN and "FEN" not in game.headers:
            game.setup(chess.Board(res["fens"][0]))
        node = game
        for m in res["moves"]:
            node = node.add_main_variation(chess.Move.from_uci(m["uci"]))
        return game

    def open_chapter(self, i):
        """Показує на дошці розділ дослідження з усіма його варіантами, коментарями й стрілками."""
        st = self.study
        if st is None or not 0 <= i < len(st["chapters"]):
            return
        ch = st["chapters"][i]
        if ch is self.chapter:
            return
        try:
            res = ch["result"]
            if not res["fens"] or len(res["fens"]) != len(res["moves"]) + 1:
                raise ValueError
            game = None if res.get("free") else self._chapter_game(ch)
        except Exception:  # noqa: BLE001
            messagebox.showerror(trd("Помилка", "Error"), tr("Розділ пошкоджений, його не вдалося відкрити."))
            self._render_study_panel()
            return
        self._stop_play()
        self._clear_var()
        self._new_doc()
        self.lines = ch.setdefault("lines", [])
        self.notes = ch.setdefault("notes", {})
        self.shapes = ch.setdefault("shapes", {})
        for i in range(len(self.lines) - 1, -1, -1):  # ходи, які не встигли оцінити, - відкидаємо
            ln = self.lines[i]
            p = next((k for k, r in enumerate(ln["rows"]) if r.get("pending")), None)
            if p is None:
                continue
            del ln["rows"][p:]
            del ln["fens"][p + 1:]
            del ln["pes"][p + 1:]
            del ln["book_path"][p + 1:]
            if not ln["rows"]:
                del self.lines[i]
        self.chapter = ch
        st["current"] = i
        if bool(ch.get("flipped")) != self.board.flipped:
            self.board.flip()
        if game is None:
            self._start_free(res=res)
        else:
            h = ch.get("headers") or {}
            self.game = game
            self._reset_view()
            self._set_names(h.get("White", "Білі"), h.get("WhiteElo", ""),
                            h.get("Black", "Чорні"), h.get("BlackElo", ""))
            self._show_results(res, save=False)
        self.status_var.set(f"📚  {st.get('name') or '—'}  ·  {ch.get('name') or '—'}")
        self._render_study_panel()
        self._show_note()

    def _add_doc_to_study(self, st):
        """Партія на дошці (разом з варіантами, коментарями, стрілками) стає розділом дослідження."""
        res = self.result
        if res.get("free"):
            headers = {}
            name = f"{pick('Розділ', 'Chapter')} {len(st['chapters']) + 1}"
        else:
            headers = dict(self.game.headers) if self.game is not None else {}
            name = f"{headers.get('White', '?')} – {headers.get('Black', '?')}"
        ch = {"name": name, "headers": headers, "result": res, "lines": self.lines,
              "notes": self.notes, "shapes": self.shapes, "flipped": bool(self.board.flipped)}
        st["chapters"].append(ch)
        st["current"] = len(st["chapters"]) - 1
        self.chapter = ch

    def new_chapter(self):
        """«Новий розділ» (з 1.18.10): порожній розділ з початковою позиції, одразу на дошці."""
        if self.study is None:
            return
        self._start_free()                  # нова партія з початкової позиції (старий розділ лишається цілий)
        self._add_doc_to_study(self.study)
        self._save_study_now()
        self._render_study_panel()
        self._show_note()

    def add_chapter(self):
        """«Додати поточну партію»: партія на дошці стає новим розділом відкритого дослідження."""
        if self.study is None or self.chapter is not None:
            return
        if not self.result:
            messagebox.showinfo(trd("Підказка", "Tip"), tr("Зачекайте, поки закінчиться аналіз партії."))
            return
        self._add_doc_to_study(self.study)
        self._save_study_now()
        self._render_study_panel()
        self._show_note()

    def delete_chapter(self):
        st, ch = self.study, self.chapter
        if st is None or ch is None:
            return
        name = ch.get("name") or "—"
        if not messagebox.askyesno(
                trd("Видалити розділ", "Delete chapter"),
                pick(f"Видалити розділ «{name}» з дослідження? Партія лишиться на дошці.",
                     f"Delete the chapter “{name}” from the study? The game stays on the board.")):
            return
        st["chapters"] = [c for c in st["chapters"] if c is not ch]
        st["current"] = 0
        self.chapter = None
        self._save_study_now()
        self._render_study_panel()

    def close_study(self):
        """Закриває дослідження (усе вже збережено); партія лишається на дошці."""
        self._flush_save()
        self.study = self.study_path = self.chapter = None
        self.study_panel.pack_forget()
        self._show_summary_box()

    def export_study(self):
        """Усі розділи - в один PGN-файл (його можна відкрити на lichess)."""
        st = self.study
        if st is None:
            return
        if not st["chapters"]:
            messagebox.showinfo(trd("Підказка", "Tip"), tr("У дослідженні ще немає розділів."))
            return
        self._flush_save()
        path = filedialog.asksaveasfilename(
            title=tr("Зберегти дослідження як PGN"), defaultextension=".pgn",
            initialfile=_safe_filename(st.get("name") or "study") + ".pgn",
            filetypes=[("PGN", "*.pgn"), (tr("Усі файли"), "*.*")])
        if not path:
            return
        try:
            text = "\n\n".join(chapter_pgn(ch, st.get("name", "")) for ch in st["chapters"]) + "\n"
            with open(path, "w", encoding="utf-8") as f:
                f.write(text)
        except Exception as e:  # noqa: BLE001
            messagebox.showerror(trd("Помилка", "Error"), str(e))
            return
        self.status_var.set(f"{tr('Збережено:')} {path}")

